import { Book } from "@/lib/types";

export const exodus: Book = {
  id: "exodus",
  name: "2. Mose (Exodus)",
  shortName: "2. Mose",
  testament: "old",
  introduction: `Gott befreit sein Volk\n**Das zweite Buch Mose** wird auch \"Exodus\" genannt, \"Auszug\", denn es beinhaltet die Geschichte vom Auszug des Volkes Israel aus der Sklaverei in Ägypten. Das Buch ist in zwei Hauptteile gegliedert: Kapitel 1-19: Auszug aus Ägypten; Kapitel 20-40: Gesetzgebung am Berg Sinai und Bau des Heiligtums. In diesem Buch wird der Verfasser, Mose, selbst zum Träger der Handlung. Man kann davon ausgehen, dass er dieses Buch während oder kurz nach dem Aufenthalt des Volkes am Sinai 1446 v.Chr. (Frühdatierung) niederschrieb. Gott hatte ihn verschiedentlich dazu aufgefordert (2. Mose 17,14; 34,27). Auch andere biblische Bücher und Jesus selbst bestätigen die Verfasserschaft Moses (1. Könige 2,3; Nehemia 8,1; Markus 7,10; 12,26).\n****Wie Gott sein Volk Israel aus Ägypten befreite und am Berg Sinai den Bund mit ihm schloss.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Das sind die Namen der Israeliten, die mit ihrem Vater Jakob und ihren Familien nach Ägypten gekommen waren:", heading: "1-18: Die Befreiung aus Ägypten\nDie Unterdrückung (1-6)\nSklaven in Ägypten" },
      { number: 2, text: "Ruben und Simeon, Levi und Juda," },
      { number: 3, text: "Issachar, Sebulon und Benjamin," },
      { number: 4, text: "Dan und Naftali, Gad und Ascher." },
      { number: 5, text: "Zusammen waren es siebzig Personen, die alle von Jakob abstammten.* Josef war schon vorher nach Ägypten gekommen.", footnotes: ["abstammten. Siehe Fußnote zu 1. Mose 46,27. Jakobs Ankunft in Ägypten könnte um das Jahr 1867 v.Chr. stattgefunden haben."] },
      { number: 6, text: "Dann starben Josef und seine Brüder. Auch von ihren Zeitgenossen lebte niemand mehr." },
      { number: 7, text: "Aber die Israeliten waren fruchtbar und vermehrten sich und wurden überaus stark. Das Land füllte sich mit ihnen." },
      { number: 8, text: "Da trat ein neuer König die Herrschaft über Ägypten an, der Josef nicht mehr kannte." },
      { number: 9, text: "Er sagte zu seinen Leuten: \"Passt auf! Das Volk der Israeliten ist zahlreicher und stärker als wir." },
      { number: 10, text: "Wir müssen geschickt gegen sie vorgehen, damit sie nicht noch stärker werden! Sonst laufen sie in einem Krieg womöglich zu unseren Feinden über und kämpfen gegen uns und ziehen dann aus dem Land weg.\"" },
      { number: 11, text: "Deshalb setzten die Ägypter Aufseher ein, um die Israeliten mit Zwangsarbeit unter Druck zu setzen. Sie mussten die Vorratsstädte Pitom* und Ramses* für den Pharao* bauen.", footnotes: ["Pitom. Stadt im Nordosten Ägyptens.", "Ramses. Stadt im östlichen Nildelta, etwa 30 km südlich von Tanis/Zoan.", "Pharao. Das ägyptische Wort bedeutet \"großes Haus\" und ist ein königlicher Titel."] },
      { number: 12, text: "Aber je mehr sie die Israeliten unterdrückten, umso stärker vermehrten sich diese. Sie breiteten sich derartig aus, dass die Ägypter das Grauen vor den Israeliten packte." },
      { number: 13, text: "Darum gingen sie hart gegen sie vor und zwangen sie zu Sklavendiensten." },
      { number: 14, text: "Sie machten ihnen das Leben zur Hölle. Die Israeliten mussten in Schwerstarbeit Ziegel aus Lehm herstellen und harte Feldarbeiten verrichten." },
      { number: 15, text: "Dann ließ der König von Ägypten die Hebammen für die Hebräer,* Schifra und Pua, zu sich rufen", footnotes: ["für die Hebräer. Entweder gehörten die Hebammen zu den Israeliten (Hebräer) oder es waren gottesfürchtige Ägypterinnen."] },
      { number: 16, text: "und befahl ihnen: \"Wenn ihr den hebräischen Frauen bei der Entbindung helft und seht, dass ein Junge zur Welt kommt, dann tötet ihn sofort! Mädchen dürft ihr am Leben lassen.\"" },
      { number: 17, text: "Aber die Hebammen fürchteten Gott und befolgten den Befehl des ägyptischen Königs nicht. Sie ließen die Jungen am Leben." },
      { number: 18, text: "Da rief der König sie wieder zu sich und fragte sie: \"Warum tut ihr das und lasst die Jungen am Leben?\"" },
      { number: 19, text: "Sie erwiderten dem Pharao: \"Weil die hebräischen Frauen nicht so wie die ägyptischen sind. Sie sind kräftig und haben ihre Kinder schon zur Welt gebracht, ehe die Hebamme zu ihnen kommt.\"" },
      { number: 20, text: "So vermehrte sich das Volk und wurde sehr stark. Gott tat den Hebammen Gutes." },
      { number: 21, text: "Und weil sie Ehrfurcht vor ihm hatten, schenkte er ihnen Nachkommenschaft." },
      { number: 22, text: "Da ließ der Pharao einen Befehl an sein ganzes Volk ergehen: \"Werft jeden Jungen, der den Hebräern geboren wird, in den Nil! Nur die Mädchen dürfen am Leben bleiben.\"" },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Ein Mann von den Nachkommen Levis heiratete eine Frau aus dem gleichen Stamm.", heading: "Moses Kindheit" },
      { number: 2, text: "Sie wurde schwanger und brachte einen Sohn zur Welt. Als sie sah, wie schön der Junge war, hielt sie ihn drei Monate lang versteckt." },
      { number: 3, text: "Länger konnte sie ihn nicht verbergen. Deshalb nahm sie ein Kästchen* aus Papyrusrohr, dichtete es mit Erdharz und Pech ab und legte das Kind hinein. Dann setzte sie es im Schilf am Nilufer aus.", footnotes: ["Kästchen. Das gleiche Wort wird nur noch einmal in der Bibel für Noahs Arche verwendet."] },
      { number: 4, text: "Seine Schwester blieb in der Nähe stehen, um zu sehen, was mit ihm geschehen würde." },
      { number: 5, text: "Da kam die Tochter des Pharao an den Nil, um zu baden. Ihre Dienerinnen gingen am Ufer hin und her. Auf einmal sah sie das Kästchen mitten im Schilf und schickte eine Dienerin hin, um es zu holen." },
      { number: 6, text: "Als sie es öffnete, fand sie einen weinenden Jungen darin. Mitleidig rief sie: \"Das ist ja eins von den Kindern der Hebräer!\"" },
      { number: 7, text: "Da sagte seine Schwester zur Tochter des Pharao: \"Soll ich eine hebräische Frau holen, die das Kind für dich stillen kann?\"" },
      { number: 8, text: "\"Ja, hole sie!\", sagte die Tochter des Pharao. Da holte das Mädchen die Mutter des Kindes." },
      { number: 9, text: "Die Pharaostochter sagte zu ihr: \"Nimm dieses Kind und stille es für mich! Ich werde dich dafür bezahlen.\" Da nahm die Frau das Kind zu sich und stillte es." },
      { number: 10, text: "Als der Junge größer geworden war, übergab sie ihn der Tochter des Pharao, die ihn als ihren Sohn annahm. Sie nannte ihn Mose und sagte: \"Ich habe ihn ja aus dem Wasser gezogen.\"*", footnotes: ["Mose erinnert im Hebräischen an \"herausziehen\"."] },
      { number: 11, text: "Als Mose erwachsen war, ging er einmal zu seinen Brüdern* hinaus und schaute ihnen bei ihren Lastarbeiten zu. Da wurde er Zeuge, wie ein ägyptischer Mann einen von seinen Stammesbrüdern misshandelte*.", heading: "Mose entdeckt seine Brüder", footnotes: ["Brüder meint hier seine hebräischen Volksgenossen.", "misshandelte. Das hebräische Wort kann auch \"erschlug\" bedeuten."] },
      { number: 12, text: "Mose schaute sich nach allen Seiten um, und als er sah, dass niemand in der Nähe war, erschlug er den Ägypter und verscharrte ihn im Sand." },
      { number: 13, text: "Am nächsten Tag ging er wieder hinaus. Da sah er zwei Hebräer miteinander streiten. Er sagte zu dem, der im Unrecht war: \"Warum schlägst du einen Mann aus deinem eigenen Volk?\"" },
      { number: 14, text: "\"Wer hat dich denn zum Aufseher und Richter über uns eingesetzt?\", erwiderte dieser. \"Willst du mich auch umbringen wie den Ägypter?\" Da erschrak Mose. \"Also ist es doch herausgekommen\", dachte er." },
      { number: 15, text: "Als der Pharao davon hörte, wollte er Mose töten lassen. Mose aber entkam ihm und hielt sich im Land Midian* auf. Eines Tages saß er dort an einem Brunnen.", heading: "Mose in Midian", footnotes: ["Die Midianiter waren ein Nomadenvolk, das in der Araba (südliches Jordantal) und in Transjordanien umherzog."] },
      { number: 16, text: "Da kamen die sieben Töchter des Priesters von Midian zu dem Brunnen, um das Kleinvieh* ihres Vaters zu tränken. Als sie gerade die Tränkrinnen voll Wasser geschöpft hatten,", footnotes: ["Kleinvieh. Gemeint sind Schafe und/oder Ziegen."] },
      { number: 17, text: "kamen Hirten und trieben sie weg. Da stand Mose auf und half ihnen, ihre Herde zu tränken." },
      { number: 18, text: "Als sie zu ihrem Vater Reguël* zurückkamen, fragte er: \"Warum seid ihr heute so früh gekommen?\"", footnotes: ["Reguël heißt \"Freund Gottes\". Sein anderer Name Jitro (Kapitel 3,1) könnte ein Titel sein mit der Bedeutung \"seine Exzellenz\"."] },
      { number: 19, text: "\"Ein ägyptischer Mann hat uns gegen die Hirten verteidigt\", erwiderten sie. \"Er hat uns sogar beim Tränken geholfen und auch selbst Wasser geschöpft.\"" },
      { number: 20, text: "\"Und wo ist er?\", fragte er seine Töchter. \"Warum habt ihr den Mann draußen gelassen? Ladet ihn zum Essen ein!\"" },
      { number: 21, text: "Mose willigte dann ein, bei dem Mann zu bleiben. Dieser gab ihm später seine Tochter Zippora zur Frau." },
      { number: 22, text: "Als sie einen Sohn zur Welt brachte, nannte Mose ihn Gerschom, Gast in der Öde, und sagte: \"Ich bin Gast in einem fremden Land geworden.\"" },
      { number: 23, text: "Jahre später starb der König von Ägypten. Die Israeliten stöhnten unter der Zwangsarbeit und schrien um Hilfe. Ihr Schreien wegen der Arbeit drang zu Gott.", heading: "Gott hört den Hilferuf der Israeliten" },
      { number: 24, text: "Gott hörte ihr Stöhnen und dachte an den Bund, den er mit Abraham, Isaak und Jakob geschlossen hatte." },
      { number: 25, text: "Gott sah also nach den Israeliten und kümmerte sich um sie." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Mose war Hirt für das Kleinvieh seines Schwiegervaters Jitro*, des Priesters von Midian. Als er die Herde hinter die Steppe führte, kam er an den Gottesberg, den Horeb*.", heading: "Moses Berufung", footnotes: ["Jitro. Siehe Fußnote zu Reguël (Kapitel 2,18).", "Horeb. Anderer Name für den Berg Sinai oder einen anderen Gipfel in derselben Bergregion. Der Sinai wird meist mit dem Dschebel Musa im Südosten der Sinai-Halbinsel identifiziert, was aber nicht sicher ist."] },
      { number: 2, text: "Dort erschien ihm der Engel Jahwes* in einer lodernden Flamme, die aus einem Dornbusch herausschlug. Mose sah, dass der Busch brannte, aber nicht von den Flammen verzehrt wurde.", footnotes: ["Engel Jahwes. Hebräisch Mal'ach Jahwe. Das war kein gewöhnlicher Engel, sondern eine Erscheinung Gottes."] },
      { number: 3, text: "\"Warum verbrennt der Dornbusch nicht?\", dachte Mose. \"Das muss ich mir aus der Nähe ansehen!\"" },
      { number: 4, text: "Als Jahwe sah, dass Mose näher kam, rief Gott ihm aus dem Dornbusch heraus zu: \"Mose! Mose!\" – \"Hier bin ich\", erwiderte dieser." },
      { number: 5, text: "\"Komm nicht näher!\", sagte Gott. \"Zieh deine Sandalen aus, denn der Ort, auf dem du stehst, ist heiliges Land.\"" },
      { number: 6, text: "Dann sagte er: \"Ich bin der Gott deines Vaters, ich bin der Gott Abrahams, Isaaks und Jakobs.\"* Da verhüllte Mose sein Gesicht, denn er fürchtete sich, Gott anzusehen.*", footnotes: ["Wird im Neuen Testament von Jesus Christus und von Stephanus zitiert: Matthäus 22,32; Markus 12,26; Lukas 20,37; Apostelgeschichte 7,32.", "Gott anzusehen. Das heißt hier: in die Flamme hineinzusehen, mit der Gott sich verhüllte."] },
      { number: 7, text: "Doch Jahwe sprach weiter: \"Ich habe sehr wohl gesehen, wie mein Volk Israel in Ägypten misshandelt wird, und habe sein Schreien wegen der Antreiber gehört. Ja, ich kenne seine Schmerzen." },
      { number: 8, text: "Nun bin ich gekommen, um es aus der Gewalt der Ägypter zu befreien. Ich will es aus Ägypten herausführen in ein gutes und geräumiges Land. Ich bringe es in ein Land, das von Milch und Honig überfließt. Es ist das Land der Kanaaniter*, Hetiter*, Amoriter*, Perisiter*, Hiwiter* und Jebusiter*.", footnotes: ["Kanaaniter. Bewohner des Landes Kanaan auf dem Gebiet des heutigen Israel. Sie besaßen eine gemeinsame Sprache, Religion und Kultur, waren politisch aber in viele Kleinkönigtümer und Stadtstaaten zersplittert.", "Das Reich der Hetiter erstreckte sich nach Norden weit bis in die heutige Türkei.", "Amoriter kann sowohl für einen einzelnen Stamm als auch für alle Bewohner Kanaans stehen. Es waren semitische Einwanderer aus der Arabischen Wüste, die um 2000 v.Chr. ins Kulturland eindrangen.", "Perisiter. Nicht näher bekanntes Volk in Kanaan; möglicherweise die bäuerliche Bevölkerung.", "Hiwiter. Bewohner Kanaans. Die Einwohner der Städte Gibeon, Kefira, Beerot und Kirjat-Jearim gehörten zu ihnen. Ihr Hauptsiedlungsgebiet scheint am Libanon zwischen Hermon und Hamat gelegen zu haben.", "Jebusiter siedelten auf dem Gebirge in Kanaan und bewohnten auch die Stadt Jerusalem."] },
      { number: 9, text: "Ja, die Hilfeschreie der Israeliten sind bei mir angekommen, und ich habe auch gesehen, wie grausam die Ägypter sie unterdrücken." },
      { number: 10, text: "Und nun geh! Ich will dich zum Pharao senden. Du sollst mein Volk, die Israeliten, aus Ägypten herausführen!\"" },
      { number: 11, text: "Mose erwiderte Gott: \"Wer bin ich denn, dass ich zum Pharao gehen und die Israeliten aus Ägypten führen könnte?\"" },
      { number: 12, text: "Da sagte Gott: \"Ich werde dir ja beistehen. Und das hier ist das Zeichen, dass ich dich beauftragt habe: Wenn du das Volk aus Ägypten herausgeführt hast, werdet ihr an diesem Berg Gott anbeten.\"" },
      { number: 13, text: "Mose sagte zu Gott: \"Wenn ich nun zu den Israeliten komme und ihnen sage: 'Der Gott eurer Vorfahren hat mich zu euch geschickt', und sie mich dann fragen: 'Wie heißt er denn?', was soll ich ihnen sagen?\"" },
      { number: 14, text: "Da sagte Gott zu Mose: \"Ich bin der, der ist und immer sein wird. Sag den Israeliten: Der 'Ich-bin'* hat mich zu euch geschickt.\"", footnotes: ["Ich bin. Das Hebräische (Ehje = Ich bin) klingt an den Gottesnamen Jahwe an. Die Juden verstehen Ehje jedoch als zusätzlichen Gottesnamen."] },
      { number: 15, text: "Weiter sagte Gott zu Mose: \"Sag den Israeliten: 'Jahwe, der Gott eurer Vorfahren, der Gott Abrahams, Isaaks und Jakobs, hat mich zu euch geschickt.' Das ist mein Name für immer. Mit diesem Namen sollen mich auch die kommenden Generationen ansprechen.\"" },
      { number: 16, text: "\"Nun geh, ruf die Ältesten Israels zusammen und sag ihnen: 'Jahwe, der Gott eurer Vorfahren, der Gott Abrahams, Isaaks und Jakobs, ist mir erschienen und hat gesagt: Ich habe genau auf euch achtgegeben und gesehen, was man euch in Ägypten antut,", heading: "Moses Auftrag" },
      { number: 17, text: "und mich entschlossen, euch aus dem Elend Ägyptens herauszuführen. Ich bringe euch in das Land der Kanaaniter, Hetiter, Amoriter, Perisiter, Hiwiter und Jebusiter, in ein Land, das von Milch und Honig überfließt.'" },
      { number: 18, text: "Wenn du ihnen das sagst, werden sie auf dich hören. Dann sollst du mit den Ältesten Israels zum König von Ägypten gehen und ihm sagen: 'Jahwe, der Gott der Hebräer, ist uns erschienen. Nun lass uns doch drei Tagereisen* weit in die Wüste ziehen, damit wir Jahwe, unserem Gott, dort Opfertiere schlachten.'", footnotes: ["Eine Tagesreise entspricht etwa 30 Kilometern."] },
      { number: 19, text: "Ich weiß wohl, dass der König von Ägypten euch nicht ziehen lassen will. Auch durch eine starke Hand will er sich nicht zwingen lassen." },
      { number: 20, text: "Deshalb werde ich meine Hand ausstrecken und die Ägypter schlagen. Schreckenerregende Wunder werde ich unter ihnen tun. Dann erst wird er euch ziehen lassen." },
      { number: 21, text: "Ich werde euch bei den Ägyptern Achtung verschaffen. Ihr werdet das Land nicht mit leeren Händen verlassen." },
      { number: 22, text: "Jede israelitische Frau soll von ihrer Nachbarin Silber- und Goldschmuck und Obergewänder verlangen. Das können dann eure Söhne und Töchter tragen. So sollt ihr die Ägypter ausplündern.\"" },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Da erwiderte Mose: \"Und was ist, wenn sie mir nicht glauben, wenn sie nicht auf mich hören und sagen: 'Jahwe ist dir gar nicht erschienen!'?\"", heading: "Moses Einwände" },
      { number: 2, text: "\"Was hast du da in der Hand?\", fragte Jahwe ihn. \"Einen Stab\", erwiderte Mose." },
      { number: 3, text: "\"Wirf ihn auf die Erde!\", befahl Jahwe. Mose tat es. Da wurde der Stab zu einer Schlange, und Mose lief vor ihr davon." },
      { number: 4, text: "Jahwe rief: \"Pack sie beim Schwanz!\" Mose griff nach ihr, und sie wurde in seiner Hand wieder zum Stab." },
      { number: 5, text: "\"So werden sie glauben, dass Jahwe dir erschienen ist, der Gott ihrer Vorfahren, der Gott Abrahams, Isaaks und Jakobs.\"" },
      { number: 6, text: "Dann befahl Jahwe ihm: \"Steck deine Hand in dein Gewand!\" Mose tat es, und als er die Hand wieder hervorzog, war sie voller Aussatz*, weiß wie Schnee.", footnotes: ["Aussatz. Bezeichnung für rasch um sich greifende Hautkrankheiten, Lepra eingeschlossen."] },
      { number: 7, text: "Da befahl er ihm: \"Steck deine Hand noch einmal ins Gewand!\" Mose tat es, und als er sie hervorzog, war sie wieder gesund." },
      { number: 8, text: "\"Wenn sie dir auf das erste Zeichen hin nicht glauben, werden sie sich durch das zweite überzeugen lassen." },
      { number: 9, text: "Und wenn sie selbst diesen beiden Zeichen nicht glauben und nicht auf dich hören wollen, dann nimm etwas Nilwasser und schütte es auf den Boden. Es wird dort zu Blut werden.\"" },
      { number: 10, text: "Doch Mose erwiderte Jahwe: \"Ach Herr, ich bin kein Redner. Ich konnte das noch nie. Und auch seit du mit deinem Sklaven sprichst, ist es nicht besser geworden. Ich bin schwerfällig und unbeholfen, wenn ich reden soll.\"" },
      { number: 11, text: "Da sagte Jahwe zu ihm: \"Wer hat dem Menschen denn den Mund gemacht? Wer macht Menschen stumm oder taub, sehend oder blind? Doch wohl ich, Jahwe!" },
      { number: 12, text: "Also geh jetzt! Ich werde deinem Mund schon beistehen und dir beibringen, was du sagen sollst.\"" },
      { number: 13, text: "Doch Mose erwiderte: \"Ach Herr, schick doch lieber einen anderen!\"" },
      { number: 14, text: "Da wurde Jahwe zornig über Mose und sagte: \"Hast du nicht noch einen Bruder, den Leviten Aaron? Er kann reden, das weiß ich. Er ist schon auf dem Weg zu dir und wird sich freuen, wenn er dich wiedersieht." },
      { number: 15, text: "Dann teilst du ihm alles mit, was er sagen soll. Ich helfe dir dabei und werde auch ihm helfen und sage euch auch, was ihr tun sollt." },
      { number: 16, text: "Wenn er für dich zum Volk redet, wird das so sein, als ob er dein Sprecher ist und du sein Gott* bist.", footnotes: ["du sein Gott. Der Pharao sollte glauben, dass Mose ein Gott ist, der mit seinem Sprecher vor ihm auftritt (siehe 2. Mose 7,1)."] },
      { number: 17, text: "Und diesen Stab hier nimm in deine Hand! Mit ihm sollst du die Wunderzeichen tun.\"" },
      { number: 18, text: "Daraufhin kehrte Mose zu seinem Schwiegervater Jitro zurück und sagte: \"Ich möchte gern zu meinen Brüdern nach Ägypten zurückkehren und sehen, ob sie noch am Leben sind.\" – \"Zieh in Frieden!\", sagte Jitro zu Mose.", heading: "Moses Rückkehr nach Ägypten" },
      { number: 19, text: "Noch im Land Midian hatte Jahwe zu Mose gesagt: \"Du kannst ruhig nach Ägypten zurückkehren, denn alle, die dich töten wollten, sind gestorben.\"" },
      { number: 20, text: "So ließ Mose seine Frau mit den kleinen Kindern auf dem Esel reiten und machte sich mit ihnen auf den Weg nach Ägypten. Den Stab Gottes hatte er in der Hand." },
      { number: 21, text: "Jahwe sagte zu Mose: \"Wenn du wieder nach Ägypten kommst, dann sollst du vor dem Pharao die Wunderzeichen vollbringen, zu denen ich dich bevollmächtigt habe. Ich werde ihn allerdings starrsinnig machen, sodass er das Volk nicht ziehen lassen wird." },
      { number: 22, text: "Dann sollst du dem Pharao verkünden: 'So spricht Jahwe: Israel ist mein erstgeborener Sohn." },
      { number: 23, text: "Und ich sage dir: Lass meinen Sohn ziehen, dass er mir dient. Wenn du dich weigerst, ihn ziehen zu lassen, pass auf: Dann werde ich deinen erstgeborenen Sohn umbringen.'\"" },
      { number: 24, text: "Unterwegs am Rastplatz fiel Jahwe über Mose her und wollte ihn töten.*", footnotes: ["töten. Mose hatte es versäumt, dem Gebot Gottes zu gehorchen und seinen Sohn zu beschneiden (1. Mose 17,9-14). Deswegen ließ Gott offenbar eine tödliche Krankheit über ihn kommen."] },
      { number: 25, text: "Da nahm Zippora einen scharfen Stein, schnitt die Vorhaut am Glied ihres Sohnes ab und berührte damit die Scham von Mose.* Dabei sagte sie: \"Du bist mir wirklich ein Blutsbräutigam!\"", footnotes: ["Scham von Mose. Das war möglicherweise ein symbolischer Akt, in dem der Gehorsam den Ungehorsam ersetzte."] },
      { number: 26, text: "Wegen der Beschneidung sagte sie \"Blutsbräutigam\" zu ihm. Da ließ Jahwe von Mose ab." },
      { number: 27, text: "Zu Aaron hatte Jahwe gesagt: \"Geh in die Wüste, Mose entgegen!\" Aaron machte sich auf den Weg. Am Berg Gottes traf er Mose und begrüßte ihn mit einem Kuss." },
      { number: 28, text: "Mose berichtete Aaron in allen Einzelheiten, was Jahwe ihm aufgetragen hatte und welche Wunderzeichen er tun sollte." },
      { number: 29, text: "Dann gingen beide nach Ägypten und riefen die Ältesten des Volkes Israel zusammen." },
      { number: 30, text: "Aaron wiederholte vor ihnen alle Worte, die Jahwe zu Mose gesagt hatte, und Mose tat die Wunderzeichen vor dem Volk." },
      { number: 31, text: "Da glaubten die Israeliten und begriffen, dass Jahwe ihr Elend gesehen hatte und zu ihnen gekommen war. Sie verneigten sich und beteten Gott an." },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Dann gingen Mose und Aaron zum Pharao und sagten: \"So spricht Jahwe, der Gott Israels: Lass mein Volk ziehen, damit es in der Wüste ein Fest für mich feiern kann!\"", heading: "Mose und Aaron vor dem Pharao – Verschlimmerung der Lage" },
      { number: 2, text: "\"Jahwe, wer ist das überhaupt\", erwiderte der Pharao, \"dass er mir befehlen will, Israel ziehen zu lassen? Ich kenne Jahwe nicht und werde Israel auch nicht ziehen lassen!\"" },
      { number: 3, text: "Da sagten sie: \"Er ist der Gott der Hebräer, der uns begegnet ist. Darum wollen wir drei Tagereisen weit in die Wüste ziehen und Jahwe, unserem Gott, Opfer schlachten, damit er nicht mit Pest oder Schwert über uns herfällt.\"" },
      { number: 4, text: "Der Ägypterkönig erwiderte: \"Warum wollt ihr das Volk von seiner Arbeit abhalten, Mose und Aaron? Macht euch an die Arbeit!\"" },
      { number: 5, text: "Dann fügte er noch hinzu: \"Es gibt schon mehr als genug von diesem Volk, und da wollt ihr sie auch noch von ihrer Arbeit abhalten?\"" },
      { number: 6, text: "Noch am selben Tag gab der Pharao den ägyptischen Sklaventreibern und den israelitischen Aufsehern die Anweisung:" },
      { number: 7, text: "\"Ab sofort dürft ihr den Leuten kein Häcksel* mehr zur Herstellung der Ziegel liefern. Sie sollen sich das Stroh selbst zusammensuchen!", footnotes: ["Das Stroh wurde zu Häcksel geschnitten und diente bei der Ziegelherstellung als Bindemittel für den Lehm. Die Ziegel waren 38 x 18 x 11 cm groß und wurden in der Sonne getrocknet."] },
      { number: 8, text: "Aber sie müssen genauso viele Ziegel abliefern wie bisher! Ihr dürft ihnen nichts erlassen, denn sie sind faul. Darum schreien sie ja: 'Wir wollen losziehen und unserem Gott Opfer schlachten!'" },
      { number: 9, text: "Die Arbeit muss den Männern Druck machen! Wenn sie daran genug zu schaffen haben, kümmern sie sich nicht um leeres Geschwätz!\"" },
      { number: 10, text: "So kamen die Sklaventreiber und die Aufseher des Volkes zu den Israeliten und sagten: \"Der Pharao hat befohlen, dass ihr kein Häcksel mehr bekommt." },
      { number: 11, text: "Geht selbst und sucht euch Stroh, wo ihr es finden könnt! Doch euer Soll wird nicht gekürzt!\"" },
      { number: 12, text: "Daraufhin verteilte sich das Volk im ganzen Land Ägypten, um Strohstoppeln für Häcksel zu sammeln." },
      { number: 13, text: "Die Sklaventreiber drängten sie und sagten: \"Ihr müsst jeden Tag genauso viele Ziegel abliefern wie früher, als es noch Häcksel gab!\"" },
      { number: 14, text: "Auch die israelitischen Aufseher, die die Sklaventreiber des Pharao eingesetzt hatten, wurden geschlagen und angeschrien: \"Warum habt ihr gestern und heute euer Soll an Ziegeln nicht erfüllt?\"" },
      { number: 15, text: "Da gingen die israelitischen Aufseher zum Pharao und beklagten sich: \"Warum tust du das mit deinen Dienern?" },
      { number: 16, text: "Man liefert unseren Leuten kein Häcksel mehr und verlangt dennoch, dass sie Ziegel herstellen. Sie werden sogar geschlagen, und dabei sind deine Leute daran schuld!\"" },
      { number: 17, text: "\"Faul seid ihr\", erwiderte der Pharao, \"faul! Deswegen schreit ihr: 'Wir wollen losziehen und Jahwe Opfer schlachten!'" },
      { number: 18, text: "Macht euch wieder an die Arbeit! Häcksel bekommt ihr nicht, aber euer Soll an Ziegeln müsst ihr erfüllen!\"" },
      { number: 19, text: "Da sahen sich die Aufseher aus dem Volk Israel in einer üblen Lage, weil man ihnen sagte: \"Nichts von eurem täglichen Soll an Ziegeln wird euch erlassen!\"" },
      { number: 20, text: "Als sie vom Pharao kamen, trafen sie Mose und Aaron, die auf sie warteten." },
      { number: 21, text: "\"Jahwe möge euch bestrafen!\", sagten sie zu beiden. \"Ihr habt uns beim Pharao und seinen Leuten verhasst gemacht. Ihr habt ihnen eine Waffe in die Hand gegeben, mit der sie uns umbringen werden!\"" },
      { number: 22, text: "Da wandte sich Mose an Jahwe und sagte: \"Herr, warum behandelst du dieses Volk so schlecht? Wozu hast du mich denn hergeschickt?" },
      { number: 23, text: "Seit ich zum Pharao gegangen bin und in deinem Namen gesprochen habe, misshandelt er das Volk nur noch mehr. Du hast dein Volk keineswegs gerettet!\"" },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Da sagte Jahwe zu Mose: \"Jetzt wirst du erleben, was ich mit dem Pharao machen werde. Eine starke Hand wird ihn zwingen, sie ziehen zu lassen, ja, er wird sie sogar aus seinem Land fortjagen.\"", heading: "Gottes Zusagen für Israel" },
      { number: 2, text: "Gott fuhr fort: \"Ich bin Jahwe!" },
      { number: 3, text: "Ich bin Abraham, Isaak und Jakob als Gott, der Allmächtige, erschienen. Aber unter meinem Namen Jahwe habe ich mich ihnen noch nicht zu erkennen gegeben.*", footnotes: ["erkennen gegeben. Das heißt nicht, dass sie den Namen Jahwe noch nicht kannten (siehe 1. Mose 12,8), sondern dass sie dessen eigentliche Bedeutung noch nicht erfassen konnten, weil Jahwe auch der ist, der sein Volk befreien wird (2. Mose 3,8.13-15). Das konnte erst das aus Ägypten befreite Volk richtig verstehen. Der Name Jahwe selbst kann aus der Wurzel haja (\"sein\") abgeleitet werden (2. Mose 3,14). Die Kausativform dieser Wurzel lautet jahwe (\"der, der ins Sein bringt\")."] },
      { number: 4, text: "Und dann habe ich auch meinen Bund mit ihnen geschlossen und habe versprochen, ihnen das Land Kanaan zu geben, das Land, in dem sie als Fremde lebten." },
      { number: 5, text: "Auch das Stöhnen der Israeliten, die von den Ägyptern wie Sklaven behandelt werden, habe ich gehört. Da habe ich an meinen Bund gedacht." },
      { number: 6, text: "Sag deshalb zu den Israeliten: 'Ich bin Jahwe. Ich befreie euch von der Zwangsarbeit für die Ägypter. Ich rette euch aus der Sklaverei. Mit starker Hand und durch große Strafgerichte werde ich euch erlösen." },
      { number: 7, text: "Ich nehme euch als mein Volk an und werde euer Gott sein. Ihr sollt erkennen, dass ich Jahwe bin, euer Gott, der euch von der Zwangsarbeit für die Ägypter befreit hat." },
      { number: 8, text: "Ich bringe euch in das Land, das ich Abraham, Isaak und Jakob unter Eid versprochen habe, und gebe es euch zum bleibenden Besitz, ich, Jahwe.'\"" },
      { number: 9, text: "Mose sagte das alles den Israeliten. Aber sie glaubten ihm nicht, so entmutigt und erschöpft waren sie von der schweren Arbeit." },
      { number: 10, text: "Da sagte Jahwe zu Mose:" },
      { number: 11, text: "\"Geh zum Pharao, dem König von Ägypten, und verlange von ihm, die Israeliten aus seinem Land ziehen zu lassen.\"" },
      { number: 12, text: "Doch Mose erwiderte Jahwe: \"Nicht einmal die Israeliten haben auf mich gehört, wie sollte es da der Pharao tun! Ich bin nun einmal ungeschickt im Reden.\"" },
      { number: 13, text: "Aber Jahwe schickte Mose und Aaron erneut zu den Israeliten und zum Pharao, weil er sein Volk aus dem Land Ägypten herausführen wollte." },
      { number: 14, text: "Es folgt die Liste der Sippenoberhäupter: Die Nachkommen Rubens, des erstgeborenen Sohnes Israels, unterteilen sich in die Sippen Henoch, Pallu, Hezron und Karmi,", heading: "Die Herkunft von Mose und Aaron" },
      { number: 15, text: "die Nachkommen Simeons in die Sippen Jemuël, Jamin, Ohad, Jachin, Zohar und Schaul – Schaul war der Sohn einer Kanaaniterin." },
      { number: 16, text: "Mit Levi ging es folgendermaßen weiter: Seine Söhne waren Gerschon, Kehat und Merari. Levi selbst war 137 Jahre alt geworden." },
      { number: 17, text: "Die Nachkommen Gerschons unterteilten sich in die Sippen Libni und Schimi," },
      { number: 18, text: "die Nachkommen Kehats in die Sippen Amram, Jizhar, Hebron und Usiël – Kehat wurde 133 Jahre alt." },
      { number: 19, text: "Die Nachkommen Meraris unterteilten sich in die Sippen Machli und Muschi." },
      { number: 20, text: "Amram* heiratete Jochebed, die Schwester seines Vaters*. Sie gebar ihm Aaron und Mose. Amram wurde 137 Jahre alt.", footnotes: ["Amram ist nicht identisch mit dem in Vers 18 genannten, denn Kehat, der Vater dieses Amrams, war schon geboren, bevor Jakob nach Ägypten kam (1. Mose 46,11). Zwischen diesem Datum und dem des Auszugs aus Ägypten lagen 430 Jahre (2. Mose 12,40-41). Auf jeden Fall will Gottes Wort deutlich machen, dass Mose zur Sippe Amram gehörte.", "Schwester seines Vaters.Eine Ehe mit so nahen Verwandten hat Gott später gesetzlich verboten (3. Mose 18,12)."] },
      { number: 21, text: "Jizhars Söhne hießen: Korach, Nefeg und Sichri;" },
      { number: 22, text: "Usiëls Söhne: Mischaël, Elizafan und Sitri." },
      { number: 23, text: "Aaron heiratete Elischeba, eine Tochter Amminadabs und Schwester Nachschons. Sie brachte ihm vier Söhne zur Welt: Nadab, Abihu, Eleasar und Itamar." },
      { number: 24, text: "Die Nachkommen Korachs unterteilten sich in die Sippen Assir, Elkana und Abiasaf." },
      { number: 25, text: "Aarons Sohn Eleasar heiratete eine Tochter Putiëls. Sie gebar ihm einen Sohn namens Pinhas. Damit sind die Familienhäupter der Leviten aufgezählt." },
      { number: 26, text: "Die hier genannten Aaron und Mose sind diejenigen, denen Jahwe befohlen hatte: \"Führt die Israeliten in geordneten Scharen aus Ägypten hinaus.\"" },
      { number: 27, text: "Es sind die, die mit dem Pharao redeten, um die Israeliten aus Ägypten herauszuführen." },
      { number: 28, text: "Jahwe hatte in Ägypten zu Mose gesagt:" },
      { number: 29, text: "\"Ich bin Jahwe! Sag dem König von Ägypten alles, was ich dir auftrage!\"" },
      { number: 30, text: "Mose aber hatte eingewandt: \"Ich bin so ungeschickt im Reden, wie sollte der Pharao da auf mich hören?\"" },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Jahwe sagte zu Mose: \"Pass auf! Für den Pharao habe ich dich zu einem Gott gemacht und Aaron wird dein Prophet sein.", heading: "Der Auszug aus Ägypten (7-13)\nAaron, der Sprecher Moses" },
      { number: 2, text: "Du gibst ihm alles weiter, was ich dir befehle, und dein Bruder Aaron wird dann vom Pharao fordern, dass er die Israeliten aus seinem Land ziehen lässt." },
      { number: 3, text: "Ich selbst werde den Pharao starrsinnig machen und werde viele Zeichen und Wunder im Land Ägypten tun." },
      { number: 4, text: "Der Pharao wird nicht auf euch hören. Deshalb wird Ägypten meine Macht zu spüren bekommen, und ich werde meine Scharen, mein Volk, die Israeliten, unter gewaltigen Strafgerichten aus dem Land Ägypten herausführen." },
      { number: 5, text: "Die Ägypter sollen erkennen, dass ich es bin, Jahwe, wenn ich sie meine Macht spüren lasse und die Israeliten aus ihrem Land wegführe.\"" },
      { number: 6, text: "Mose und Aaron taten, was Jahwe ihnen befohlen hatte." },
      { number: 7, text: "Mose war damals 80 Jahre alt und Aaron 83 Jahre." },
      { number: 8, text: "Jahwe hatte Mose und Aaron noch gesagt:" },
      { number: 9, text: "\"Wenn der Pharao verlangt, dass ihr euch durch ein Wunder ausweist, dann sagst du zu Aaron: 'Wirf deinen Stab vor dem Pharao auf den Boden!' Dann wird er zu einer Schlange werden.\"" },
      { number: 10, text: "Da gingen Mose und Aaron zum Pharao und taten, was Jahwe ihnen aufgetragen hatte. Aaron warf den Stab vor dem Pharao und seinen Hofbeamten hin und er wurde zur Schlange." },
      { number: 11, text: "Da rief der Pharao seine Weisen und Zauberer. Diese seine Magier vollbrachten mit ihren Zauberkünsten dasselbe." },
      { number: 12, text: "Jeder warf seinen Stab auf den Boden, und es wurden Schlangen daraus. Doch Aarons Stab verschlang ihre Stäbe." },
      { number: 13, text: "Der Pharao aber blieb hart. Er hörte nicht auf Mose und Aaron, wie Jahwe es gesagt hatte." },
      { number: 14, text: "Jahwe sagte zu Mose: \"Der Pharao bleibt hart. Er weigert sich, das Volk ziehen zu lassen.", heading: "1. Plage: Wasser wird Blut" },
      { number: 15, text: "Geh morgen früh zu ihm, wenn er ans Wasser hinunter geht. Nimm den Stab mit, der sich in eine Schlange verwandelt hat, und tritt dem Pharao am Ufer des Nils entgegen!" },
      { number: 16, text: "Sag zu ihm: 'Jahwe, der Gott der Hebräer, hat mich zu dir geschickt und fordert dich auf: Lass mein Volk ziehen, damit es mir in der Wüste dient! Aber bis jetzt hast du nicht darauf gehört." },
      { number: 17, text: "So spricht Jahwe: Jetzt wirst du merken, dass ich, Jahwe, es bin. Pass auf! Ich werde mit dem Stab in meiner Hand auf das Wasser im Nil schlagen, und es wird sich in Blut verwandeln." },
      { number: 18, text: "Dann werden die Fische im Nil verenden und der Fluss wird stinken, sodass die Ägypter sich ekeln, Nilwasser zu trinken.'\"" },
      { number: 19, text: "Dann sagte Jahwe zu Mose: \"Sag Aaron: 'Strecke deinen Stab über alle Gewässer Ägyptens aus, über die Flüsse und Kanäle, die Sümpfe* und alle Wasserstellen! Dann wird alles Wasser in Ägypten zu Blut, selbst in den entlegenen Ecken*.'\"", footnotes: ["Sümpfe, die nach der Nilüberschwemmung an einzelnen Stellen zurückblieben.", "entlegenen Ecken. Wörtlich: Holz und Stein. Das war ein Synonym für entlegene unfruchtbare Gegenden."] },
      { number: 20, text: "Mose und Aaron taten, was Jahwe ihnen aufgetragen hatte. Aaron hob den Stab und schlug vor den Augen des Pharao und seiner Hofbeamten auf das Wasser im Nil. Da verwandelte sich alles Wasser im Strom zu Blut." },
      { number: 21, text: "Die Fische starben, und das Wasser begann zu stinken, sodass die Ägypter das Nilwasser nicht mehr trinken konnten. Im ganzen Land war das Wasser zu Blut geworden.*", footnotes: ["Blut geworden. Vielleicht benutzte Gott dazu Unmengen an Flaggellaten, Mikroorganismen, die sowohl die Rotfärbung des Wassers als auch den Verwesungsgeruch verursachen konnten. Außerdem hätten sie dem Wasser nachts große Mengen an Sauerstoff entzogen, sodass die Fische sterben mussten."] },
      { number: 22, text: "Aber die ägyptischen Magier machten es mit ihren Zauberkünsten nach. Deshalb blieb der Pharao hart. Er hörte nicht auf Mose und Aaron, wie Jahwe es gesagt hatte." },
      { number: 23, text: "Er drehte ihnen den Rücken zu und ging in seinen Palast zurück. Er nahm es nicht ernst." },
      { number: 24, text: "Alle Ägypter aber gruben in der Umgebung des Nil nach Trinkwasser, denn das Nilwasser* war ungenießbar geworden,", footnotes: ["Nilwasser. Das heißt: alle mit dem Nil verbundenen Gewässer."] },
      { number: 25, text: "nachdem Jahwe den Nil geschlagen* hatte. So vergingen sieben Tage.", footnotes: ["Nil geschlagen. Offenbar sollten das die Ägypter als Angriff auf Hapi, den Gott des Nils, und die zahlreichen Fischgottheiten verstehen."] },
      { number: 26, text: "Da sagte Jahwe zu Mose: \"Geh zum Pharao und sage ihm: 'So spricht Jahwe: Lass mein Volk ziehen, damit es mir dienen kann!", heading: "2. Plage: Frösche" },
      { number: 27, text: "Wenn du dich weigerst, dann pass auf! Ich werde eine Froschplage über dein ganzes Land kommen lassen." },
      { number: 28, text: "Der Nil wird von Fröschen wimmeln; sie werden das Wasser verlassen und in deinen Palast kommen, in dein Schlafzimmer und in dein Bett. Auch in die Häuser deiner Beamten und des ganzen Volkes werden sie kommen und sich in die Backtröge und Backöfen setzen." },
      { number: 29, text: "Über dich und alle deine Untertanen wird diese Froschplage kommen.'\"" },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Dann sagte Jahwe zu Mose: \"Sag Aaron: 'Strecke deinen Stab über alle Gewässer Ägyptens aus, über die Flüsse, Kanäle und Sümpfe und lass die Frösche über das Land Ägypten kommen!'\"" },
      { number: 2, text: "Aaron streckte seine Hand über die Gewässer Ägyptens aus. Da kamen so viele Frösche heraus, dass sie das ganze Land bedeckten.*", footnotes: ["Frösche wurden von den Ägyptern als heilige Tiere angesehen. Auch eine der ägyptischen Hauptgöttinnen, Heqet, wurde in Froschgestalt oder mit einem Froschkopf dargestellt. Sie war für die Entbindung zuständig. Frösche durften nicht getötet werden. Ihr Quaken galt als Signal, dass die Götter das Land durch die Nilüberschwemmung wieder fruchtbar gemacht hatten. Doch hier brachten sie die gewohnte Ordnung aus dem Tritt."] },
      { number: 3, text: "Aber die ägyptischen Magier machten es mit ihren Zauberkünsten nach und ließen Frösche über Ägypten kommen.*", footnotes: ["ließen ... kommen. Sie machten also die Plage noch schlimmer, anstatt sie rückgängig zu machen."] },
      { number: 4, text: "Da ließ der Pharao Mose und Aaron rufen und sagte zu ihnen: \"Bittet Jahwe* für mich, dass er die Frösche von mir und meinem Volk wegschafft. Dann will ich euer Volk ziehen lassen, damit sie Jahwe Opfer schlachten können.\"", footnotes: ["bittet Jahwe. Es war eine Demütigung für den \"göttlichen\" Pharao, dass andere für ihn zu einem anderen Gott beten mussten."] },
      { number: 5, text: "Mose erwiderte dem Pharao: \"Verfüge über mich! Wann sollen die Frösche aus euren Häusern verschwinden und nur noch im Nil übrig bleiben? Für welche Zeit also soll ich für dich, deine Beamten und dein Volk beten?\"" },
      { number: 6, text: "\"Für morgen\", erwiderte er. \"Gut, es wird nach deinem Wunsch geschehen\", sagte Mose, \"denn du sollst erkennen, dass niemand Jahwe, unserem Gott, gleicht." },
      { number: 7, text: "Die Frösche werden aus deinem Palast verschwinden und dich, deine Hofbeamten und dein Volk in Ruhe lassen. Nur im Nil werden noch welche übrig bleiben.\"" },
      { number: 8, text: "Mose und Aaron verließen den Pharao, und Mose bat Jahwe dringend, der Froschplage ein Ende zu machen." },
      { number: 9, text: "Jahwe erhörte Mose, und überall in den Häusern, auf den Gehöften und Feldern starben die Frösche." },
      { number: 10, text: "Haufenweise schüttete man sie zusammen, und das ganze Land war von Gestank erfüllt." },
      { number: 11, text: "Als der Pharao sah, dass er wieder Luft hatte, verschloss er sein Herz und hörte nicht auf Mose und Aaron, wie Jahwe es gesagt hatte." },
      { number: 12, text: "Jahwe sagte zu Mose: \"Sag Aaron, dass er seinen Stab ausstrecken und damit auf die Erde schlagen soll. Dann wird der Staub zu Mücken* werden.\"", heading: "3. Plage: Mücken", footnotes: ["Mücken. Vielleicht sind die kleinen Stechmücken gemeint, die man mit bloßem Auge kaum sehen kann. Möglicherweise sahen die Ägypter das als Angriff auf den Wüstengott Set und auf die Priester, die ihre penible Reinheit durch die überall sitzenden Mücken nicht mehr aufrecht halten konnten."] },
      { number: 13, text: "Sie taten es. Aaron schlug mit seinem Stab auf den Staub der Erde. Da wurde der ganze Staub in Ägypten zu Mücken. Sie überfielen Menschen und Tiere." },
      { number: 14, text: "Die Magier versuchten mit ihren Zauberkünsten ebenfalls Mücken hervorzubringen. Aber sie konnten es nicht, und die Mücken setzten Mensch und Vieh zu." },
      { number: 15, text: "Da sagten sie zum Pharao: \"Das ist Gottes Finger!\"* Aber der Pharao blieb hart und hörte nicht auf sie, wie Jahwe es gesagt hatte.", footnotes: ["Gottes Finger. Bildhafte Ausdrucksweise für die Macht Gottes, die auch Jesus gebraucht (Lukas 11,20)"] },
      { number: 16, text: "Jahwe sagte zu Mose: \"Geh morgen früh zum Pharao, wenn er ans Wasser hinausgeht, und sag zu ihm: 'So spricht Jahwe: Lass mein Volk ziehen, damit es mir dient!", heading: "4. Plage: Stechfliegen" },
      { number: 17, text: "Sonst werde ich die Stechfliegen* zu dir ziehen lassen. Sie werden über dich, deine Hofbeamten und dein Volk kommen. Eure Häuser werden voller Fliegen sein, auch das ganze Land draußen.", footnotes: ["Stechfliegen. Wahrscheinlich sind Hundsfliegen gemeint, die für ihr unangenehmes Stechverhalten bekannt sind. Welche Gottheit sie für die Ägypter repräsentierten, ist nicht bekannt."] },
      { number: 18, text: "Aber das Gebiet von Goschen*, in dem sich mein Volk aufhält, werde ich davon ausnehmen. Dort werden keine Stechfliegen sein, damit du erkennst, dass ich, Jahwe, mitten in deinem Land bin.", footnotes: ["Goschen war ein sehr fruchtbares Gebiet östlich vom Nildelta."] },
      { number: 19, text: "Ich werde ein Zeichen der Erlösung zwischen mein und dein Volk stellen. Morgen wird es geschehen.'\"" },
      { number: 20, text: "Jahwe machte es so. Die Stechfliegen kamen in großen Schwärmen in den Palast des Pharao und seiner Hofbeamten und verheerten ganz Ägypten." },
      { number: 21, text: "Da ließ der Pharao Mose und Aaron zu sich rufen und sagte: \"Geht und schlachtet eurem Gott Opfer. Es muss aber hier im Land geschehen!\"" },
      { number: 22, text: "\"Das können wir nicht\", erwiderte Mose, \"denn unsere Art, Opfer für Jahwe, unseren Gott, zu schlachten, wäre für die Ägypter ein Gräuel. Wenn sie das zu sehen bekämen, würden sie uns gewiss steinigen." },
      { number: 23, text: "Drei Tagereisen weit wollen wir in die Wüste ziehen und Jahwe, unserem Gott, Opfer schlachten, wie er es uns befohlen hat.\"" },
      { number: 24, text: "Da sagte der Pharao: \"Gut, ich will euch gehen lassen, damit ihr Jahwe, eurem Gott, in der Wüste Opfer schlachten könnt. Entfernt euch aber nicht zu weit und betet auch für mich!\"" },
      { number: 25, text: "Mose erwiderte: \"Pass auf! Wenn ich jetzt von dir weggehe, werde ich zu Jahwe beten, dass der Pharao, seine Hofbeamten und sein Volk morgen von den Stechfliegen befreit werden. Aber der Pharao möge uns nicht wieder täuschen, dass er das Volk doch nicht ziehen und Jahwe Opfer bringen lässt!\"" },
      { number: 26, text: "Mose verließ den Pharao und betete zu Jahwe." },
      { number: 27, text: "Jahwe erhörte Moses Gebet und befreite den Pharao, seine Beamten und sein Volk von den Stechfliegen. Keine einzige blieb übrig." },
      { number: 28, text: "Aber der Pharao blieb auch diesmal hart und ließ das Volk nicht ziehen." },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Da sagte Jahwe zu Mose: \"Geh zum Pharao und sag ihm: 'So spricht Jahwe, der Gott der Hebräer: Lass mein Volk ziehen, damit es mir dient!", heading: "5. Plage: Viehpest" },
      { number: 2, text: "Denn wenn du dich weigerst und es weiter festhältst," },
      { number: 3, text: "dann pass auf! Jahwe wird eine schwere Seuche über deine Viehherden auf den Weiden bringen, über Pferde, Esel, Kamele, Rinder* und das Kleinvieh.", footnotes: ["Rinder. Vielleicht verstanden das die Ägypter als Angriff auf ihre Göttin Hator, die Liebe, Freude und Schönheit repräsentierte und als Frau mit Kuhkopf dargestellt wurde. Auch Khnum, eine Gottheit, die als Schafbock dargestellt wurde, könnte gemeint sein, ebenso die Stiergötter Apis, Buchis und Month und selbst der Pharao, der häufig in Stiergestalt abgebildet war."] },
      { number: 4, text: "Außerdem wird Jahwe einen Unterschied zwischen dem Vieh Israels und dem Vieh der Ägypter machen. Vom Vieh, das den Israeliten gehört, wird auch nicht ein Stück verenden." },
      { number: 5, text: "Jahwe hat eine bestimmte Zeit dafür festgesetzt und zwar morgen!'\"" },
      { number: 6, text: "Am nächsten Tag schickte Jahwe die Seuche. Da verendete das ganze Herdenvieh der Ägypter, aber vom Vieh der Israeliten kam kein einziges Tier um." },
      { number: 7, text: "Der Pharao ließ es nachprüfen, und tatsächlich war bei den Israeliten nicht ein einziges Stück Vieh eingegangen. Dennoch blieb der Pharao starrsinnig und ließ das Volk nicht ziehen." },
      { number: 8, text: "Da sagte Jahwe zu Mose und Aaron: \"Nehmt beide Hände voll Ofenruß. Mose soll ihn vor den Augen des Pharao hochwerfen!", heading: "6. Plage: Geschwüre" },
      { number: 9, text: "Er wird dann als feiner Staub auf ganz Ägypten niedergehen und an Menschen und Tieren Geschwüre hervorrufen, die in Blasen aufbrechen.\"" },
      { number: 10, text: "Da nahmen sie Ruß und traten vor den Pharao. Mose warf ihn in die Luft. Schon nach kurzer Zeit litten Menschen und Tiere an aufbrechenden Geschwüren*.", footnotes: ["Geschwüren. Nach dem Glauben der Ägypter war die löwenköpfige Göttin Sechmet sowohl für das Ausbrechen als auch für die Heilung von Seuchen zuständig. Auch der Hauptgott von Theben, Amon-Re, war für das Heilen von Krankheiten zuständig. Beide waren offensichtlich machtlos."] },
      { number: 11, text: "Wegen ihrer Geschwüre konnten die Magier Mose nicht entgegentreten, denn sie waren genauso davon befallen wie alle Ägypter." },
      { number: 12, text: "Doch Jahwe machte den Pharao starrsinnig, dass er auch diesmal nicht auf Mose und Aaron hörte, wie Jahwe es gesagt hatte." },
      { number: 13, text: "Jahwe sagte zu Mose: \"Geh morgen früh zum Pharao und sag zu ihm: 'So spricht Jahwe, der Gott der Hebräer: Lass mein Volk ziehen, damit es mir dient!", heading: "7. Plage: Hagel" },
      { number: 14, text: "Diesmal werde ich dich mit meinen Plagen ins Herz treffen, dich, deine Hofbeamten und dein Volk. Du sollst erkennen, dass niemand auf der ganzen Erde mir gleichkommt." },
      { number: 15, text: "Denn schon jetzt hätte ich dich mit der Pest schlagen können. Dann wärst du vom Erdboden verschwunden." },
      { number: 16, text: "Aber ich habe dich am Leben gelassen, um meine Macht an dir zu beweisen, damit mein Name in der ganzen Welt bekannt gemacht wird.*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 9,17"] },
      { number: 17, text: "Du stellst dich immer noch gegen mein Volk und lässt es nicht ziehen." },
      { number: 18, text: "Morgen um diese Zeit werde ich einen so schweren Hagel kommen lassen, wie es ihn noch nie gegeben hat, solange Ägypten besteht." },
      { number: 19, text: "Lass dein Vieh in Sicherheit bringen und alles, was du noch im Freien hast! Alle Menschen und Tiere, die im Freien bleiben und nicht ins Haus kommen, wird der Hagel erschlagen.'\"" },
      { number: 20, text: "Die Minister des Pharao, die das Wort Jahwes fürchteten, ließen ihre Sklaven und ihr Vieh in die Häuser flüchten." },
      { number: 21, text: "Wer das Wort Jahwes aber nicht ernst nahm, ließ seine Sklaven und sein Vieh draußen." },
      { number: 22, text: "Jahwe sagte zu Mose: \"Streck deine Hand zum Himmel aus! Dann wird in ganz Ägypten ein Hagel auf Menschen, Tiere und Pflanzen niedergehen.\"" },
      { number: 23, text: "Mose hob seinen Stab zum Himmel hoch. Da ließ Jahwe es donnern und hageln. Blitze fuhren auf die Erde herab. So ließ Jahwe den Hagel auf Ägypten niedergehen," },
      { number: 24, text: "und mitten im Hagel zuckten die Blitze. Einen so schweren Hagel hatte es noch nie gegeben, solange Ägypten eine Nation war." },
      { number: 25, text: "Überall im Land tötete der Hagel die Menschen und Tiere, die sich im Freien befanden. Er zerschlug alles, was auf den Feldern wuchs, und brach die Äste von den Bäumen." },
      { number: 26, text: "Nur im Gebiet von Goschen, wo die Israeliten lebten, fiel kein Hagel." },
      { number: 27, text: "Da ließ der Pharao Mose und Aaron rufen und sagte ihnen: \"Diesmal habe ich mich schuldig gemacht. Jahwe ist im Recht, ich und mein Volk sind im Unrecht." },
      { number: 28, text: "Betet zu Jahwe! Die Donnerstimme Gottes und der Hagel, das ist zu viel.* Ich will euch ziehen lassen. Niemand wird euch zurückhalten.\"", footnotes: ["Hagel war in Ägypten etwas ganz Außergewöhnliches. Gewitter waren gefürchtet, weil man sie für Manifestationen der Götter hielt. Die Ägypter merkten, dass Osiris, ihr Gott der Ernte und der Fruchtbarkeit, die Feldfrüchte nicht schützen konnte."] },
      { number: 29, text: "Da sagte Mose zu ihm: \"Sobald ich die Stadt verlassen habe, werde ich meine Hände zu Jahwe ausbreiten. Dann wird der Donner aufhören und kein neuer Hagel mehr entstehen. Daran wirst du erkennen, dass Jahwe die ganze Erde gehört." },
      { number: 30, text: "Aber ich weiß: Du und deine Hofbeamten, ihr fürchtet euch immer noch nicht vor Gott, vor Jahwe!\"" },
      { number: 31, text: "Flachs und Gerste waren zerschlagen, denn die Gerste hatte schon Ähren angesetzt und der Flachs stand in Blüte." },
      { number: 32, text: "Weizen und Dinkel blieben verschont, weil sie später reif werden." },
      { number: 33, text: "Mose verließ den Pharao und ging aus der Stadt hinaus. Dort breitete er seine Hände zu Jahwe aus. Da hörten Donner und Hagel auf, und es regnete auch nicht mehr." },
      { number: 34, text: "Als der Pharao sah, dass das Unwetter aufgehört hatte, blieb er bei seiner Sünde. Er und seine Hofbeamten verschlossen ihr Herz." },
      { number: 35, text: "So blieb der Pharao hart und ließ die Israeliten nicht ziehen, wie Jahwe es durch Mose angekündigt hatte." },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Nun sagte Jahwe zu Mose: \"Geh zum Pharao! Ich selbst habe ihn und seine Hofbeamten hart gemacht, denn ich wollte diese Wunderzeichen unter ihnen tun.", heading: "8. Plage: Heuschrecken" },
      { number: 2, text: "Du sollst deinen Kindern und Enkeln einmal erzählen, wie ich den Ägyptern mitgespielt und welche Wunderzeichen ich unter ihnen getan habe. So werdet ihr erkennen, dass ich, Jahwe, es bin.\"" },
      { number: 3, text: "Mose und Aaron gingen wieder zum Pharao und sagten ihm: \"So spricht Jahwe, der Gott der Hebräer: Wie lange dauert es noch, bis du dich vor mir beugst? Lass mein Volk ziehen, dass es mir dient!" },
      { number: 4, text: "Wenn du dich weigerst, mein Volk ziehen zu lassen, schicke ich morgen Heuschrecken über dein Land." },
      { number: 5, text: "Sie werden das Land so bedecken, dass man den Boden nicht mehr sehen kann. Alles, was der Hagel verschont hat, werden sie abfressen, selbst die Bäume auf euren Feldern." },
      { number: 6, text: "Deine Paläste und die Häuser deiner Hofbeamten und aller Ägypter werden voller Heuschrecken* sein. So etwas haben deine Väter und Vorväter noch nie gesehen, seit sie auf diesem Boden sesshaft wurden.\" Damit drehte Mose sich um und verließ den Pharao.", footnotes: ["Um Heuschrecken abzuschrecken, beteten die Ägypter zu Senehem, der zusammen mit anderen Göttern dafür zuständig war."] },
      { number: 7, text: "Da sagten die Hofbeamten zum Pharao: \"Wie lange soll der uns noch zum Fallstrick sein? Lass die Leute ziehen, dass sie Jahwe, ihrem Gott, dienen! Siehst du nicht, dass Ägypten zugrunde geht?\"" },
      { number: 8, text: "Darauf wurden Mose und Aaron zum Pharao zurückgebracht. Er sagte zu ihnen: \"Zieht hin und dient Jahwe, eurem Gott! Wer soll denn alles mitgehen?\"" },
      { number: 9, text: "Mose erwiderte: \"Mit unseren Jungen und Alten wollen wir gehen, mit unseren Söhnen und Töchtern, mit unserm Kleinvieh und mit unseren Rindern, denn es ist ein Fest Jahwes für uns!\"" },
      { number: 10, text: "\"Dann möge Jahwe so wenig mit euch sein, wie ich euch mit euren Kindern ziehen lasse!\", sagte der Pharao. \"Es ist doch klar, dass ihr Böses im Schild führt!" },
      { number: 11, text: "Nein, so nicht! Zieht ihr Männer hin und dient Jahwe, denn das wolltet ihr doch!\" Damit ließ der Pharao sie hinauswerfen." },
      { number: 12, text: "Da sagte Jahwe zu Mose: \"Streck deine Hand über Ägypten aus, um die Heuschrecken kommen zu lassen. Sie sollen alles abfressen – alles, was der Hagel übrig gelassen hat!\"" },
      { number: 13, text: "Mose streckte seinen Stab über Ägypten aus. Da ließ Jahwe den ganzen Tag und die ganze Nacht einen Ostwind über das Land wehen. Am nächsten Morgen hatte der Ostwind die Heuschrecken gebracht." },
      { number: 14, text: "Sie kamen über ganz Ägypten und ließen sich in riesigen Schwärmen nieder. Eine solche Menge Heuschrecken hatte es noch nie gegeben und wird es auch nie wieder geben." },
      { number: 15, text: "Sie verfinsterten den Himmel und bedeckten den ganzen Boden. Sie fraßen alles Grüne am Boden ab, die Früchte der Bäume, überhaupt alles, was der Hagel verschont hatte. In ganz Ägypten blieb nichts Grünes übrig." },
      { number: 16, text: "Da ließ der Pharao in aller Eile Mose und Aaron herbeirufen und sagte: \"Ich habe mich an Jahwe, eurem Gott, versündigt und auch an euch." },
      { number: 17, text: "Vergebt mir meine Sünde nur noch dieses eine Mal! Bittet Jahwe, euren Gott, dass er diese tödliche Plage von mir nimmt.\"" },
      { number: 18, text: "Mose verließ den Pharao wieder und betete zu Jahwe." },
      { number: 19, text: "Da ließ Jahwe den Wind umschlagen. Ein sehr starker Westwind trug die Heuschrecken weg und warf sie ins Schilfmeer. In ganz Ägypten blieb nicht eine davon übrig." },
      { number: 20, text: "Aber Jahwe machte den Pharao starrsinnig, sodass er die Israeliten nicht ziehen ließ." },
      { number: 21, text: "Darauf sagte Jahwe zu Mose: \"Streck deine Hand zum Himmel aus! Dann wird eine solche Finsternis* über Ägypten kommen, dass man sie mit Händen greifen kann.\"", heading: "9. Plage: Finsternis", footnotes: ["Die Finsternis werden die Ägypter als Angriff auf ihren Hauptgott Re verstanden haben, der, begleitet von seinem Wesir Thot, dem ägyptischen Mondgott, und seiner Tochter Maat, der Verkörperung der kosmischen Ordnung, den Himmelsozean überquert."] },
      { number: 22, text: "Mose erhob seine Hand, und drei Tage lang wurde es stockfinster in ganz Ägypten." },
      { number: 23, text: "Keiner sah den anderen. Drei Tage lang stand niemand von seinem Platz auf. Nur die Israeliten hatten Licht in ihren Siedlungen." },
      { number: 24, text: "Da ließ der Pharao Mose rufen und sagte: \"Geht und dient Jahwe! Eure Kinder dürfen mit. Nur eure Schafe, Ziegen und Rinder müssen zurückbleiben.\"" },
      { number: 25, text: "Mose erwiderte: \"Willst du uns vielleicht Tiere zur Verfügung stellen, die wir Jahwe, unserem Gott, als Schlacht- und Brandopfer* darbringen können?", footnotes: ["Schlachtopfer. Allgemeine Bezeichnung für jedes Opfer, bei dem ein Tier geschlachtet wurde. Beim Brandopfer wurde das geschlachtete Tier vollständig auf dem Altar verbrannt."] },
      { number: 26, text: "Nein, auch unser Vieh zieht mit! Nicht eine Klaue bleibt zurück. Denn davon werden wir das nehmen, womit wir Jahwe dienen. Wir wissen ja erst, wenn wir dort sind, welche Tiere wir zur Verehrung Jahwes brauchen.\"" },
      { number: 27, text: "Aber Jahwe machte den Pharao starrsinnig, sodass er nicht bereit war, sie ziehen zu lassen." },
      { number: 28, text: "\"Verschwinde!\", rief der Pharao. \"Hüte dich, mir jemals wieder unter die Augen zu kommen, sonst bist du ein toter Mann!\"" },
      { number: 29, text: "\"Du hast Recht\", erwiderte Mose. \"Ich werde dir nie wieder unter die Augen kommen.\"" },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Nun hatte Jahwe zu Mose gesagt: \"Noch eine Plage will ich über den Pharao und ganz Ägypten bringen. Dann wird er euch ziehen lassen. Ja, er wird euch nicht nur ziehen lassen, sondern euch regelrecht von hier fortjagen.", heading: "Ankündigung der 10. Plage" },
      { number: 2, text: "Sag dem Volk, dass jeder Mann seinen Nachbarn und jede Frau ihre Nachbarin um silberne und goldene Schmuckstücke bitten soll.\"" },
      { number: 3, text: "Jahwe hatte dem Volk hohes Ansehen bei den Ägyptern verschafft. Und Mose wurde in ganz Ägypten sehr hoch geachtet, sowohl von den Hofbeamten des Pharao als auch von der Bevölkerung." },
      { number: 4, text: "Bevor Mose ging, sagte er zum Pharao: \"So spricht Jahwe: 'Um Mitternacht werde ich durch Ägypten gehen." },
      { number: 5, text: "Dann werden alle Erstgeborenen in Ägypten sterben,* vom ältesten Sohn des Pharao an, der einmal auf seinem Thron sitzen soll, bis zum Erstgeborenen der Sklavin, die an der Handmühle kniet. Selbst beim Vieh wird alle Erstgeburt sterben.", footnotes: ["Erstgeborenen ... sterben. Diese Plage traf den Pharao direkt, der nach dem Glauben der Ägypter als Gott auf Erden eine Vermittlerfunktion zwischen der diesseitigen und jenseitigen Welt hatte. Ihr Pharaonen-Gott war völlig machtlos."] },
      { number: 6, text: "Dann wird es ein großes Geschrei in ganz Ägypten geben, wie es keins je gegeben hat oder geben wird.'" },
      { number: 7, text: "Aber keinen der Israeliten wird auch nur ein Hund anknurren. Weder Menschen noch Tieren wird etwas geschehen. Denn ihr sollt merken, dass Jahwe einen Unterschied zwischen den Ägyptern und den Israeliten macht." },
      { number: 8, text: "Dann werden deine Hofbeamten zu mir kommen und mich auf Knien anflehen: 'Zieht endlich weg, du und das ganze Volk, das dir folgt!' Und dann werden wir das Land verlassen!\" Glühend vor Zorn ging er vom Pharao weg." },
      { number: 9, text: "Jahwe hatte allerdings zu Mose gesagt: \"Der Pharao wird nicht auf euch hören, damit meine Wunder sich im Land Ägypten mehren.\"" },
      { number: 10, text: "Mose und Aaron haben all diese Wunderzeichen vor dem Pharao gewirkt. Doch Jahwe hatte den Pharao hart gemacht, sodass er die Israeliten nicht aus seinem Land ziehen ließ." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Jahwe sagte zu Mose und Aaron, als sie noch in Ägypten waren:", heading: "Das Passafest" },
      { number: 2, text: "\"Dieser Monat soll von jetzt an der Beginn des Jahres* für euch sein.", footnotes: ["Beginn des Jahres. Gemeint ist das heilige Jahr, das mit dem ersten Erscheinen der schmalen Mondsichel nach der Tag-und-Nacht-Gleiche im Frühjahr (März/April) begann. Der Monat wurde Abib (Ährenmonat), später Nisan genannt. Das bürgerliche Jahr begann mit dem Herbstmonat (Etanim) nach der herbstlichen Tag-und-Nacht-Gleiche."] },
      { number: 3, text: "Sagt der ganzen Gemeinschaft Israels: 'Am 10. dieses Monats soll jeder ein Lamm für seine Familie auswählen, ein Lamm für jedes Haus." },
      { number: 4, text: "Ist die Familie zu klein, um ein ganzes Tier zu essen, dann soll sie sich mit der Nachbarsfamilie zusammentun. Es sollen so viele Menschen von dem Lamm essen, dass es für alle reicht und nichts übrig bleibt." },
      { number: 5, text: "Es muss ein Schaf- oder Ziegenböckchen sein, einjährig und ohne Fehler." },
      { number: 6, text: "Ihr sollt es bis zum 14. des Monats gesondert halten und am späten Nachmittag* dieses Tages schlachten.", footnotes: ["später Nachmittag. Wörtlich: Zwischen den zwei Abenden. Gemeint ist wahrscheinlich die Zeit zwischen Niedergang (15 Uhr) und Untergang der Sonne."] },
      { number: 7, text: "Dann sollen sie etwas von dem Blut nehmen und es an den Türsturz und die beiden Türpfosten streichen. Das muss bei den Häusern geschehen, wo sie das Lamm essen." },
      { number: 8, text: "Das Fleisch muss am Feuer gebraten und noch in derselben Nacht zusammen mit ungesäuertem Fladenbrot und bitteren Kräutern gegessen werden." },
      { number: 9, text: "Ihr dürft das Fleisch nicht roh* oder im Wasser gekocht essen. Es muss über dem Feuer gebraten sein, und zwar das ganze Tier mit Kopf, Unterschenkeln und Innereien.", footnotes: ["roh. Oder: halbgar. Das Wort ist in diesem Sinn sonst nirgends im Alten Testament belegt. Seine Bedeutung kann nur aus dem Zusammenhang geschlossen werden."] },
      { number: 10, text: "Es darf nichts davon bis zum Morgen übrig bleiben. Die Reste müsst ihr verbrennen." },
      { number: 11, text: "Ihr sollt euch beim Essen beeilen und schon für die Reise angezogen* sein, Sandalen tragen und den Wanderstab in der Hand haben. Es ist ein Passa für Jahwe.", footnotes: ["angezogen. Wörtlich: Die Lenden gegürtet. Das fußlange Obergewand wurde mit einem Gurt um die Hüften hochgerafft."] },
      { number: 12, text: "In dieser Nacht werde ich durch Ägypten gehen und jede männliche Erstgeburt bei Mensch und Vieh töten. An allen Göttern Ägyptens werde ich das Gericht vollstrecken,* ich, Jahwe.", footnotes: ["an allen Göttern … Gericht vollstrecken. Viele Götter Ägyptens wurden durch Tiere repräsentiert und viele Tiere waren den Göttern geweiht. Wenn die Götter nicht einmal \"ihre\" Tiere schützen konnten, geschweige denn die Menschen, offenbarte das ihre völlige Nutzlosigkeit."] },
      { number: 13, text: "Das Blut an den Häusern, in denen ihr euch befindet, soll ein Schutzzeichen für euch sein. Wenn ich das Blut sehe, werde ich vorübergehen*, und der Schlag, mit dem ich das Land Ägypten treffe, wird euch nicht verderben.", footnotes: ["vorübergehen. Hebräisch: pasachti, wovon Passa abgeleitet ist."] },
      { number: 14, text: "Dieser Tag soll für euch ein Gedenktag sein. Ihr sollt ihn als Fest für Jahwe feiern. Das gilt für euch und alle Generationen nach euch.'\"" },
      { number: 15, text: "\"Vom Passa-Abend an sollt ihr sieben Tage lang ungesäuerte Brotfladen essen. Vorher müsst ihr den Sauerteig aus euren Häusern entfernen. Jeder, der in diesen sieben Tagen etwas mit Sauerteig isst, muss sterben und so aus Israel beseitigt werden.", heading: "Das Fest der ungesäuerten Brote" },
      { number: 16, text: "Am ersten und am siebten Tag sollt ihr euch zu einem heiligen Fest versammeln. Da muss jede Arbeit ruhen. Nur das Essen darf zubereitet werden." },
      { number: 17, text: "Haltet das Fest der ungesäuerten Brote auch in allen kommenden Generationen, denn am ersten Tag dieses Festes habe ich euch in geordneten Scharen aus dem Land Ägypten herausgeführt." },
      { number: 18, text: "Vom Abend des 14. bis zum Abend des 21. April* müsst ihr ungesäuerte Brotfladen essen.", footnotes: ["April. Zum Datum siehe unter \"Schaltmonat\" im Vorwort des Übersetzers."] },
      { number: 19, text: "Sieben Tage lang darf kein Sauerteig in euren Häusern zu finden sein. Denn jeder, der etwas mit Sauerteig isst, muss sterben und so aus der Gemeinschaft Israels beseitigt werden. Das gilt für den Einheimischen genauso wie für den Fremden." },
      { number: 20, text: "In dieser Zeit dürft ihr nichts essen, was mit Sauerteig zubereitet ist. Das gilt für alle eure Wohnsitze.\"" },
      { number: 21, text: "Mose rief die Ältesten Israels zusammen und sagte zu ihnen: \"Sucht euch ein Schaf- oder Ziegenböckchen für eure Sippen heraus und schlachtet es für das Passa!", heading: "10. Plage: Tötung der Erstgeborenen" },
      { number: 22, text: "Nehmt dann ein Büschel Ysop* und taucht ihn in das Blut, das ihr in einer Schüssel aufgefangen habt! Bestreicht damit den Türsturz und die beiden Türpfosten. Danach darf bis zum nächsten Morgen niemand mehr das Haus verlassen.", footnotes: ["Ysop, ein Busch mit stark riechenden Blättern, der bei Reinigungsopfern zum Besprengen verwendet wurde. Seine Stängel werden bis zu 80 Zentimeter lang."] },
      { number: 23, text: "Jahwe wird durch das Land gehen, um die Ägypter zu töten. Wenn er das Blut am Türsturz und den beiden Türpfosten sieht, wird er an dieser Tür vorübergehen und dem todbringenden Engel nicht gestatten, eure Häuser zu betreten." },
      { number: 24, text: "Haltet euch an diese Anweisungen! Sie gelten euch und euren Nachkommen als feste Regel." },
      { number: 25, text: "Auch wenn ihr in das Land kommt, das Jahwe euch geben wird, sollt ihr an diesem Brauch festhalten." },
      { number: 26, text: "Und wenn euch eure Kinder fragen, was das bedeutet," },
      { number: 27, text: "dann erklärt ihnen: 'Es ist das Passaopfer für Jahwe, der in Ägypten an den Häusern der Israeliten vorüberging und uns verschonte, als er den Schlag gegen die Ägypter führte.'\"Da warf sich das Volk zur Anbetung nieder." },
      { number: 28, text: "Dann gingen die Israeliten und machten alles genauso, wie Jahwe es Mose und Aaron befohlen hatte." },
      { number: 29, text: "Um Mitternacht erschlug Jahwe alle Erstgeburt in Ägypten vom ältesten Sohn des Pharao an, der einmal auf seinem Thron sitzen sollte, bis zum Erstgeborenen des Sträflings im Gefängnis, ja selbst die Erstgeburt beim Vieh." },
      { number: 30, text: "Der Pharao und alle seine Hofbeamten fuhren aus dem Schlaf, ganz Ägypten schreckte in dieser Nacht hoch. Überall im Land hörte man Wehgeschrei, denn es gab kein Haus, in dem nicht ein Toter war." },
      { number: 31, text: "Noch in der Nacht ließ der Pharao Mose und Aaron zu sich rufen und sagte zu ihnen: \"Verlasst sofort mein Volk, ihr und die Israeliten! Geht und dient Jahwe, wie ihr es wolltet!", heading: "Der Auszug Israels" },
      { number: 32, text: "Nehmt eure Schafe, Ziegen und Rinder mit, wie ihr es verlangt habt! Geht und segnet auch mich!\"" },
      { number: 33, text: "Die Ägypter drängten das Volk und wollten sie so schnell wie möglich aus dem Land haben. \"Sonst kommen wir alle noch um\", sagten sie." },
      { number: 34, text: "So nahmen die Israeliten ihren noch ungesäuerten Brotteig in Backschüsseln mit. Sie wickelten die Schüsseln in ihre Kleidung und trugen sie auf den Schultern." },
      { number: 35, text: "Auf Moses Anweisung hatten sie sich von den Ägyptern silberne und goldene Schmuckstücke und festliche Kleidung erbeten." },
      { number: 36, text: "Jahwe hatte ihnen bei den Ägyptern Achtung verschafft, so dass sie ihnen gaben, was sie verlangten. Auf diese Weise plünderten sie die Ägypter aus." },
      { number: 37, text: "Die Israeliten brachen von Ramses* in Richtung Sukkot* auf. Es waren etwa 600.000 Männer zu Fuß, die Kinder nicht mitgerechnet.", footnotes: ["Ramses war eine Stadt im östlichen Nildelta, etwa 30 km südlich von Tanis/Zoan.", "Sukkot war vielleicht das heutige Tell el-Maskuta im Wadi Tumilat, 14 km westlich von Ismailia im Nordosten Ägyptens."] },
      { number: 38, text: "Auch eine Menge Nichtisraeliten hatte sich ihnen angeschlossen. Dazu kamen große Herden an Schafen, Ziegen und Rindern." },
      { number: 39, text: "Aus dem ungesäuerten Teig, den sie aus Ägypten mitgenommen hatten, backten sie Fladenbrote. Sie waren ja aus Ägypten vertrieben worden und hatten nicht warten können. So hatten sie auch keine Verpflegung für unterwegs vorbereitet." },
      { number: 40, text: "430 Jahre* hatten die Israeliten in Ägypten zugebracht.", footnotes: ["430 Jahre. Abraham war die Zahl von rund 400 Jahren genannt worden (1. Mose 15,13)."] },
      { number: 41, text: "Nach Ablauf dieser Zeit zogen die Heerscharen Jahwes aus dem Land Ägypten weg." },
      { number: 42, text: "Jahwe wachte über sie, als er sie in der Nacht aus Ägypten führte. Seitdem gilt diese Nacht für die Israeliten als Nacht des Wachens zur Ehre Jahwes." },
      { number: 43, text: "Jahwe sagte zu Mose und Aaron: \"Beim Passa sollt ihr folgende Vorschriften beachten: Es darf kein Fremder daran teilnehmen.", heading: "Vorschriften für das Passafest" },
      { number: 44, text: "Doch ein ausländischer Sklave, der von einem Israeliten gekauft und auch beschnitten* worden ist, darf mitessen,", footnotes: ["beschnitten. Siehe 1. Mose 17,9-14!"] },
      { number: 45, text: "aber kein ausländischer Nachbar oder Lohnarbeiter." },
      { number: 46, text: "Das Lamm muss in dem Haus gegessen werden, in dem es zubereitet wurde. Weder darfst du ein Stück davon nach draußen bringen noch einen Knochen an ihm zerbrechen.*", footnotes: ["Wird im Neuen Testament von Johannes in Bezug auf Jesus zitiert: Johannes 19,36"] },
      { number: 47, text: "Die ganze Gemeinschaft Israels soll das Passa feiern." },
      { number: 48, text: "Wenn ein Fremder bei euch lebt und das Passa für Jahwe mitfeiern will, muss er alle männlichen Familienangehörigen beschneiden lassen. Dann gilt er als Einheimischer und darf das Passa mitessen. Kein Unbeschnittener darf davon essen." },
      { number: 49, text: "Ein und dasselbe Gesetz gilt für den Einheimischen und den Fremden, der bei euch lebt.\"" },
      { number: 50, text: "Alle Israeliten machten es genauso, wie Jahwe es Mose und Aaron befohlen hatte." },
      { number: 51, text: "An diesem Tag führte Jahwe die Israeliten in geordneten Scharen aus Ägypten heraus." },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Jahwe hatte auch zu Mose gesagt:" },
      { number: 2, text: "\"Jede Erstgeburt soll mir geweiht werden!* Alles, was das erste Mal aus einem Mutterschoß kommt, gehört mir! Das soll bei den Israeliten für Mensch und Tier gelten!\"", footnotes: ["Wird im Neuen Testament von Lukas zitiert: Lukas 2,23."] },
      { number: 3, text: "Mose sagte nun zum Volk: \"Erinnert euch immer an diesen Tag, an dem ihr aus dem Sklavenhaus Ägypten gezogen seid! Denn Jahwe hat euch mit starker Hand von dort herausgeführt. Darum soll nichts gegessen werden, worin Sauerteig ist.", heading: "Das Fest der ungesäuerten Brote" },
      { number: 4, text: "Heute im Ährenmonat* zieht ihr aus.", footnotes: ["Ährenmonat. Hebräisch: Abib. Entspricht dem April 1446 v.Chr. Zum Datum siehe unter Biblische Chronologie im Vorwort des Übersetzers."] },
      { number: 5, text: "Jahwe hat euren Vätern geschworen, euch das Land zu geben, das von Milch und Honig überfließt. Wenn Jahwe euch dann in das Land bringt, das jetzt den Hetitern, Amoritern, Hiwitern und Jebusitern gehört, dann sollt ihr das Fest immer in diesem Monat begehen." },
      { number: 6, text: "Sieben Tage lang sollt ihr ungesäuerte Brotfladen essen, und am siebten Tag ein Fest für Jahwe feiern." },
      { number: 7, text: "Während dieser sieben Tage dürft ihr nur ungesäuerte Brotfladen essen. Nichts, was mit Sauerteig zubereitet wurde, soll bei euch und in eurem ganzen Wohngebiet gesehen werden!" },
      { number: 8, text: "Deinem Sohn sollst du es so erklären: 'Wir tun das zur Erinnerung an das, was Jahwe für uns getan hat, als wir aus Ägypten zogen.'" },
      { number: 9, text: "Das soll dir wie ein Zeichen auf Hand und Stirn sein, damit du das Gesetz Jahwes in deinem Mund führst! Denn Jahwe hat euch mit starker Hand aus Ägypten herausgeführt." },
      { number: 10, text: "Jahr für Jahr zur festgesetzten Zeit sollt ihr euch an diese Ordnung halten!\"" },
      { number: 11, text: "Weiter sagte Mose: \"Wenn Jahwe euch in das Land der Kanaaniter bringt und es euch übergibt, wie er das euren Vorfahren und euch selbst geschworen hat,", heading: "Bestimmungen für die Erstgeburten" },
      { number: 12, text: "dann sollt ihr jedes männliche Erstgeborene Jahwe übergeben. Auch jeder erste männliche Wurf eines Muttertiers gehört Jahwe." },
      { number: 13, text: "Jede Erstgeburt eines Esels sollt ihr mit einem Lamm auslösen. Wer das nicht tun will, muss dem Fohlen das Genick brechen. Auch für eure erstgeborenen Söhne müsst ihr Jahwe einen Ersatz geben." },
      { number: 14, text: "Wenn dein Sohn dich künftig fragt, was das bedeutet, dann sollst du ihm sagen: 'Jahwe hat uns mit starker Hand aus dem Sklavenhaus von Ägypten herausgeführt." },
      { number: 15, text: "Denn als der Pharao sich weigerte, uns ziehen zu lassen, brachte Jahwe alle Erstgeborenen im Land Ägypten bei Mensch und Vieh um. Darum opfere ich Jahwe jede männliche Erstgeburt, aber meinen erstgeborenen Sohn löse ich durch ein Ersatzopfer aus.'" },
      { number: 16, text: "Das soll euch wie ein Zeichen auf Hand und Stirn sein, denn Jahwe hat euch mit starker Hand aus Ägypten herausgeführt.\"" },
      { number: 17, text: "Als der Pharao das Volk ziehen ließ, führte Gott es nicht den Weg durch das Land der Philister,* obwohl das der kürzeste Weg gewesen wäre, denn Gott dachte: \"Wenn das Volk merkt, dass es kämpfen muss, könnte es seine Meinung ändern und nach Ägypten zurückkehren.\"", heading: "Zug zum Rand der Wüste", footnotes: ["Weg ... Philister. Es wäre der Weg an der Küste des Mittelmeeres entlang gewesen, der bei ungestörter Reise nur zehn Tage gedauert hätte. Er war aber einerseits durch eine Kette ägyptischer Festungen gesichert und hätte andererseits in Kanaan zuerst durch das Gebiet der kriegerischen Philister geführt."] },
      { number: 18, text: "Aus diesem Grund ließ Gott das Volk einen Umweg machen und führte es den Wüstenweg zum Schilfmeer. Die Israeliten zogen wie ein Kriegsheer aus Ägypten." },
      { number: 19, text: "Mose nahm die Gebeine Josefs mit, denn dieser hatte es die Söhne Israels ausdrücklich schwören lassen und gesagt: \"Gott wird euch gewiss wieder aufsuchen. Nehmt dann meine Gebeine von hier mit!\"*", footnotes: ["Gebeine ... mit. Siehe 1. Mose 50,25!"] },
      { number: 20, text: "Von Sukkot zogen sie nach Etam*. Dort, am Rand der Wüste, schlugen sie ihr Lager auf.", footnotes: ["Etam. Das ägyptische Wort bedeutet \"Festung\". Wahrscheinlich handelte es sich um eine der Festungen, die die Ostgrenze von Ägypten bewachten."] },
      { number: 21, text: "Jahwe zog vor ihnen her, um ihnen den Weg zu zeigen. Tagsüber führte er sie in einer Wolkensäule und nachts in einer Feuersäule, um ihnen zu leuchten. So konnten sie Tag und Nacht weiterziehen." },
      { number: 22, text: "Tagsüber sahen sie die Wolkensäule vor sich, nachts die Feuersäule." },
    ] },
    { number: 14, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Die Reise zum Sinai (14-18)\nIsrael am Schilfmeer" },
      { number: 2, text: "\"Befiehl den Israeliten, umzukehren und ihr Lager vor Pi-Hahirot zwischen Migdol* und dem Meer aufzuschlagen, gegenüber von Baal-Zefon.", footnotes: ["Migdol ist das semitische Wort für Festung. Alle genannten Orte können Festungen meinen, die in der Nähe des heutigen Suez-Kanals lagen. Pi-Hahirot und Migdol werden in ägyptischen Quellen genannt."] },
      { number: 3, text: "Der Pharao wird denken: 'Sie irren ziellos im Land herum und sitzen in der Wüste fest.'" },
      { number: 4, text: "Ich werde ihn so starrsinnig machen, dass er euch verfolgen wird. Dann will ich ihm und seinem ganzen Heer meine Macht zeigen. Die Ägypter sollen erkennen, dass ich Jahwe bin.\" Die Israeliten folgten dem Befehl." },
      { number: 5, text: "Als man dem König von Ägypten meldete, Israel sei geflohen, bereuten er und seine Hofbeamten ihre Nachgiebigkeit. Sie sagten: \"Wie konnten wir Israel nur aus unserem Dienst entlassen!\"" },
      { number: 6, text: "So ließ er seinen Streitwagen anspannen und bot seine ganze Kriegsmacht auf." },
      { number: 7, text: "Alle verfügbaren Streitwagen Ägyptens folgten den 600 Wagen seiner Elitetruppe. Auf allen war ein dritter zusätzlicher Wagenkämpfer*.", footnotes: ["Wagenkämpfer. Die Streitwagenbesatzung bestand normalerweise aus dem Wagenlenker und einem Bogenschützen."] },
      { number: 8, text: "Jahwe hatte den Pharao, den König von Ägypten, starrsinnig gemacht, so dass er die Israeliten verfolgte, die kühn* aus dem Land zogen.", footnotes: ["kühn. Wörtlich: Mit erhobener Hand."] },
      { number: 9, text: "Die Ägypter jagten mit allen Pferden und Streitwagen des Pharao, mit seinen Reitern und seiner ganzen Streitmacht hinter ihnen her und holten sie ein, während sie bei Pi-Hahirot gegenüber Baal-Zefon am Meer lagerten." },
      { number: 10, text: "Als der Pharao sich näherte und die Israeliten sahen, dass die Ägypter sie verfolgten, wurden sie von Angst gepackt und schrien zu Jahwe." },
      { number: 11, text: "Mose warfen sie vor: \"Es gab wohl keine Gräber in Ägypten, dass du uns zum Sterben in die Wüste geführt hast? Was hast du uns da angetan! Warum hast du uns aus Ägypten herausgeführt?" },
      { number: 12, text: "Haben wir es dir nicht schon dort gesagt: 'Lass uns in Ruhe, wir wollen den Ägyptern dienen!'? Wir wären besser Sklaven der Ägypter, als hier in der Wüste umzukommen!\"" },
      { number: 13, text: "Mose antwortete ihnen: \"Habt keine Angst! Stellt euch auf und schaut euch an, wie Jahwe euch heute retten wird! Denn die Ägypter, die ihr heute noch seht, werdet ihr nie wieder erblicken." },
      { number: 14, text: "Jahwe wird für euch kämpfen, ihr selbst braucht gar nichts zu tun.\"" },
      { number: 15, text: "Jahwe sagte zu Mose: \"Was schreist du zu mir? Sag den Israeliten, sie sollen aufbrechen.", heading: "Israels Rettung durch das Schilfmeer hindurch" },
      { number: 16, text: "Und du heb deinen Stab hoch und streck deine Hand über das Meer aus! Spalte es, damit die Israeliten auf dem Trockenen ins Meer hineingehen können!" },
      { number: 17, text: "Ich aber werde die Ägypter so starrsinnig machen, dass sie hinter ihnen her jagen. Dann werde ich am Pharao und seiner ganzen Heeresmacht, an seinen Streitwagen und Reitern meine Macht beweisen." },
      { number: 18, text: "Die Ägypter sollen erkennen, dass ich Jahwe bin, wenn ich am Pharao, seinen Wagen und Männern meine Macht beweise.\"" },
      { number: 19, text: "Der Engel Gottes, der den Zug der Israeliten anführte, ging nun ans Ende der Kolonne, und die Wolkensäule, die sonst immer vor ihnen war, stellte sich hinter sie." },
      { number: 20, text: "So kam sie zwischen die beiden Heerlager. Auf der Seite der Ägypter stand eine finstere Wolke, aber auf der Seite der Israeliten erhellte sie die Nacht. So konnten die Ägypter ihnen die ganze Nacht nicht näherkommen." },
      { number: 21, text: "Mose streckte seine Hand über das Meer aus, und Jahwe ließ die ganze Nacht einen starken Ostwind wehen, der das Wasser zurücktrieb. So verwandelte sich das Meer in trockenes Land. Das Wasser hatte sich geteilt." },
      { number: 22, text: "Die Israeliten gingen auf dem Trockenen mitten durchs Meer. Das Wasser stand wie eine Mauer auf beiden Seiten." },
      { number: 23, text: "Die Ägypter verfolgten sie. Alle Pferde und Streitwagen des Pharao und alle seine Reiter jagten ins Meer." },
      { number: 24, text: "Kurz vor Tagesanbruch schaute Jahwe in der Feuer- und Wolkensäule auf das Heer der Ägypter herab und brachte es durcheinander." },
      { number: 25, text: "Er ließ die Räder ihrer Streitwagen sich lockern und sie nur mühsam vorankommen. Da sagten die Ägypter: \"Wir müssen fliehen! Jahwe kämpft für Israel und ist gegen uns.\"" },
      { number: 26, text: "Da sagte Jahwe zu Mose: \"Streck deine Hand über das Meer aus! Dann wird das Wasser zurückfluten und die Ägypter, ihre Streitwagen und ihre Reiter bedecken.\"" },
      { number: 27, text: "Mose streckte seine Hand aus, und bei Tagesanbruch strömte das Wasser zurück. Die fliehenden Ägypter rannten geradewegs hinein. Jahwe trieb sie mitten ins Meer." },
      { number: 28, text: "Das Wasser kehrte zurück und bedeckte Wagen und Reiter, die ganze Heeresmacht des Pharao, die den Israeliten ins Meer gefolgt war. Nicht einer von ihnen entkam." },
      { number: 29, text: "Die Israeliten aber waren auf dem Trockenen mitten durchs Meer gegangen, während das Wasser wie eine Mauer links und rechts neben ihnen stand." },
      { number: 30, text: "So rettete Jahwe an diesem Tag die Israeliten aus der Gewalt der Ägypter. Israel sah die Ägypter nur noch tot am Strand liegen." },
      { number: 31, text: "Als den Israeliten bewusst wurde, dass Jahwe seine große Macht an den Ägyptern demonstriert hatte, fürchteten sie Jahwe. Sie glaubten an ihn und vertrauten seinem Diener Mose." },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Damals sangen Mose und die Israeliten ein Lied zur Ehre Jahwes:Jahwe will ich singen, / denn hoch ist er und unerreicht. / Pferd und Reiter warf er ins Meer.", heading: "Das Danklied der Befreiten" },
      { number: 2, text: "Jah* ist meine Stärke und mein Lied, / denn er ist mein Retter geworden. / Er ist mein Gott, / ihn will ich preisen. / Er war schon der Gott meines Vaters, / er, den ich lobe.", footnotes: ["Jah. Kurzform für Jahwe."] },
      { number: 3, text: "Jahwe ist ein Kämpfer, / Jahwe ist sein Name!" },
      { number: 4, text: "Pharaos Wagen und seine ganze Macht, / die warf er ins Meer. / Die Elite seiner Wagenkämpfer / ist im Schilfmeer versunken." },
      { number: 5, text: "Die Fluten haben sie bedeckt. / Sie fuhren in die Tiefe wie ein Stein." },
      { number: 6, text: "Jahwe, deine Rechte ist mit Kraft geschmückt, / deine Hand zerschmettert den Feind!" },
      { number: 7, text: "In deiner unerreichten Größe / wirfst du deine Gegner zu Boden. / Du schickst deinen glühenden Zorn; / er frisst sie wie Feuer das Stroh." },
      { number: 8, text: "Du schnaubtest vor Zorn, / da türmten sich die Wasser, / da standen die Wogen als Wall. / Die Fluten erstarrten mitten im Meer." },
      { number: 9, text: "Es prahlte der Feind: \"Ich will sie jagen, ich hole sie ein, / verteile die Beute, stille die Gier! / Ich zücke mein Schwert und lösche sie aus!\"" },
      { number: 10, text: "Doch als dein Atem blies, verschlang sie das Meer. / Sie versanken wie Blei in den mächtigen Wogen." },
      { number: 11, text: "Wer von allen Göttern ist dir gleich, Jahwe? / Wer ist so herrlich und heilig wie du, / der Furcht erregt und Lobgesänge weckt, / der Wunderbares tut?" },
      { number: 12, text: "Du strecktest die Hand aus, / und schon verschlang sie die Erde." },
      { number: 13, text: "Du lenkst mit Liebe das gerettete Volk, / führst es in Kraft zu deiner heiligen Wohnung." },
      { number: 14, text: "Als die Völker das hörten, erzitterten sie; / ein Schütteln packte die Philister." },
      { number: 15, text: "Da erschraken die Anführer Edoms, / die Mächtigen Moabs begannen zu zittern, / Kanaans Bewohner verloren den Mut." },
      { number: 16, text: "Furcht und Schrecken packte sie. / Vor deinem mächtigen Arm / wurden sie starr wie Stein, / bis dein Volk hindurchzog, Jahwe, / bis hindurchzog das Volk, das dir gehört." },
      { number: 17, text: "Du bringst sie hin, du pflanzt sie ein / auf dem Berg, der dir gehört, / am Ort, wo du wohnst, Jahwe, / beim Heiligtum, das du errichtet hast." },
      { number: 18, text: "Jahwe ist König für immer und ewig!" },
      { number: 19, text: "Die Pferde und Streitwagen des Pharao waren also mit den Reitern ins Meer gezogen, und Jahwe hatte das Wasser über sie zurückfluten lassen. Die Israeliten aber waren auf dem Trockenen mitten durchs Meer gegangen." },
      { number: 20, text: "Dann nahm die Prophetin Mirjam, Aarons Schwester, ihr Tamburin zur Hand. Alle Frauen schlossen sich ihr an. Sie schlugen ihre Handpauken und zogen im Reigentanz hinter ihr her.", heading: "Das Lied der Mirjam" },
      { number: 21, text: "Mirjam sang ihnen zu:Singt Jahwe, denn hoch ist er und unerreicht! / Pferd und Reiter warf er ins Meer." },
      { number: 22, text: "Mose ließ Israel vom Schilfmeer aufbrechen. Sie zogen los und kamen in die Wüste Schur*. Drei Tage waren sie in der Wüste unterwegs und fanden kein Wasser.", heading: "Das Wasser von Mara und von Elim", footnotes: ["Schur. Die Wüste liegt im nordwestlichen Teil der Halbinsel Sinai. In 4. Mose 33,8 wird sie Wüste Etam genannt. Schur ist das hebräische und Etam das ägyptische Wort für \"Festungswall\"."] },
      { number: 23, text: "Dann kamen sie nach Mara*. Dort gab es Wasser, aber man konnte es nicht trinken, weil es bitter war. Deshalb hatte der Ort auch den Namen Mara, Bitterwasser.", footnotes: ["Mara war eine Oase, ungefähr drei Tagereisen von Ägypten entfernt, vielleicht identisch mit Ain Hawarah, 75 km südöstlich von Suez."] },
      { number: 24, text: "Da stellte sich das Volk gegen Mose und murrte: \"Was sollen wir nun trinken?\"" },
      { number: 25, text: "Mose schrie zu Jahwe, und Jahwe zeigte ihm ein Stück Holz. Das warf Mose ins Wasser. Da wurde es zu Süßwasser.Dort legte Gott Vorschriften und Rechte für das Volk fest und stellte es auf die Probe." },
      { number: 26, text: "Er sagte: \"Wenn du auf Jahwe, deinen Gott, hörst und tust, was ihm gefällt, wenn du seinen Geboten folgst und dich an seine Vorschriften hältst, dann werde ich dir keine von den Krankheiten schicken, die ich den Ägyptern auferlegt habe. Denn ich bin Jahwe, dein Arzt.\"" },
      { number: 27, text: "Dann kamen sie nach Elim*. Dort am Wasser schlugen sie ihr Lager auf. In Elim gab es nämlich zwölf Quellen und siebzig Palmen.", footnotes: ["Elim lag elf Kilometer südlich von Ain Hawarah im gut bewässerten Tal von Gharandel. Die Identifikation der Orte hängt allerdings davon ab, welcher Berg mit dem Sinai identifiziert wird."] },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Von Elim aus zogen die Israeliten weiter und kamen in die Wüste Sin*, die zwischen Elim und Sinai liegt. Es war am 15. Tag im 2. Monat nach ihrem Auszug aus Ägypten.", heading: "Wachteln und Manna", footnotes: ["Die Wüste Sin lag wahrscheinlich im südwestlichen Teil der Sinaihalbinsel in dem Gebiet, das heute Debbet-er-Ramleh genannt wird."] },
      { number: 2, text: "Hier in der Wüste stellte sich die ganze Gemeinschaft der Israeliten gegen Mose und Aaron. Sie ärgerten sich:" },
      { number: 3, text: "\"Hätte Jahwe uns doch in Ägypten sterben lassen, als wir an Fleischtöpfen saßen und genug Brot zu essen hatten! Aber ihr habt uns dort herausgeführt und in diese Wüste gebracht, damit wir alle verhungern!\"" },
      { number: 4, text: "Da sagte Jahwe zu Mose: \"Pass auf! Ich werde euch Brot vom Himmel regnen lassen. Dann sollen die Leute aus dem Lager hinausgehen und so viel sammeln, wie sie für einen Tag brauchen, aber nicht mehr. Ich will das Volk prüfen, ob es nach meiner Weisung leben wird oder nicht." },
      { number: 5, text: "Wenn sie am sechsten Tag die eingesammelte Nahrung zubereiten, werden sie entdecken, dass es doppelt so viel ist, wie sie sonst gesammelt haben.\"" },
      { number: 6, text: "Mose und Aaron sagten zu allen Israeliten: \"Heute Abend werdet ihr erfahren, dass Jahwe es war, der euch aus Ägypten herausgeführt hat." },
      { number: 7, text: "Und morgen früh werdet ihr die Herrlichkeit Jahwes erkennen. Er hat euer Murren gehört. Denn wer sind wir schon, dass ihr gegen uns murrt!\"" },
      { number: 8, text: "Weiter sagte Mose: \"Er wird euch am Abend Fleisch zu essen geben und am Morgen Brot, dass ihr euch satt essen könnt, weil Jahwe euer Murren gehört hat. Denn wer sind wir schon? Euer Murren hat sich nicht gegen uns gerichtet, sondern gegen Jahwe.\"" },
      { number: 9, text: "Dann sagte Mose zu Aaron: \"Befiehl der ganzen Gemeinschaft Israels: 'Kommt her und stellt euch vor Jahwe auf, denn er hat euer Murren gehört!'\"" },
      { number: 10, text: "Während Aaron noch zu den Israeliten redete und alle zur Wüste hinschauten, erschien die Herrlichkeit Jahwes in der Wolke." },
      { number: 11, text: "Jahwe sagte zu Mose:" },
      { number: 12, text: "\"Ich habe das Murren der Israeliten gehört. Sag zu ihnen: 'Am späten Nachmittag werdet ihr Fleisch essen können und am Morgen Brot, bis ihr satt seid. So werdet ihr erkennen, dass ich Jahwe, euer Gott, bin.'\"" },
      { number: 13, text: "Gegen Abend kamen Wachteln und ließen sich überall im Lager nieder. Und am Morgen lag Tau rings um das Lager." },
      { number: 14, text: "Als der Tau verdunstet war, blieben auf dem Wüstenboden feine Körner zurück, die aussahen wie Reif." },
      { number: 15, text: "Als die Israeliten das sahen, sagten sie zueinander: \"Was ist das?\"* Denn sie wussten nicht, was es war. Mose sagte zu ihnen: \"Das ist das Brot, das Jahwe euch zu essen gibt.", footnotes: ["Was ist das? Hebräisch: Man hu. Damit wird bereits der Name Manna angedeutet."] },
      { number: 16, text: "Und er befiehlt euch: 'Sammelt davon, so viel ihr braucht, etwa zwei Liter* pro Kopf, je nachdem, wie viele Personen ihr im Zelt habt.'\"", footnotes: ["zwei Liter. Wörtlich: ein Gomer = 2,2 Liter."] },
      { number: 17, text: "Die Israeliten sammelten es also, der eine mehr, der andere weniger." },
      { number: 18, text: "Als sie es zu Hause abmaßen, hatte keiner, der viel gesammelt hatte, zu viel, und keiner, der wenig gesammelt hatte, zu wenig.* Jeder hatte genauso viel gesammelt, wie er brauchte.", footnotes: ["Wird im Neuen Testament von Paulus zitiert: 2. Korinther 8,15"] },
      { number: 19, text: "Mose sagte zu ihnen: \"Niemand darf bis morgen etwas davon übrig lassen!\"" },
      { number: 20, text: "Einige hörten nicht auf ihn und legten etwas für den nächsten Tag zurück. Aber am nächsten Morgen war es voller Maden und stank. Mose war zornig über sie." },
      { number: 21, text: "Morgen für Morgen sammelte nun jeder so viel er brauchte. Wenn es heiß wurde, zerschmolz das, was draußen lag." },
      { number: 22, text: "Am sechsten Tag hatten sie doppelt so viel Brot gesammelt, etwa vier Liter pro Person. Die Vertreter der Gemeinschaft kamen zu Mose und berichteten es ihm." },
      { number: 23, text: "Er erwiderte: \"Damit ist genau eingetroffen, was Jahwe gesagt hat. Morgen ist ein Ruhetag, ein Sabbat, der Jahwe geweiht ist. Backt, was ihr backen wollt, und kocht, was ihr kochen wollt, und bewahrt den Rest für morgen auf.\"" },
      { number: 24, text: "Sie bewahrten es also bis zum nächsten Morgen auf, wie Mose es angeordnet hatte. Tatsächlich fing es nicht an zu stinken, und es waren auch keine Maden darin." },
      { number: 25, text: "Mose sagte: \"Esst das heute! Heute ist ein Sabbat für Jahwe. Heute werdet ihr draußen nichts finden." },
      { number: 26, text: "Sechs Tage sollt ihr es sammeln, aber am siebten Tag ist Sabbat; da gibt es nichts.\"" },
      { number: 27, text: "Trotzdem gingen am siebten Tag einige Leute vom Volk hinaus und wollten sammeln. Aber sie fanden nichts." },
      { number: 28, text: "Da sagte Jahwe zu Mose: \"Wie lange wollt ihr euch noch weigern, meine Gebote und Anordnungen zu befolgen?" },
      { number: 29, text: "Ihr seht, Jahwe hat euch den Sabbat gegeben. Deshalb gibt er euch am sechsten Tag Brot für zwei Tage. Jeder bleibe also am siebten Tag zu Hause und gehe nicht hinaus!\"" },
      { number: 30, text: "Da hielt das Volk den siebten Tag als Ruhetag ein." },
      { number: 31, text: "Die Israeliten nannten es Manna*. Es war weiß wie Koriandersamen* und schmeckte wie Honigkuchen.", heading: "Eine Probe Manna zur Erinnerung", footnotes: ["Manna. Siehe Vers 15!", "Koriander. Die Übersetzung des hebräischen Wortes gad mit Koriander, dessen 2-3 Millimeter große Samenkörner braun sind, ist nicht sicher."] },
      { number: 32, text: "Mose sagte: \"Jahwe hat befohlen, einen Gomer* voll Manna für eure Nachkommen aufzubewahren. Sie sollen das Brot sehen, das er euch in der Wüste zu essen gab, nachdem er euch aus Ägypten herausgeführt hatte.\"", footnotes: ["Gomer. Siehe Verse 16 und 36!"] },
      { number: 33, text: "Dann sagte er zu Aaron: \"Nimm ein Gefäß und füll es mit einem Gomer Manna. Dann stell es vor Jahwe, damit es für künftige Generationen aufbewahrt wird.\"" },
      { number: 34, text: "Aaron tat es und stellte es zur Aufbewahrung vor die Bundeslade*.", footnotes: ["Bundeslade. Wörtlich: Zeugnis. Die Anweisung ab Vers 32 bezieht sich offenbar auf die Zeit nach dem Bau des heiligen Zeltes."] },
      { number: 35, text: "Vierzig Jahre lang aßen die Israeliten das Manna, bis sie an der Grenze des Landes Kanaan in bewohntes Land kamen.*", footnotes: ["Siehe Josua 5,12!"] },
      { number: 36, text: "Ein Gomer ist der zehnte Teil eines Efa*.", footnotes: ["Efa ist ein Hohlmaß von 22 Litern."] },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Nach dem Befehl Jahwes brach die Gemeinschaft der Israeliten das Lager in der Wüste Sin ab. Sie zogen weiter, von einem Lagerplatz zum anderen. Als sie ihr Lager in Refidim* aufschlugen, fanden sie kein Trinkwasser.", heading: "Wasser aus dem Felsen", footnotes: ["Refidim. Vielleicht das Wadi Refajid oder Wadi Feiran im Süden der Sinai-Halbinsel. Die Lage des Ortes hängt davon ab, wo der biblische Berg Sinai liegt."] },
      { number: 2, text: "Da machten sie Mose schwere Vorwürfe und forderten: \"Gib uns Wasser zum Trinken!\" Mose erwiderte: \"Was streitet ihr mit mir? Warum stellt ihr Jahwe auf die Probe?\"" },
      { number: 3, text: "Aber die Israeliten quälte der Durst. So murrten sie gegen Mose und sagten: \"Wozu hast du uns überhaupt aus Ägypten herausgeführt? Willst du uns und unsere Kinder und unser Vieh vor Durst umkommen lassen?\"" },
      { number: 4, text: "Da schrie Mose zu Jahwe: \"Was soll ich nur mit diesem Volk machen? Es fehlt nicht viel, dann steinigen sie mich!\"" },
      { number: 5, text: "Jahwe antwortete ihm: \"Ruf einige von den Ältesten Israels und geh mit ihnen dem Volk voran. Nimm den Stab in die Hand, mit dem du auf das Nilwasser geschlagen hast." },
      { number: 6, text: "Dort drüben, auf dem Felsen am Horeb* werde ich vor dir stehen. Dann sollst du an den Felsen schlagen. Es wird Wasser herauskommen, und das Volk kann trinken.\" Mose machte es so, und zwar vor den Augen der Ältesten Israels.", footnotes: ["Horeb. Siehe Fußnote zu 2. Mose 3,1!"] },
      { number: 7, text: "Dann nannte er den Ort Massa und Meriba, Versuchung und Vorwurf. Denn dort hatten die Israeliten Mose Vorwürfe gemacht und Jahwe auf die Probe gestellt. Sie hatten nämlich gesagt: \"Ist Jahwe nun unter uns oder nicht?\"" },
      { number: 8, text: "Bei Refidim geschah es auch, dass die Amalekiter* anrückten, um gegen Israel zu kämpfen.", heading: "Abwehr der Amalekiter", footnotes: ["Die Amalekiter lebten als Nomaden im Negev, südlich von Beerscheba."] },
      { number: 9, text: "Mose sagte zu Josua*: \"Wähl uns Männer aus und zieh in den Kampf gegen die Amalekiter! Ich selbst werde morgen oben auf dem Hügel stehen und den Stab Gottes in der Hand halten.\"", footnotes: ["Josua bedeutet: Jahwe ist Rettung (griechisch: Jesus). Er war Moses Diener und späterer Nachfolger."] },
      { number: 10, text: "Josua tat, was Mose ihm aufgetragen hatte, und zog in den Kampf gegen die Amalekiter. Mose, Aaron und Hur* stiegen auf die Spitze des Hügels.", footnotes: ["Hur Ben-Kaleb war der Großvater von Bezaleel, einem der Erbauer der Stiftshütte (siehe 2. Mose 31,2-11)."] },
      { number: 11, text: "Solange Mose seine Hand erhob, hatte Israel die Oberhand. Wenn er seine Hand sinken ließ, waren die Amalekiter überlegen." },
      { number: 12, text: "Als Mose die Hände immer schwerer wurden, brachten Aaron und Hur einen Stein herbei, auf dem Mose sitzen konnte. Sie selbst standen rechts und links neben ihm und stützten seine Arme. So blieben seine Hände erhoben, bis die Sonne unterging." },
      { number: 13, text: "Auf diese Weise konnte Josua das Heer der Amalekiter mit dem Schwert besiegen." },
      { number: 14, text: "Danach sagte Jahwe zu Mose: \"Schreib es in ein Buch, damit es nicht in Vergessenheit gerät, und präge es Josua ein: 'Ich werde das Andenken an Amalek in der ganzen Welt vollständig auslöschen.'\"" },
      { number: 15, text: "Mose baute einen Altar und nannte ihn: \"Mein Feldzeichen ist Jahwe!\"" },
      { number: 16, text: "Er rief: \"Hand zum Thron Jahwes!* Krieg Jahwes gegen Amalek in jeder Generation!\"", footnotes: ["Hand zum Thron. Die Bedeutung der Wendung ist unbekannt. Es handelt sich vielleicht um eine Schwurformel: \"Erhebt die Hand zum Thron Jahwes!\""] },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Jitro, der Priester von Midian und Schwiegervater Moses, erfuhr, was Gott alles für Mose und für sein Volk Israel getan und dass er sie aus Ägypten herausgeführt hatte.", heading: "Jitros Rat: Berufung von Richtern" },
      { number: 2, text: "Da machte er sich mit Zippora, Moses Frau, auf den Weg. Mose hatte sie nämlich zu ihrem Vater zurückgeschickt." },
      { number: 3, text: "Jitro nahm auch die beiden Söhne Zipporas mit. Der eine hieß Gerschom, Gast in der Öde, weil Mose gesagt hatte: \"Ich bin Gast in einem fremden Land geworden.\"" },
      { number: 4, text: "Der andere hieß Eliëser, Gotthilf, denn Mose hatte gesagt: \"Der Gott meines Vaters hat mir geholfen, denn er hat mich vom Schwert des Pharao gerettet.\"" },
      { number: 5, text: "So kam Jitro, der Schwiegervater Moses, also mit dessen Frau und seinen Söhnen zu ihm an den Lagerplatz in der Wüste beim Gottesberg." },
      { number: 6, text: "Er ließ Mose ausrichten: \"Dein Schwiegervater Jitro kommt zusammen mit deiner Frau und deinen beiden Söhnen zu dir.\"" },
      { number: 7, text: "Da ging Mose seinem Schwiegervater entgegen, verneigte sich und küsste ihn. Sie fragten einander nach dem Wohlergehen und gingen ins Zelt." },
      { number: 8, text: "Mose erzählte seinem Schwiegervater alles, was Jahwe am Pharao und den Ägyptern getan hatte, um Israel zu befreien. Er erzählte von den vielen Schwierigkeiten unterwegs, und wie Jahwe ihnen herausgeholfen hatte." },
      { number: 9, text: "Da freute sich Jitro, dass Jahwe so viel Gutes an den Israeliten getan und sie aus der Gewalt der Ägypter gerettet hatte." },
      { number: 10, text: "Er sagte: \"Jahwe sei gepriesen, der euch aus der Gewalt des Pharao und der Ägypter und von ihrer Unterdrückung befreit hat." },
      { number: 11, text: "Jetzt weiß ich, dass Jahwe größer ist als alle Götter, denn das hat sich gerade an der Vermessenheit der Ägypter gezeigt.\"" },
      { number: 12, text: "Dann opferte er Gott ein Brand- und ein Schlachtopfer. Aaron und alle Ältesten Israels nahmen an dem Opfermahl in der Gegenwart Gottes teil." },
      { number: 13, text: "Am nächsten Tag setzte sich Mose hin, um Recht zu sprechen. Die Leute standen vom Morgen bis zum Abend vor ihm." },
      { number: 14, text: "Als Moses Schwiegervater das alles sah, fragte er ihn: \"Was machst du da mit dem Volk? Warum sitzt du allein hier, und die Leute stehen vom Morgen bis zum Abend um dich herum?\"" },
      { number: 15, text: "Mose erwiderte: \"Die Leute kommen zu mir, um Gott zu befragen." },
      { number: 16, text: "Auch wenn sie einen Streitfall haben, kommen sie zu mir. Ich entscheide ihren Fall und mache sie mit den Vorschriften und Weisungen Gottes bekannt.\"" },
      { number: 17, text: "Da sagte sein Schwiegervater: \"Das machst du nicht besonders gut." },
      { number: 18, text: "Es ist viel zu viel für dich und auch für die Leute, die vor dir stehen. Die Aufgabe ist zu schwer, du kannst sie nicht allein bewältigen!" },
      { number: 19, text: "Hör auf meinen Rat, und Gott möge mit dir sein: Du solltest das Volk vor Gott vertreten und ihre Anliegen vor ihn bringen." },
      { number: 20, text: "Erkläre ihnen die Vorschriften und Weisungen Gottes und zeig ihnen, was sie tun und lassen sollen." },
      { number: 21, text: "Sieh dich aber im ganzen Volk nach tüchtigen und zuverlässigen Männern um. Sie müssen Gott fürchten, die Wahrheit lieben und Bestechung hassen. Setze sie als Verantwortliche für je tausend, hundert, fünfzig oder zehn ein." },
      { number: 22, text: "Sie sollen die alltäglichen Streitigkeiten schlichten und nur mit den schwierigeren Fällen zu dir kommen. Mach dir die Last leichter und lass sie mittragen." },
      { number: 23, text: "Wenn du das tust, sofern Gott es dir befiehlt, wirst du bei Kräften bleiben, und dieses Volk wird seinen Bestimmungsort sicher erreichen.\"" },
      { number: 24, text: "Mose nahm den Rat seines Schwiegervaters an und handelte danach." },
      { number: 25, text: "Er wählte zuverlässige Männer aus ganz Israel aus und setzte sie als Verantwortliche für je tausend, hundert, fünfzig und zehn ein." },
      { number: 26, text: "Von nun an konnten sie jederzeit Recht sprechen und regelten die einfachen Streitfälle selbst. Nur mit den schwierigen Fällen kamen sie zu Mose." },
      { number: 27, text: "Dann ließ Mose seinen Schwiegervater ziehen, und der kehrte heim in sein Land." },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Genau am dritten Neumondstag nach ihrem Auszug aus Ägypten erreichten die Israeliten die Wüste Sinai.", heading: "19-40: Der Gottesdienst am Sinai\nGottes Bund: Das Gesetz (19-24)\nIsrael am Sinai" },
      { number: 2, text: "Sie waren von Refidim aufgebrochen und schlugen nun ihr Lager in der Wüste dem Berg gegenüber auf." },
      { number: 3, text: "Mose stieg hinauf, um Gott zu begegnen. Da rief ihm Jahwe vom Berg aus zu: \"Sage es den Nachkommen Jakobs, rede zu den Israeliten:" },
      { number: 4, text: "'Ihr habt gesehen, was ich mit den Ägyptern gemacht habe. Ihr habt erlebt, dass ich euch wie auf Adlersflügeln getragen und bis hierher zu mir gebracht habe." },
      { number: 5, text: "Wenn ihr nun auf mich hört und meinen Bund haltet, dann sollt ihr unter allen Völkern mein persönliches Eigentum sein. Denn mir gehört die ganze Erde." },
      { number: 6, text: "Ihr sollt mir ein Königreich von Priestern sein, ein heiliges Volk!'* Das sollst du den Israeliten sagen!\"", footnotes: ["Wird im Neuen Testament von Petrus zitiert: 1. Petrus 2,9"] },
      { number: 7, text: "Da ging Mose zurück und rief die Ältesten des Volkes zusammen. Er legte ihnen vor, was Jahwe ihm aufgetragen hatte." },
      { number: 8, text: "Das ganze Volk war sich einig: \"Wir wollen alles tun, was Jahwe gesagt hat!\" Mose ging, um Jahwe die Antwort des Volkes zu überbringen." },
      { number: 9, text: "Jahwe sagte zu ihm: \"Pass auf! Ich werde in einer dichten Wolke zu dir kommen, damit das Volk es hören kann, wenn ich mit dir rede, und damit sie dir immer glauben.\" Nun teilte Mose Jahwe die Antwort des Volkes mit." },
      { number: 10, text: "Dann sagte Jahwe zu Mose: \"Geh zum Volk und sorge dafür, dass sie sich heute und morgen auf die Begegnung mit mir vorbereiten!* Sie sollen ihre Gewänder waschen,", footnotes: ["auf ... vorbereiten. Wörtlich: Heilige das Volk! So auch Vers 14."] },
      { number: 11, text: "damit sie für den dritten Tag bereit sind. Denn am dritten Tag wird Jahwe vor den Augen des ganzen Volkes auf den Berg Sinai herabsteigen." },
      { number: 12, text: "Du musst das Volk ringsum abgrenzen und ihnen einschärfen: 'Nehmt euch in Acht! Steigt nicht auf den Berg, kommt nicht einmal an seinen Fuß!' Jeder, der den Berg antastet, muss getötet werden." },
      { number: 13, text: "Keine Hand darf ihn berühren! Und wer es dennoch tut, darf nicht am Leben bleiben! Er muss mit Steinen erschlagen oder mit Pfeilen erschossen werden, ganz egal, ob Mensch oder Tier.* Erst wenn das Widderhorn* anhaltend dröhnt, dürfen sie auf den Berg steigen.\"", footnotes: ["Wird im Neuen Testament vom Hebräerbrief zitiert: Hebräer 12,20", "Das Widderhorn Hebräisch: Jobel. Signalhorn, das aus den gewundenen Hörnern von Schafböcken hergestellt wurde."] },
      { number: 14, text: "Mose stieg wieder zum Volk hinunter und ordnete an, dass die Leute ihre Gewänder wuschen und sich darauf vorbereiteten, Gott zu begegnen." },
      { number: 15, text: "Er sagte zu ihnen: \"Haltet euch für den dritten Tag bereit! Bis dahin darf niemand mit seiner Frau schlafen!\"" },
      { number: 16, text: "Im Morgengrauen des dritten Tages begann es zu donnern und zu blitzen. Eine schwere Wolke lag auf dem Berg, und das überlaute Dröhnen des Schofar* war zu hören. Das Volk im Lager zitterte vor Angst.", footnotes: ["Der Schofar wurde aus den gewundenen Hörnern des männlichen Fettschwanzschafes hergestellt und brachte einen dumpfen, durchdringenden Ton hervor."] },
      { number: 17, text: "Doch Mose führte es aus dem Lager heraus, Gott entgegen. Am Fuß des Berges stellten sie sich auf." },
      { number: 18, text: "Der ganze Berg Sinai war in dichten Rauch gehüllt, weil Jahwe im Feuer auf ihn herabgekommen war. Rauch stieg von ihm auf wie von einem Schmelzofen. Der ganze Berg wurde von einem gewaltigen Beben geschüttelt." },
      { number: 19, text: "Das Dröhnen des Schofar wurde immer lauter. Mose rief, und Gott antwortete ihm mit Donnerstimme." },
      { number: 20, text: "Dann stieg Jahwe ganz auf den Gipfel des Berges herab und rief Mose zu sich. Mose stieg hinauf." },
      { number: 21, text: "Jahwe sagte zu ihm: \"Geh noch einmal zurück und warne das Volk, dass sie ja nicht zu Jahwe durchbrechen, um ihn zu sehen. Sonst würden viele von ihnen den Tod finden." },
      { number: 22, text: "Auch die Priester*, die sich Jahwe nähern, müssen sich dafür weihen, sonst ist ihr Leben in Gefahr.\"", footnotes: ["Priester. Siehe auch Vers 24! Bevor es die offizielle aaronitische Priesterschaft in Israel gab (2. Mose 28,1), wurden priesterliche Funktionen von den Ältesten (2. Mose 3,18; 18,12) oder von jungen Männern wahrgenommen (2. Mose 24,5)."] },
      { number: 23, text: "Mose sagte zu Jahwe: \"Das Volk kann gar nicht auf den Berg Sinai steigen, denn du hast uns ja gewarnt und befohlen, eine Grenze um den Berg zu ziehen und ihn für heilig zu erklären.\"" },
      { number: 24, text: "Doch Jahwe sagte zu ihm: \"Geh und steig hinunter! Und komm dann mit Aaron wieder herauf! Aber die Priester und das Volk dürfen nicht durchbrechen, um zu Jahwe hinaufzusteigen, damit er keine Bresche in ihre Linie bricht.\"" },
      { number: 25, text: "Da stieg Mose hinunter und warnte das Volk." },
    ] },
    { number: 20, verses: [
      { number: 1, text: "Dann redete Gott. Er sagte:", heading: "Die zehn Gebote" },
      { number: 2, text: "\"Ich bin Jahwe, dein Gott! Ich habe dich aus dem Sklavenhaus Ägyptens befreit." },
      { number: 3, text: "Du wirst* keine anderen Götter vor mich stellen!", footnotes: ["wirst. Das heißt: \"Ich habe dich befreit, deshalb sollte es undenkbar für dich sein, das zu tun.\" Es meint aber auch ein unbedingtes Verbot."] },
      { number: 4, text: "Du wirst dir kein Götterbild machen, kein Abbild von irgendetwas im Himmel, auf der Erde oder im Meer!" },
      { number: 5, text: "Wirf dich niemals vor ihnen nieder und verehre sie auf keinen Fall! Denn ich, Jahwe, ich, dein Gott, bin ein eifersüchtiger Gott. Wer mich verachtet und beiseite stellt, bei dem verfolge ich die Schuld der Väter noch bis zur dritten und vierten Generation." },
      { number: 6, text: "Doch wer mich liebt und meine Gebote hält, dem schenke ich meine Gunst auf tausend Generationen hin." },
      { number: 7, text: "Du wirst den Namen Jahwes, deines Gottes, nie missbrauchen! Denn Jahwe wird jeden bestrafen, der seinen Namen mit Nichtigkeiten in Verbindung bringt." },
      { number: 8, text: "Denk an den Sabbattag und reserviere ihn für Gott!" },
      { number: 9, text: "Sechs Tage hast du, um all deine Arbeit zu tun," },
      { number: 10, text: "aber der siebte Tag ist Sabbat für Jahwe, deinen Gott. An diesem Tag sollst du nicht arbeiten, weder du, noch dein Sohn oder deine Tochter, weder dein Sklave noch deine Sklavin, nicht einmal dein Vieh oder der Fremde, der in deinem Ort wohnt." },
      { number: 11, text: "Denn in sechs Tagen hat Jahwe den Himmel und die Erde gemacht, das Meer und alles, was dazugehört. Am siebten Tag aber ruhte er. Deshalb hat er den Sabbattag gesegnet und für sich bestimmt." },
      { number: 12, text: "Ehre deinen Vater und deine Mutter! Dann wirst du lange in dem Land leben, das Jahwe, dein Gott, dir gibt." },
      { number: 13, text: "Morde nicht!*", footnotes: ["Wird im Neuen Testament von Jesus Christus und Jakobus zitiert: Matthäus 5,21; Jakobus 2,11"] },
      { number: 14, text: "Brich die Ehe nicht!*", footnotes: ["Wird im Neuen Testament von Jesus Christus und Jakobus zitiert: Matthäus 5,27; Jakobus 2,11"] },
      { number: 15, text: "Stiehl nicht!" },
      { number: 16, text: "Sag nichts Unwahres über deinen Mitmenschen!" },
      { number: 17, text: "Begehre nichts,* was deinem Mitmenschen gehört,* weder seine Frau noch seinen Sklaven oder seine Sklavin, sein Rind oder seinen Esel oder sonst etwas, das ihm gehört!\"", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 7,7.", "Die Verse 13-17 werden im Neuen Testament von Paulus zitiert: Römer 13,9"] },
      { number: 18, text: "Als das ganze Volk den Donner und die Flammen wahrnahm, das Dröhnen des Schofar und den rauchenden Berg, da zitterte es vor Angst. Es hielt sich in der Ferne" },
      { number: 19, text: "und sagte zu Mose: \"Rede du mit uns! Wir werden auf dich hören. Gott soll nicht mit uns reden, sonst müssen wir sterben.\"" },
      { number: 20, text: "Da sagte Mose zum Volk: \"Ihr müsst keine Angst haben. Gott ist nur gekommen, um euch auf die Probe zu stellen. Die Furcht vor ihm sollte über euch kommen, damit ihr nicht sündigt.\"" },
      { number: 21, text: "So blieb das Volk in der Ferne stehen. Mose aber näherte sich dem Dunkel, wo Gott war." },
      { number: 22, text: "Jahwe sagte zu Mose: \"Sag den Israeliten: 'Ihr habt erlebt, wie ich vom Himmel her zu euch gesprochen habe.", heading: "Das Altargesetz" },
      { number: 23, text: "Darum sollt ihr keine selbst gemachten Götter neben mich stellen, weder aus Silber noch aus Gold." },
      { number: 24, text: "Macht mir einen Altar aus Erde und bringt darauf eure Schafe und Rinder als Brand- und Freudenopfer* dar. An jedem Ort, wo ihr durch ein Opfer an mich denkt, werde ich euch nahe sein und euch segnen.", footnotes: ["Beim Freudenopfer wurde im Gegensatz zum Brandopfer nur das Fett auf dem Altar verbrannt. Der größte Teil des Tieres durfte bei einer fröhlichen Opfermahlzeit gemeinsam mit Verwandten und Freunden verzehrt werden."] },
      { number: 25, text: "Wenn ihr mir einen Altar aus Steinen bauen wollt, dürft ihr nur unbehauene Steine dafür verwenden. Wenn ihr sie mit einem Meißel bearbeiten würdet, hättet ihr den Altar entweiht." },
      { number: 26, text: "Du sollst nicht auf Stufen zu meinem Altar hinaufsteigen, damit deine Nacktheit unter dem Gewand nicht zum Vorschein kommt.'\"" },
    ] },
    { number: 21, verses: [
      { number: 1, text: "\"Folgende Rechtsordnungen sollst du ihnen vorlegen:", heading: "Das Bundesbuch (Kapitel 21-23)" },
      { number: 2, text: "'Wenn du einen hebräischen Sklaven kaufst, soll er dir sechs Jahre lang dienen. Im siebten Jahr soll er unentgeltlich als freier Mann entlassen werden.", heading: "Hebräische Sklaven" },
      { number: 3, text: "Ist er allein gekommen, soll er allein gehen. War er verheiratet, soll seine Frau mitgehen." },
      { number: 4, text: "Falls sein Herr ihm eine Frau gegeben hat, bleiben die Frau und ihre Kinder Eigentum ihres Herrn. Nur er selbst ist frei." },
      { number: 5, text: "Wenn der Sklave aber sagt: \"Ich liebe meinen Herrn, meine Frau und meine Kinder; ich will nicht freigelassen werden!\"," },
      { number: 6, text: "dann soll sein Herr ihn in der Gegenwart Gottes an die Tür oder den Türpfosten stellen und ihm das Ohr mit einer Ahle durchbohren. So wird er für immer sein Sklave sein." },
      { number: 7, text: "Wenn jemand seine Tochter als Sklavin verkauft hat, darf sie nicht so wie ein Sklave freigelassen werden." },
      { number: 8, text: "Hatte ihr Herr sie für sich selbst bestimmt, aber sie gefiel ihm nicht, dann soll er sie zurückkaufen lassen. Er hat nicht das Recht, sie an Fremde zu verkaufen, weil er seine Zusage nicht eingehalten hat." },
      { number: 9, text: "Hat er sie als Frau für seinen Sohn bestimmt, muss er ihr die Rechte einer Tochter einräumen." },
      { number: 10, text: "Heiratet er sie und später noch eine andere, dann darf er sie in Nahrung, Kleidung und sexueller Gemeinschaft nicht benachteiligen." },
      { number: 11, text: "Vernachlässigt er eine dieser drei Pflichten, muss er sie unentgeltlich freilassen.'" },
      { number: 12, text: "'Wer einen Menschen so schlägt, dass er stirbt, wird mit dem Tod bestraft.", heading: "Totschlag und Mord" },
      { number: 13, text: "Hat er ihn nicht absichtlich getötet, sondern Gott hat es durch seine Hand geschehen lassen, dann werde ich dir einen Ort bestimmen, wohin er fliehen kann." },
      { number: 14, text: "Doch wenn jemand seinen Mitmenschen vorsätzlich und hinterhältig umbringt, findet er nicht einmal an meinem Altar Schutz. Er muss von dort weggeholt und getötet werden.'" },
      { number: 15, text: "'Wer seinen Vater oder seine Mutter schlägt, wird mit dem Tod bestraft.'", heading: "Misshandlung der Eltern" },
      { number: 16, text: "'Wer einen Menschen raubt, wird mit dem Tod bestraft, gleichgültig, ob er ihn schon verkauft oder noch in seiner Gewalt hat.'", heading: "Menschenraub" },
      { number: 17, text: "'Wer seinen Vater oder seine Mutter verflucht, wird mit dem Tod bestraft.'*", heading: "Verfluchung der Eltern", footnotes: ["Wird im Neuen Testament von Jesus Christus zitiert: Matthäus 15,4; Markus 7,10"] },
      { number: 18, text: "'Wenn Männer in Streit geraten und einer verletzt den anderen mit einem Stein oder der Faust, sodass er bettlägerig wird,", heading: "Körperverletzung" },
      { number: 19, text: "aber später wieder aufstehen und draußen am Stock umherlaufen kann, ist der Täter nicht körperlich zu bestrafen. Er muss den Verletzten aber für seine Arbeitsunfähigkeit entschädigen und ihm die Heilungskosten erstatten." },
      { number: 20, text: "Wenn jemand seinen Sklaven mit einem Stock so schlägt, dass er ihm unter der Hand stirbt, dann muss das bestraft werden. Dasselbe gilt bei einer Sklavin." },
      { number: 21, text: "Wenn der Sklave aber noch einen oder zwei Tage am Leben bleibt, muss die Tat nicht bestraft werden, denn er schadet sich ja selbst.*", footnotes: ["schadet sich selbst. Wörtlich: es ist sein eigenes Geld. Wenn der Sklave stirbt, hat der Herr eine Arbeitskraft verloren."] },
      { number: 22, text: "Wenn Männer sich prügeln und dabei eine schwangere Frau stoßen, sodass sie eine Frühgeburt hat, aber sonst kein ernstlicher Schaden entstanden ist, dann muss der Schuldige eine Geldstrafe bezahlen. Die Höhe wird vom Ehemann der betreffenden Frau bestimmt und nach gerichtlicher Bestätigung bezahlt." },
      { number: 23, text: "Ist aber ein weiterer Schaden entstanden, dann muss gegeben werden: Leben für Leben," },
      { number: 24, text: "Auge für Auge, Zahn für Zahn,* Hand für Hand, Fuß für Fuß,", footnotes: ["Wird im Neuen Testament von Jesus Christus in der Bergpredigt zitiert: Matthäus 5,38"] },
      { number: 25, text: "Brandmal für Brandmal, Wunde für Wunde, Strieme für Strieme." },
      { number: 26, text: "Wenn jemand seinem Sklaven ein Auge oder einen Zahn ausschlägt, muss er ihn als Entschädigung dafür freilassen." },
      { number: 27, text: "Dasselbe gilt bei einer Sklavin.'" },
      { number: 28, text: "'Wenn ein Rind einen Mann oder eine Frau stößt, so dass sie sterben, muss das Rind mit schweren Steinen erschlagen werden. Sein Fleisch darf man nicht essen. Der Besitzer jedoch bleibt straffrei.", heading: "Körperverletzung durch Haustiere" },
      { number: 29, text: "Hat das Rind aber schon früher Menschen gestoßen und sein Besitzer hat es nicht eingesperrt, obwohl man ihn gewarnt hatte, dann muss nicht nur das Rind gesteinigt, sondern auch sein Besitzer getötet werden." },
      { number: 30, text: "Wenn ihm die Zahlung eines Sühngeldes erlaubt wird, dann muss er als Lösegeld für sein Leben alles bezahlen, was man ihm auferlegt." },
      { number: 31, text: "Der gleiche Grundsatz gilt auch, wenn das Rind einen Jungen oder ein Mädchen tödlich verletzt." },
      { number: 32, text: "Bei einem Sklaven oder einer Sklavin muss der Besitzer des Rindes ihrem Herrn dreißig Silberstücke* zahlen, und das Rind muss gesteinigt werden.'", footnotes: ["Silberstücke. Wörtlich: Schekel. Nach archäologischen Funden kann das Durchschnittsgewicht eines Schekel mit 11,5 Gramm angenommen werden."] },
      { number: 33, text: "'Wenn jemand eine Zisterne offen lässt oder eine gräbt und nicht abdeckt, und ein Rind oder ein Esel fällt hinein,", heading: "Schadenersatz bei fremdem Vieh" },
      { number: 34, text: "dann muss er das Tier seinem Besitzer bezahlen. Das tote Tier kann er behalten." },
      { number: 35, text: "Wenn jemandes Rind das Rind eines anderen stößt, sodass es verendet, dann sollen beide Besitzer das lebende Tier verkaufen und den Erlös teilen. Auch das tote Tier sollen sie sich teilen." },
      { number: 36, text: "Hat das Rind aber schon früher gestoßen und sein Besitzer hat es nicht eingesperrt, muss er ein lebendes Rind für das tote erstatten. Das tote darf er behalten.'" },
      { number: 37, text: "'Wenn jemand ein Rind oder ein Stück Kleinvieh stiehlt und es schlachtet oder verkauft, dann muss er für das Rind fünffachen Ersatz leisten und für das Schaf oder die Ziege vierfachen.'", heading: "Schadenersatz bei Diebstahl" },
    ] },
    { number: 22, verses: [
      { number: 1, text: "'Wenn der Dieb beim Einbruch ertappt und so geschlagen wird, dass er stirbt, so liegt keine Blutschuld vor." },
      { number: 2, text: "War jedoch die Sonne schon aufgegangen, zählt es als Mord. Ein Dieb jedenfalls muss vollen Ersatz leisten. Ist er dazu nicht imstande, wird er als Sklave verkauft." },
      { number: 3, text: "Findet man das Gestohlene aber noch lebend in seinem Besitz, sei es Rind, Esel, Schaf oder Ziege, dann muss er doppelten Ersatz leisten.'" },
      { number: 4, text: "'Wenn jemand ein Feld oder einen Weinberg abweiden lässt und sein Vieh dabei nicht beaufsichtigt, sodass es auch das Feld eines anderen abweidet, muss er es mit dem Besten vom Ertrag seines eigenen Feldes oder Weinbergs ersetzen.", heading: "Schadenersatz bei Ernteschädigung" },
      { number: 5, text: "Wenn jemand Feuer macht und es erfasst eine Dornenhecke und greift auf einen Garbenhaufen über oder es vernichtet stehendes Getreide, dann muss er vollen Ersatz leisten.'" },
      { number: 6, text: "'Wenn jemand einem anderen Geld oder Gegenstände zur Aufbewahrung übergibt und es wird etwas davon aus dessen Haus gestohlen, dann muss der Dieb den doppelten Wert erstatten, falls er gefunden wird.", heading: "Haftung für fremdes Eigentum" },
      { number: 7, text: "Kann der Dieb nicht ermittelt werden, muss der Hausbesitzer vor Gott erscheinen, damit festgestellt wird, ob er das Eigentum seines Nächsten unterschlagen hat." },
      { number: 8, text: "Bei jedem Fall von Veruntreuung, ganz gleich, ob es sich um ein Rind, einen Esel, ein Schaf, eine Ziege oder ein Kleidungsstück handelt, von dem jeder Beteiligte behauptet, es sei sein Eigentum, muss die Sache vor Gott entschieden werden. Wen Gott für schuldig erklärt, der muss seinem Nächsten das Doppelte erstatten." },
      { number: 9, text: "Wenn jemand einem anderen einen Esel, ein Rind, ein Schaf oder ein anderes Tier in Verwahrung gibt und es stirbt oder bricht sich etwas oder es wird von Feinden weggetrieben, ohne dass es jemand gesehen hat," },
      { number: 10, text: "dann soll der, dem es anvertraut wurde, vor Jahwe einen Eid schwören, dass er sich nicht an dem fremden Eigentum vergriffen hat. Der Besitzer muss das gelten lassen und darf keinen Ersatz fordern." },
      { number: 11, text: "Ist es jedoch nachweislich gestohlen worden, muss er es dem Besitzer voll erstatten." },
      { number: 12, text: "Ist es von wilden Tieren gerissen worden und kann er es als Beweis herbeibringen, muss er es nicht erstatten." },
      { number: 13, text: "Wenn jemand sich von einem anderen ein Stück Vieh leiht und es bricht sich etwas oder stirbt, muss er es erstatten, wenn sein Besitzer nicht dabei war." },
      { number: 14, text: "War der Besitzer dabei, muss er es nicht erstatten. Und wenn es gemietet war, ist es durch den Mietpreis abgegolten.'" },
      { number: 15, text: "'Wenn jemand eine noch nicht verlobte junge Frau verführt und mit ihr schläft, muss er den Brautpreis bezahlen und sie heiraten.", heading: "Verführung eines Mädchens" },
      { number: 16, text: "Falls sich ihr Vater weigert, sie ihm zu geben, muss er ihm dennoch den üblichen Brautpreis für ein unberührtes Mädchen bezahlen.'" },
      { number: 17, text: "'Eine Zauberin* darfst du nicht am Leben lassen!", heading: "Todeswürdige Verbrechen", footnotes: ["Zauberin. Eine Frau, die okkulte und magische Praktiken betreibt."] },
      { number: 18, text: "Jeder, der mit einem Tier Geschlechtsverkehr hat, muss getötet werden." },
      { number: 19, text: "Wer einer Gottheit Opfer bringt, außer Jahwe, soll dem Bann verfallen*.'", footnotes: ["dem Bann verfallen. Das heißt, er muss mit seinem ganzen Besitz vernichtet werden."] },
      { number: 20, text: "'Einen Fremden darfst du weder ausbeuten noch unterdrücken. Ihr seid ja selbst Fremde im Land Ägypten gewesen.", heading: "Schutz der Schwachen" },
      { number: 21, text: "Keine Witwe oder Waise dürft ihr benachteiligen." },
      { number: 22, text: "Wenn du sie dennoch in irgendeiner Weise bedrückst, und sie zu mir um Hilfe schreien, werde ich bestimmt auf sie hören." },
      { number: 23, text: "Dann wird mein Zorn auflodern, und ich werde euch durch das Schwert umkommen lassen. Eure Frauen werden dann zu Witwen werden und eure Kinder zu Waisen." },
      { number: 24, text: "Wenn du einem Armen aus meinem Volk Geld leihst, dann verhalte dich nicht wie ein Wucherer. Verlange keine Zinsen von ihm!" },
      { number: 25, text: "Falls du wirklich den Mantel eines anderen zum Pfand nimmst, dann gib ihn noch vor Sonnenuntergang zurück," },
      { number: 26, text: "denn das ist seine einzige Decke für die Nacht. Womit soll er sich sonst zudecken? Wenn er dann zu mir um Hilfe schreit, werde ich ganz bestimmt auf ihn hören, denn ich bin gnädig.'" },
      { number: 27, text: "'Gott sollst du nicht lästern und einen Fürsten in deinem Volk nicht verfluchen.*", heading: "Pflichten gegen Gott", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Apostelgeschichte 23,5"] },
      { number: 28, text: "Hinterzieht nicht den Ertrag eurer Felder und Weinberge! Eure erstgeborenen Söhne sollt ihr mir übereignen." },
      { number: 29, text: "Ebenso sollt ihr es mit euren Rindern und dem Kleinvieh machen. Sieben Tage soll das erstgeborene Jungtier bei seiner Mutter bleiben, am achten Tag sollst du es mir übereignen." },
      { number: 30, text: "Ihr seid Menschen, die mir geweiht sind. Deshalb dürft ihr kein Fleisch essen, das von Raubtieren gerissen wurde. Das kannst du deinen Hunden hinwerfen.'" },
    ] },
    { number: 23, verses: [
      { number: 1, text: "'Verbreite kein falsches Gerücht! Lass dich nicht von einem Schuldigen zur Falschaussage verleiten!", heading: "Gerechtigkeit und Nächstenliebe" },
      { number: 2, text: "Schließ dich nicht der Mehrheit an, wenn sie im Unrecht ist! Und wenn du vor Gericht aussagen musst, richte dich nicht nach der Mehrheit, wenn sie das Recht verdreht." },
      { number: 3, text: "Aber auch einen Armen darfst du vor Gericht nicht begünstigen." },
      { number: 4, text: "Wenn du einem verirrten Rind oder Esel deines Feindes begegnest, dann bringe ihm das Tier ohne Zögern zurück." },
      { number: 5, text: "Wenn der Esel deines Feindes unter seiner Last zusammengebrochen ist, dann geh nicht einfach vorbei, sondern hilf ihm, das Tier wieder auf die Beine zu bringen." },
      { number: 6, text: "Du darfst das Recht eines Armen vor Gericht nicht beugen!" },
      { number: 7, text: "Halte dich von einer Lügensache fern! Hilf nie dabei, einen, der unschuldig und gerecht ist, umzubringen! Denn ich gebe dem Schuldigen nicht Recht." },
      { number: 8, text: "Nimm keine Bestechung an, denn das trübt das Urteilsvermögen und verdreht das Recht." },
      { number: 9, text: "Unterdrücke die Fremden nicht! Ihr wisst doch, wie einem Fremden zumute ist, denn auch ihr seid Fremde in Ägypten gewesen.'" },
      { number: 10, text: "'Sechs Jahre sollst du dein Land bearbeiten und seinen Ertrag ernten.", heading: "Sabbatjahr und Feiertage" },
      { number: 11, text: "Doch im siebten Jahr sollst du es brachliegen lassen, damit die Armen deines Volkes davon essen können. Den Rest überlass dem Wild! Ebenso sollst du es mit deinen Weinbergen und Ölbäumen halten." },
      { number: 12, text: "Sechs Tage sollst du deine Arbeit tun, aber am siebten Tag sollst du alles ruhen lassen! Auch dein Rind und dein Esel sollen sich ausruhen. Auch der Sohn deiner Sklavin und der Fremde sollen aufatmen können." },
      { number: 13, text: "Haltet euch an alles, was ich euch gesagt habe! Den Namen einer anderen Gottheit dürft ihr nicht erwähnen, er soll nicht über eure Lippen kommen!" },
      { number: 14, text: "Dreimal im Jahr sollst du mir ein Fest feiern," },
      { number: 15, text: "als erstes das Fest der ungesäuerten Brote. Dabei sollst du zur festgesetzten Zeit sieben Tage lang ungesäuerte Brotfladen essen, wie ich es dir befohlen habe. Das soll im Ährenmonat geschehen, dem Monat deines Auszugs aus Ägypten. Keiner soll mit leeren Händen vor mir erscheinen." },
      { number: 16, text: "Dann kommt das Erntefest, wenn du das erste Getreide einbringst, das du ausgesät hast, und schließlich das Wein- und Obstlesefest im Herbst, wenn ihr die Früchte von den Weinbergen und Obstplantagen geerntet habt." },
      { number: 17, text: "Dreimal im Jahr soll alles, was männlich ist, vor dem Herrn, vor Jahwe, erscheinen." },
      { number: 18, text: "Das Blut eines Schlachtopfers darfst du nicht zusammen mit gesäuerten Brotfladen vor mich bringen. Und das Fett eines Opfertiers darf nicht bis zum nächsten Morgen aufgehoben werden." },
      { number: 19, text: "Die Besten von deinen ersten Feldfrüchten sollst du in das Haus Jahwes, deines Gottes, bringen. Ein Böckchen darfst du nicht in der Milch seiner Mutter kochen.'" },
      { number: 20, text: "'Pass auf! Ich werde einen Engel vor dir her schicken, der dich unterwegs behütet und dich an den Ort bringt, den ich für dich bestimmt habe.", heading: "Schlussmahnungen" },
      { number: 21, text: "Hüte dich vor ihm und hör auf das, was er sagt! Lehn dich nicht gegen ihn auf! Er würde euch das nicht vergeben, denn mein Name ist in ihm." },
      { number: 22, text: "Doch wenn du ihm aufs Wort gehorchst, wenn du alles tust, was ich durch ihn sage, dann werde ich deine Feinde befeinden und deine Bedränger bedrängen." },
      { number: 23, text: "Mein Engel geht vor dir her und bringt dich zu den Amoritern, Hetitern, Perisitern, Kanaanitern, Hiwitern und Jebusitern, die ich alle beseitigen werde." },
      { number: 24, text: "Folge nicht dem Beispiel dieser Völker! Wirf dich nicht vor ihren Göttern nieder und diene ihnen nicht! Stürze ihre Götterbilder um und zerschlage ihre Steinmale!" },
      { number: 25, text: "Dient Jahwe, eurem Gott! Dann wird er dein Brot und Wasser segnen. Ich werde Krankheiten von dir fernhalten." },
      { number: 26, text: "Keine Frau in deinem Land wird eine Fehlgeburt haben oder kinderlos bleiben. Niemand wird vor der Zeit sterben." },
      { number: 27, text: "Angst und Schrecken schicke ich vor dir her. Alle Völker, zu denen du kommst, werden in Verwirrung geraten. Ich werde dafür sorgen, dass du nur den Rücken deiner Feinde siehst." },
      { number: 28, text: "Ich lasse Panik vor dir ausbrechen. Sie wird die Hiwiter, Kanaaniter und Hetiter vor dir her treiben." },
      { number: 29, text: "Allerdings werde ich sie nicht in einem einzigen Jahr vertreiben, sonst würde das Land verwildern und die wilden Tiere würden überhand nehmen." },
      { number: 30, text: "Ich werde sie nach und nach vertreiben, bis du dich so vermehrt hast, dass du das Land in Besitz nehmen kannst." },
      { number: 31, text: "Dein Gebiet wird vom Golf von Elat* bis zum Mittelmeer* reichen, von der Wüste bis an den Euphrat. Ich gebe die Bewohner dieses Landes in deine Gewalt, dass du sie vertreiben kannst.", footnotes: ["Golf von Elat. Wörtlich: Schilfmeer. Hier ist das Rote Meer am Golf von Akaba/Elat gemeint.", "Mittelmeer. Wörtlich: Meer der Philister."] },
      { number: 32, text: "Doch du darfst weder mit ihnen noch mit ihren Göttern einen Bund schließen." },
      { number: 33, text: "Sie dürfen nicht bei dir wohnen bleiben, denn sonst würden sie dich verführen, mir untreu zu werden und ihre Götter zu verehren. Das würde zu einer Falle für dich.'\"" },
    ] },
    { number: 24, verses: [
      { number: 1, text: "Jahwe hatte zu Mose gesagt: \"Steig zu mir herauf und nimm Aaron, Nadab, Abihu* und siebzig von den Ältesten Israels mit. Werft euch in gebührender Entfernung vor mir nieder!", heading: "Gott schließt seinen Bund mit Israel", footnotes: ["Nadab und Abihu waren die beiden ältesten Söhne Aarons."] },
      { number: 2, text: "Nur Mose darf in die Nähe Jahwes kommen, die anderen nicht. Das Volk darf überhaupt nicht auf den Berg steigen.\"" },
      { number: 3, text: "Dann trat Mose vor das Volk und gab ihm alle Worte und Bestimmungen Jahwes weiter. Das ganze Volk antwortete wie aus einem Mund: \"Wir wollen alles tun, was Jahwe uns befohlen hat.\"" },
      { number: 4, text: "Daraufhin schrieb Mose alle Worte Jahwes auf. Am nächsten Morgen errichtete er am Fuß des Berges einen Altar und stellte zwölf Gedenksteine nach der Zahl der Stämme Israels auf." },
      { number: 5, text: "Dann beauftragte er junge israelitische Männer, Jahwe Brandopfer zu bringen und junge Stiere als Freudenopfer zu schlachten." },
      { number: 6, text: "Die Hälfte des Blutes goss Mose in Schalen, die andere Hälfte sprengte er an den Altar." },
      { number: 7, text: "Anschließend nahm er die Schriftrolle mit dem Bundesgesetz in die Hand und las alles dem Volk vor. Es erwiderte: \"Alles, was Jahwe gesagt hat, wollen wir gehorsam tun.\"" },
      { number: 8, text: "Darauf nahm Mose die Schalen mit dem Blut und sprengte es über das Volk. Dabei rief er: \"Seht, das ist das Blut des Bundes, den Jahwe aufgrund dieser Gebote mit euch geschlossen hat!\"*", footnotes: ["Wird im Neuen Testament im Hebräerbrief zitiert: Hebräer 9,20."] },
      { number: 9, text: "Danach stiegen Mose und Aaron, Nadab, Abihu und siebzig von den Ältesten Israels den Berg hinauf." },
      { number: 10, text: "Da sahen sie den Gott Israels. Der Boden unter seinen Füßen sah aus, als ob er mit Saphirplatten belegt wäre, klar und leuchtend wie der Himmel." },
      { number: 11, text: "Gott griff diese ausgewählten Männer Israels nicht an, sondern sie durften ihn sehen* und aßen und tranken in seiner Gegenwart.", footnotes: ["ihn sehen. Nach Vers 10 sahen sie nur den Fußboden, auf dem sein Thron stand. Gott selbst verhüllt sich in strahlendem Licht, denn Gottes Gesicht zu sehen ist für jeden Menschen tödlich (2. Mose 33,20-23)."] },
      { number: 12, text: "Jahwe sagte zu Mose: \"Steig nun zu mir auf den Berg herauf und bleib dort, damit ich dir die Steintafeln geben kann, auf die ich das Gesetz und die Gebote für die Unterweisung Israels geschrieben habe.\"" },
      { number: 13, text: "Da machte sich Mose mit seinem Diener Josua bereit, auf den Gottesberg zu steigen." },
      { number: 14, text: "Zu den Ältesten sagte er: \"Wartet hier auf uns, bis wir zurück sind. Ihr seht ja, dass Aaron und Hur bei euch sind. Wenn jemand einen Streitfall hat, soll er sich an sie wenden.\"" },
      { number: 15, text: "Als Mose auf den Berg stieg, war dieser von der Wolke verhüllt." },
      { number: 16, text: "Die Herrlichkeit Jahwes ließ sich auf den Berg Sinai herab. Sechs Tage lang bedeckte die Wolke den Berg. Dann, am siebten Tag, rief Gott Mose aus der Wolke heraus zu sich." },
      { number: 17, text: "Für die Israeliten sah die Herrlichkeit Jahwes wie ein rasendes Feuer aus, das auf dem Gipfel loderte." },
      { number: 18, text: "Jetzt ging Mose in die Wolke hinein und stieg auf den Berg. 40 Tage und 40 Nächte blieb er dort." },
    ] },
    { number: 25, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Gottes Plan: Das Heiligtum (25-31)\nDie Gaben" },
      { number: 2, text: "\"Sag den Israeliten, dass sie mir freiwillige Gaben bringen. Von jedem, der es gern gibt, sollt ihr diese Opfergabe annehmen." },
      { number: 3, text: "Sie kann aus Gold, Silber oder Bronze bestehen." },
      { number: 4, text: "Es kann blauer oder roter Purpur sein, Karmesinstoff, Leinen oder Ziegenhaar." },
      { number: 5, text: "Lasst rot gefärbte Felle von Schafböcken bringen, Tachasch-Häute* und Akazienholz,", footnotes: ["Tachasch-Häute. Weichgegerbtes Leder aus Tümmler- oder Dachshäuten."] },
      { number: 6, text: "Öl für den Leuchter, wohlriechende Zutaten für das Salböl und die Weihrauchmischung," },
      { number: 7, text: "dazu Edelsteine und Onyx zum Schmuck für das Efod* und die Brusttasche.", footnotes: ["Efod. Ein sehr kostbares ärmelloses Gewand, das der Hohe Priester über dem Obergewand trug (2. Mose 39). Am Efod waren die mit Edelsteinen besetzten Schulterstücke und das Brustschild befestigt."] },
      { number: 8, text: "Sie sollen mir ein Heiligtum bauen, weil ich unter ihnen wohnen will." },
      { number: 9, text: "Ich habe dir das Modell dieser Wohnung samt ihren Einrichtungsgegenständen gezeigt. Dementsprechend sollt ihr sie bauen.\"" },
      { number: 10, text: "\"Sie sollen eine Lade aus Akazienholz machen: eineinviertel Meter* lang, dreiviertel Meter breit und ebenso hoch.", heading: "Die Bundeslade", footnotes: ["Meter. Meter. Wörtlich: zweieinhalb Ellen. Weil die für eine Elle angegebenen Maße zwischen 44,42 und 52,45 cm schwanken, gehen wir für die meisten Umrechnungen von 50 cm aus. Dadurch werden auch die Proportionen deutlicher."] },
      { number: 11, text: "Innen und außen soll sie mit reinem Gold überzogen sein und oben mit einer Goldleiste verziert." },
      { number: 12, text: "Lass vier Ringe aus Gold gießen und so an den vier Ecken anbringen, dass an jeder Längsseite zwei Ringe sind." },
      { number: 13, text: "Lass dann Stangen aus Akazienholz anfertigen und mit Gold überziehen." },
      { number: 14, text: "Diese Stangen sollen in die Ringe an der Längsseite gesteckt werden, damit man die Lade tragen kann." },
      { number: 15, text: "Die Stangen müssen in den Ringen bleiben und dürfen nicht herausgezogen werden." },
      { number: 16, text: "In die Lade sollst du die Tafeln mit dem Zeugnis des Bundes legen, die ich dir geben werde." },
      { number: 17, text: "Lass dann eine Deckplatte* aus reinem Gold herstellen: eineinviertel Meter lang und dreiviertel Meter breit.", footnotes: ["Deckplatte. Das hebräische Wort ist von einem Verb abgeleitet, das ursprünglich \"verdecken\", gewöhnlich aber \"sühnen, versöhnen\" bedeutet. Vergleiche Hebräer 9,5!"] },
      { number: 18, text: "Weiter lass zwei Cherubim-Figuren* aus getriebenem Gold herstellen.", footnotes: ["Cherub, Mehrzahl: Cherubim: Majestätisches (Engel-)Wesen, das Gottes Herrlichkeit repräsentiert."] },
      { number: 19, text: "Sie sollen sich an den beiden Enden der Deckplatte befinden und fest mit ihr verbunden sein." },
      { number: 20, text: "Die Cherubim sollen ihre Flügel nach oben über die Deckplatte ausgebreitet halten. Ihre Gesichter sollen einander zugewandt und ihr Blick auf die Deckplatte gerichtet sein." },
      { number: 21, text: "In die Lade sollst du die beiden Tafeln legen, die ich dir geben werde. Verschließ dann die Lade mit der Deckplatte." },
      { number: 22, text: "Dort über der Deckplatte werde ich dir begegnen und von der Stelle zwischen den zwei Cherubim aus mit dir reden und dir die Anweisungen für die Israeliten geben.\"" },
      { number: 23, text: "\"Lass einen Tisch aus Akazienholz machen, einen Meter lang, einen halben Meter breit und dreiviertel Meter hoch!", heading: "Der Tisch für die geweihten Brote" },
      { number: 24, text: "Lass ihn mit Gold überziehen und mit einer goldenen Schmuckleiste einfassen!" },
      { number: 25, text: "Er soll auch einen Rahmen von zehn Zentimeter Höhe haben, der ebenfalls von einer goldenen Schmuckleiste eingefasst ist." },
      { number: 26, text: "Lass vier goldene Ringe für ihn anfertigen und an den Kanten der vier Füße befestigen!" },
      { number: 27, text: "Die Ringe sollen dicht an dem Rahmen sein und als Ösen für die Stangen dienen, damit man den Tisch tragen kann." },
      { number: 28, text: "Die Tragstangen sollen aus Akazienholz sein und ebenfalls mit Gold überzogen werden." },
      { number: 29, text: "Lass schließlich die Schüsseln und Schalen, die Kannen und Kellen anfertigen, die für das Trankopfer gebraucht werden. Auch sie müssen aus reinem Gold hergestellt werden." },
      { number: 30, text: "Auf dem Tisch sollen immer die geweihten Brote vor mir ausgelegt sein.\"" },
      { number: 31, text: "\"Lass einen Leuchter aus reinem Gold machen. Der Leuchter, sein Fußgestell und sein Schaft, seine Kelche, Knäufe und Blüten sollen aus einem Stück getrieben sein.", heading: "Der goldene Leuchter" },
      { number: 32, text: "Von seinem Schaft sollen je drei Arme nach beiden Seiten ausgehen," },
      { number: 33, text: "jeder von ihnen mit drei Kelchen in Form von Mandelblüten verziert und jede mit einem Knauf darunter." },
      { number: 34, text: "Auch auf dem Schaft selbst sollen sich vier solcher Blütenkelche mit Knauf befinden," },
      { number: 35, text: "drei davon unter den Ansatzstellen der Armpaare." },
      { number: 36, text: "Der ganze Leuchter mit seinen Knäufen und Armen soll aus einem Stück gearbeitet sein und aus reinem Gold bestehen." },
      { number: 37, text: "Lass dann sieben Lampen machen und setze sie so darauf, dass sie ihr Licht nach vorn fallen lassen." },
      { number: 38, text: "Auch seine Dochtscheren und Pfännchen sollen aus reinem Gold sein." },
      { number: 39, text: "Aus einem Block* reinen Goldes sollst du ihn und seine Geräte anfertigen lassen.", footnotes: ["einem Block. Hebräisch: ein Kikkar = Talent, d.h. etwa 34,5 Kilogramm."] },
      { number: 40, text: "Und achte darauf, dass alles genau nach dem Modell angefertigt wird, das dir hier auf dem Berg gezeigt worden ist!\"" },
    ] },
    { number: 26, verses: [
      { number: 1, text: "\"Für die Wohnung sollst du zehn Zeltdecken anfertigen lassen. Sie sollen aus gezwirnten Leinenfäden gewebt und künstlerisch mit Cherubim aus blauer, roter und karmesinroter Wolle bestickt sein.", heading: "Die Zeltdecken für das Heiligtum" },
      { number: 2, text: "Jede dieser Zeltdecken soll vierzehn Meter lang und zwei Meter breit sein." },
      { number: 3, text: "Je fünf Zeltdecken sollen an den Längsseiten miteinander vernäht werden." },
      { number: 4, text: "Auch die so entstandenen Stücke sollen zusammengefügt werden können. Lass deshalb an den beiden Längsseiten je fünfzig Schlaufen aus blauem Purpur anbringen," },
      { number: 5, text: "die sich genau gegenüber stehen, wenn man die Stücke nebeneinander legt." },
      { number: 6, text: "Dann lass fünfzig Haken aus Gold herstellen, mit denen man beide Zeltdecken verbinden kann, sodass es ein Ganzes wird." },
      { number: 7, text: "Weiterhin sollst du für die Überdachung elf Zeltbahnen aus Ziegenhaar herstellen lassen." },
      { number: 8, text: "Jede einzelne Bahn muss fünfzehn Meter lang und zwei Meter breit sein." },
      { number: 9, text: "Fünf dieser Zeltbahnen sollen miteinander verbunden werden und ebenso die anderen sechs. Die sechste Bahn soll dann an der Vorderseite des Zeltes doppelt gelegt werden." },
      { number: 10, text: "Am Ende der beiden großen Stücke, die verbunden werden sollen, lass je fünfzig Schlaufen anbringen." },
      { number: 11, text: "Dann lass fünfzig Bronzehaken herstellen und in die Schlaufen einfügen, sodass es ein Ganzes wird." },
      { number: 12, text: "Die halbe Zeltbahn, die übersteht, soll dann über der Rückseite der Wohnung hängen." },
      { number: 13, text: "Und was von der Länge der Bahnen übersteht, soll links und rechts an den Seiten der Wohnung je einen halben Meter überhängen." },
      { number: 14, text: "Lass schließlich noch eine Decke aus rot gefärbten Fellen von Schafböcken herstellen und oben darüber eine Decke aus Tachasch-Häuten.\"" },
      { number: 15, text: "\"Lass auch Bretter für die Wohnung herstellen! Sie sollen aus Akazienholz sein und aufrecht stehen.", heading: "Die Holzwände des Heiligtums" },
      { number: 16, text: "Jedes Brett muss fünf Meter lang und dreiviertel Meter breit sein" },
      { number: 17, text: "und unten zwei nebeneinanderstehende Zapfen haben." },
      { number: 18, text: "Zwanzig Bretter sollen die Südseite der Wohnung bilden." },
      { number: 19, text: "Unter jedem Brett müssen zwei Bodenplatten aus Silber angebracht sein, für jeden Zapfen eine, vierzig insgesamt." },
      { number: 20, text: "Auch die andere Längsseite der Wohnung, die Nordseite, wird aus zwanzig Brettern" },
      { number: 21, text: "mit ihren vierzig silbernen Bodenplatten gebildet, je zwei unter einem Brett." },
      { number: 22, text: "Für die Rückwand nach Westen lass sechs Bretter machen." },
      { number: 23, text: "Dazu kommen zwei Bretter für die Ecken an der Rückseite." },
      { number: 24, text: "Sie sollen die Rückwand mit den Seitenwänden verbinden.*", footnotes: ["verbinden. Die Ausdrücke für die genaue Beschreibung der Eckbohlen sind unverständlich."] },
      { number: 25, text: "Es sollen also acht Bretter mit sechzehn silbernen Bodenplatten sein, zwei unter jedem Brett." },
      { number: 26, text: "Lass auch Riegel aus Akazienholz anfertigen, um die Bretter der Wohnung zusammenzuhalten," },
      { number: 27, text: "je fünf für die beiden Längsseiten und fünf für die nach Westen gerichtete Rückseite." },
      { number: 28, text: "Der jeweils mittlere Riegel soll in der Mitte der Bretter von einem Ende bis zum anderen durchlaufen.*", footnotes: ["durchlaufen. Manche nehmen an, dass der mittlere Riegel durch eine Bohrung der Bretter lief, wofür es aber sonst keinen Hinweis gibt."] },
      { number: 29, text: "Die Bretter selbst sollen mit Gold überzogen werden, ebenso die Riegel. Die Ösen für die Riegel sollen aus Gold hergestellt werden." },
      { number: 30, text: "So lass die Wohnung nach dem Bauplan aufrichten, der dir auf dem Berg gezeigt worden ist.\"" },
      { number: 31, text: "\"Lass einen Vorhang aus gezwirntem Leinen anfertigen, der künstlerisch mit Cherubim aus blauer, roter und karmesinroter Wolle bestickt ist.", heading: "Die Vorhänge für das Heiligtum" },
      { number: 32, text: "Den sollst du an vier Säulen aus Akazienholz hängen, die mit Gold überzogen sind, Haken aus Gold haben und auf silbernen Bodenplatten stehen." },
      { number: 33, text: "Häng den Vorhang an die Haken. Er soll das Heilige vom Höchstheiligen trennen. Hinter den Vorhang stellst du die Bundeslade" },
      { number: 34, text: "und legst dort im Höchstheiligen die Deckplatte darauf." },
      { number: 35, text: "Vor den Vorhang stellst du den Tisch an die Nordseite der Wohnung und ihm gegenüber an die Südseite den Leuchter." },
      { number: 36, text: "Für den Eingang des Zeltes lass einen Vorhang aus gezwirntem Leinen machen, worin blaue, rote und karmesinrote Wollfäden eingewebt sind." },
      { number: 37, text: "Für den Vorhang lass fünf Säulen aus Akazienholz herstellen, die mit Gold überzogen sind. Sie sollen Haken aus Gold haben, und jede soll auf einer aus Bronze gegossenen Bodenplatte stehen.\"" },
    ] },
    { number: 27, verses: [
      { number: 1, text: "\"Lass den Altar aus Akazienholz anfertigen. Er soll viereckig sein, zweieinhalb Meter lang und ebenso breit und eineinhalb Meter hoch.", heading: "Der tragbare Brandopferaltar" },
      { number: 2, text: "An seinen vier oberen Ecken sollen Hörner aufragen, die aus einem Stück mit dem Altar bestehen. Lass ihn mit Bronzeblechen beschlagen." },
      { number: 3, text: "Auch die Töpfe, die man braucht, um ihn von der Fettasche* zu reinigen, die Schaufeln, die Schalen zum Auffangen des Blutes, die Fleischgabeln und Feuerbecken sollen aus Bronze hergestellt werden.", footnotes: ["Fettasche bildete sich aus den verbrannten Holz- und Fettstücken."] },
      { number: 4, text: "Lass ein netzartiges Gitter aus Bronze anfertigen und befestige vier Ringe an seinen Ecken." },
      { number: 5, text: "Dieses Gitter soll von unten her in die Einfassung des Altars geführt werden, dass es innen bis zur halben Höhe des Altars reicht." },
      { number: 6, text: "Lass auch Stangen aus Akazienholz für den Altar machen und mit Bronze überziehen." },
      { number: 7, text: "Die Stangen werden durch die Ringe gesteckt, so dass sie sich an beiden Seiten des Altars befinden, wenn man ihn trägt." },
      { number: 8, text: "Der Altar soll aus Brettern zusammengefügt und innen hohl sein. Lass ihn so machen, wie es dir auf dem Berg gezeigt worden ist.\"" },
      { number: 9, text: "\"Lass den Vorhof der Wohnung mit einer Abgrenzung umgeben. An seiner Südseite sollen auf fünfzig Meter Länge Planen aus gezwirnter Leinwand hängen,", heading: "Der Vorhof des Heiligtums" },
      { number: 10, text: "die von zwanzig Säulen gehalten werden. Die Säulen müssen Sockel aus Bronze haben. Die Haken und die Verbindungsstangen sollen jedoch aus Silber bestehen." },
      { number: 11, text: "Genauso soll die fünfzig Meter lange Nordseite aussehen." },
      { number: 12, text: "Auf der Westseite soll der Vorhof 25 Meter breit sein. Seine Planen sollen von zehn Säulen gehalten werden." },
      { number: 13, text: "Auch die dem Sonnenaufgang zugekehrte Ostseite soll 25 Meter breit sein." },
      { number: 14, text: "An ihrer linken Seite sollen Planen auf siebeneinhalb Meter Länge an drei Säulen hängen" },
      { number: 15, text: "und ebenso an ihrer rechten Seite." },
      { number: 16, text: "Das Tor des Vorhofs soll eine Plane von zehn Meter Breite haben, die aus gezwirntem Leinen besteht, worin blaue, rote und karmesinrote Wollfäden eingewebt sind. Sie soll an vier Säulen aufgehängt werden." },
      { number: 17, text: "Alle Säulen des Vorhofs sollen Verbindungsstangen und Haken aus Silber und Sockel aus Bronze haben." },
      { number: 18, text: "Der ganze Vorhof ist also fünfzig Meter lang und 25 Meter breit. Die Planen aus dem gezwirnten Leinen ringsherum sind zweieinhalb Meter hoch. Die Sockel müssen alle aus Bronze sein." },
      { number: 19, text: "Alle Geräte der Wohnung, die zu irgendeiner Sache gebraucht werden, auch die Zeltpflöcke für die Wohnung und den Vorhof, sollen aus Bronze sein.\"" },
      { number: 20, text: "\"Nun befiehl den Israeliten, dass sie dir reines Öl aus zerstoßenen Oliven für den Leuchter bringen, um das Licht am Brennen zu halten.", heading: "Das Öl für den Leuchter im Heiligtum" },
      { number: 21, text: "Aaron und seine Söhne sollen dafür sorgen, dass die Lampen im Zelt der Gottesbegegnung, außerhalb des Vorhangs vor der Bundeslade, vom Abend bis zum Morgen brennen. Das ist eine beständige Ordnung für die Israeliten, auch in künftigen Generationen.\"" },
    ] },
    { number: 28, verses: [
      { number: 1, text: "\"Du sollst nun deinen Bruder Aaron und seine Söhne aus der Mitte der Israeliten zu dir kommen lassen, denn sie sollen mir als Priester dienen: Aaron und seine Söhne Nadab, Abihu, Eleasar und Itamar.", heading: "Die Amtskleidung des Hohen Priesters" },
      { number: 2, text: "Lass für deinen Bruder Aaron besondere Gewänder anfertigen, die Würde und Schönheit ausdrücken." },
      { number: 3, text: "Rede mit allen, die etwas davon verstehen und von mir mit Weisheit erfüllt wurden. Sie sollen die Gewänder für Aaron anfertigen, die zeigen, dass er mir als geweihter Priester dient." },
      { number: 4, text: "Folgende Kleidungsstücke sollen sie für deinen Bruder Aaron und seine Nachfolger anfertigen: eine Brusttasche, ein Efod, ein Obergewand, ein Hemd mit eingewebten Mustern, einen Kopfbund und einen Gürtel." },
      { number: 5, text: "Als Material sollen sie Gold, blaue, rote und karmesinrote Wolle und Leinen nehmen." },
      { number: 6, text: "Das Efod sollen sie aus gezwirntem Leinen machen und künstlerisch mit Goldfäden, blauer, roter und karmesinroter Wolle besticken." },
      { number: 7, text: "Es soll auf beiden Seiten ein Paar mit ihm verbundene Schulterstücke haben." },
      { number: 8, text: "Der Gürtel, mit dem es befestigt wird, soll aus demselben Material bestehen und mit ihm verbunden sein." },
      { number: 9, text: "Dann sollst du auf zwei Onyxsteinen die Namen der Söhne Israels eingravieren lassen," },
      { number: 10, text: "auf jeden Stein sechs Namen nach der Reihenfolge ihrer Geburt." },
      { number: 11, text: "Die Namen sollen wie bei der Siegelgravur in die mit Gold eingefassten Steine eingearbeitet werden." },
      { number: 12, text: "Die beiden Steine müssen an den Schulterstücken des Efods befestigt werden, die Steine, die Jahwe an die Israeliten erinnern. Aaron soll ihre Namen auf den Schulterstücken tragen und sie so vor Jahwe in Erinnerung bringen." },
      { number: 13, text: "Lass goldene Einfassungen machen" },
      { number: 14, text: "und zwei Kettchen aus reinem Gold anfertigen, die wie Schnüre gedreht und an den Einfassungen befestigt sind.\"" },
      { number: 15, text: "\"Lass die Brusttasche für den Schiedsspruch anfertigen. Sie soll wie das Efod aus gezwirntem Leinen gemacht und künstlerisch mit Goldfäden und blauer, roter und karmesinroter Wolle bestickt sein.", heading: "Die Brusttasche des Hohen Priesters" },
      { number: 16, text: "Sie muss quadratisch, 25 mal 25 Zentimeter* groß und doppelt gelegt sein.", footnotes: ["25 mal 25 Zentimeter. Wörtlich: eine Spanne lang und eine Spanne breit. Es ist das Maß vom Daumen bis zum kleinen Finger, wenn die Hand gespreizt ist (= eine halbe Elle = 23-25 cm)."] },
      { number: 17, text: "Lass sie mit eingefassten Edelsteinen in vier Reihen besetzen. In der ersten Reihe ein Karneol, ein Topas und ein Smaragd," },
      { number: 18, text: "in der zweiten Reihe ein Rubin, ein Saphir und ein Jaspis," },
      { number: 19, text: "in der dritten Reihe ein Hyazinth, ein Achat und ein Amethyst," },
      { number: 20, text: "und in der vierten Reihe ein Türkis, ein Onyx und ein Nephrit. Alle sollen mit Gold eingefasst sein." },
      { number: 21, text: "In die Steine sollen die Namen der zwölf Söhne Israels eingraviert sein, in jedem Stein ein Name für einen Stamm." },
      { number: 22, text: "Lass zwei gedrehte Kettenschnüre aus reinem Gold für das Brustschild herstellen." },
      { number: 23, text: "An den beiden oberen Ecken des Brustschilds lass zwei goldene Ringe anbringen" },
      { number: 24, text: "und die beiden goldenen Schnüre dort befestigen." },
      { number: 25, text: "Die Enden dieser beiden Schnüre sollen an der Vorderseite der Schulterstücke befestigt werden." },
      { number: 26, text: "Lass auch zwei goldene Ringe an den beiden unteren Enden der Brusttasche anbringen, und zwar auf der Rückseite," },
      { number: 27, text: "und noch einmal zwei Goldringe für die beiden Schulterstücke des Efods. Sie sollen dicht an seiner Naht, aber oberhalb des Gürtels vom Efod befestigt werden." },
      { number: 28, text: "Man soll das Brustschild mit einer blauen Schnur von seinen Ringen aus mit den Ringen des Efods verknüpfen, sodass es über dem Gurt des Efods sitzt und sich nicht verschieben kann." },
      { number: 29, text: "So soll Aaron auf der Brusttasche für den Schiedsspruch die Namen der Söhne Israels zur ständigen Erinnerung vor Jahwe auf seinem Herzen tragen, wenn er ins Heiligtum hineingeht." },
      { number: 30, text: "In die Brusttasche für den Schiedsspruch lege die Urim und Tummim*, damit sie auf dem Herzen Aarons sind, wenn er hineingeht, um vor Jahwe zu stehen. So soll Aaron den Schiedsspruch für die Israeliten immer vor Jahwe auf dem Herzen tragen.\"", footnotes: ["Urim und Tummim waren die heiligen Lose, die bei schwierigen Entscheidungen den Schiedsspruch herbeiführten. Die Bedeutung der hebräischen Begriffe ist unsicher. Nach der LXX, der griechischen Übersetzung des Alten Testaments, bedeuteten sie Licht und Recht."] },
      { number: 31, text: "\"Das Obergewand, das unter dem Efod getragen wird, soll ganz aus purpurblauem Stoff bestehen.", heading: "Das Obergewand" },
      { number: 32, text: "Die Öffnung für den Kopf in der Mitte soll wie bei der Halseinfassung eines Panzerhemdes mit einer gewebten Borte eingefasst sein, damit sie nicht einreißt." },
      { number: 33, text: "Am unteren Saum sollst du Granatäpfel aus blauer, roter und karmesinroter Wolle befestigen und dazwischen goldene Glöckchen anbringen," },
      { number: 34, text: "sodass um den ganzen Saum herum immer ein Glöckchen auf einen Granatapfel folgt." },
      { number: 35, text: "Aaron soll das Gewand beim Dienst im Heiligtum tragen. Man soll die Glöckchen hören, wenn er zu Jahwe hineingeht und wieder herauskommt, damit er nicht stirbt.\"" },
      { number: 36, text: "\"Dann lass ein Stirnblatt aus reinem Gold herstellen und darauf eingravieren: 'Heilig für Jahwe'.", heading: "Weitere Teile der Kleidung" },
      { number: 37, text: "Das soll mit einer blauen Schnur vorn am Kopfbund befestigt werden," },
      { number: 38, text: "damit es an Aarons Stirn sei. Denn er trägt die Verantwortung für die Verfehlungen im Zusammenhang mit den heiligen Gaben, die die Israeliten zum Opfer bringen. Es soll immer an seiner Stirn sein, damit die Gaben Jahwe gefallen." },
      { number: 39, text: "Lass das leinene Hemd mit eingewebten Mustern anfertigen und den Kopfbund ebenfalls aus Leinen, schließlich den bunt gewirkten Gürtel.\"" },
      { number: 40, text: "\"Auch den Söhnen Aarons sollst du Hemden, Gürtel und Kopfbunde machen, die Würde und Schönheit ausdrücken.", heading: "Die Ausstattung der Priester" },
      { number: 41, text: "Dann sollst du Aaron und seinen Söhnen die Priesterkleidung anlegen. Salbe sie, setze sie ins Amt ein und weihe sie, damit sie mir als Priester dienen." },
      { number: 42, text: "Lass auch leinene Kniehosen für sie anfertigen, damit ihre Scham bedeckt ist." },
      { number: 43, text: "Aaron und seine Söhne sollen sie tragen, wenn sie in das Zelt der Gottesbegegnung gehen oder am Brandopferaltar Dienst tun, damit sie nicht schuldig werden und sterben. Diese Vorschrift gilt ihm und allen seinen Nachkommen für immer.\"" },
    ] },
    { number: 29, verses: [
      { number: 1, text: "\"Tu folgendes, um sie in den Priesterdienst einzusetzen: Wähle einen jungen Stier und zwei Schafböcke aus, fehlerfreie Tiere,", heading: "Regeln für die Einsetzung der Priester" },
      { number: 2, text: "dazu ungesäuertes Lochbrot* und ungesäuertes mit Öl zubereitetes Kuchenbrot und mit Öl bestrichene Fladen aus feinem Weizenmehl.", footnotes: ["Lochbrot. Ein runder Brotlaib, der in der Mitte durchstoßen ist und so auf einer Stange aufgehängt werden kann zum Schutz gegen Schimmel und Tierfraß."] },
      { number: 3, text: "Die legst du in einen Korb und bringst sie im Korb herbei, dazu den jungen Stier und die beiden Schafböcke." },
      { number: 4, text: "Führe Aaron und seine Söhne dann an den Eingang vom Zelt der Gottesbegegnung und wasche sie dort mit Wasser." },
      { number: 5, text: "Dann lege Aaron die Priesterkleider an: das Priesterhemd und das Obergewand mit dem Efod und der Brusttasche. Binde ihm den Gürtel um, der am Efod befestigt ist." },
      { number: 6, text: "Setze ihm den Kopfbund auf und befestige das heilige Stirnblatt daran." },
      { number: 7, text: "Dann gieß ihm das Salböl über den Kopf und weihe ihn." },
      { number: 8, text: "Lass auch seine Söhne herantreten und bekleide sie mit dem Priesterhemd." },
      { number: 9, text: "Dann legst du ihnen den Gürtel an und bindest ihnen die Kopfbunde um. So setzt du Aaron und seine Söhne zum Priesterdienst ein, der ihnen nun für immer übertragen ist." },
      { number: 10, text: "Lass dann den jungen Stier vor das Zelt der Gottesbegegnung bringen. Aaron und seine Söhne sollen ihre Hände fest auf den Kopf des Stiers legen." },
      { number: 11, text: "Dann schlachte den Stier vor Jahwe am Eingang des Zeltes." },
      { number: 12, text: "Nimm etwas von dem Blut und streiche es mit dem Finger an die Hörner des Altars. Das restliche Blut schütte unten an den Altar." },
      { number: 13, text: "Alles Fett an den Eingeweiden, den Fettlappen über der Leber, die beiden Nieren mit ihrem Fett lass auf dem Altar in Rauch aufsteigen." },
      { number: 14, text: "Das Fleisch des jungen Stiers, seine Haut und seine Eingeweide samt Inhalt sollst du außerhalb vom Lager verbrennen. Es ist ein Sündopfer für Jahwe." },
      { number: 15, text: "Aaron und seine Söhne sollen nun ihre Hände fest auf den Kopf des einen Schafbocks legen." },
      { number: 16, text: "Dann schlachte das Tier und sprenge sein Blut ringsum an den Altar." },
      { number: 17, text: "Zerlege es und leg die Stücke und den Kopf auf den Altar. Die Eingeweide und Unterschenkel wäschst du vorher ab." },
      { number: 18, text: "Lass dann den ganzen Schafbock in Rauch aufgehen, es ist ein Brandopfer für Jahwe, ein Feueropfer für ihn, ein Geruch, der ihm angenehm ist." },
      { number: 19, text: "Aaron und seine Söhne sollen ihre Hände dann ebenso auf den Kopf des zweiten Schafbocks legen." },
      { number: 20, text: "Anschließend musst du das Tier schlachten. Nimm etwas von seinem Blut und tupfe es auf das rechte Ohrläppchen, den rechten Daumen und die rechte große Zehe Aarons und seiner Söhne. Das übrige Blut sprengst du ringsum an den Altar." },
      { number: 21, text: "Nimm dann etwas von diesem Blut am Altar und von dem Salböl und sprenge es auf Aaron und seine Gewänder und auch auf seine Söhne und ihre Gewänder, damit sie samt ihrer Kleidung zum Dienst geweiht sind." },
      { number: 22, text: "Dieser zweite Schafbock ist das Einsetzungsopfer. Nimm sein Fett, den Fettschwanz, das Fett an den Eingeweiden, den Fettlappen an der Leber, die beiden Nieren mit ihrem Fett sowie die rechte Hinterkeule," },
      { number: 23, text: "dazu ein Lochbrot, einen Ölkuchen und einen mit Öl bestrichenen Fladen aus dem Korb der ungesäuerten Brote, der vor Jahwe steht," },
      { number: 24, text: "und leg das alles Aaron und seinen Söhnen in die Hände. Sie sollen es Jahwe hin- und herschwingend darbieten." },
      { number: 25, text: "Dann nimmst du es ihnen wieder aus den Händen und lässt es auf dem Altar über dem Brandopfer in Rauch aufgehen, ein Geruch, der Jahwe angenehm ist. Es ist ein Feueropfer für Jahwe." },
      { number: 26, text: "Nimm dann die Brust von dem Einsetzungsopfer für Aaron und biete sie Jahwe schwingend dar. Das soll dein Anteil sein." },
      { number: 27, text: "Dann sondere von dem Einsetzungsopfer für Aaron und seine Söhne das Bruststück des Schwingopfers und die Hinterkeule des Hebopfers ab, welche geschwungen und dann emporgehoben worden sind." },
      { number: 28, text: "Sie gehören Aaron und seinen Söhnen als dauerndes Anrecht gegenüber den Israeliten, denn es ist ein Hebopfer. Auch bei den Freudenopfern der Israeliten sind diese Stücke ein Hebopfer für Jahwe." },
      { number: 29, text: "Die heiligen Gewänder Aarons gehen nach ihm auf seine Nachfolger über. In ihnen sollen sie gesalbt und geweiht werden." },
      { number: 30, text: "Derjenige von seinen Nachkommen, dem es zufällt, als sein Nachfolger ins Zelt der Gottesbegegnung zu gehen und im Heiligtum Dienst zu tun, soll die Gewänder bei seiner Einsetzung sieben Tage lang tragen." },
      { number: 31, text: "Das Fleisch des Einsetzungsopfers sollst du im Bereich des Heiligtums kochen." },
      { number: 32, text: "Dann sollen Aaron und seine Söhne das Fleisch und das Brot im Korb am Eingang vom Zelt der Gottesbegegnung essen." },
      { number: 33, text: "Sie sollen die Stücke essen, mit denen die Sühne vollzogen wurde, um sie zum Dienst zu weihen. Niemand sonst darf davon essen, es ist heilig." },
      { number: 34, text: "Was vom Fleisch des Einsetzungsopfers und vom Brot am nächsten Morgen noch übrig ist, muss verbrannt werden. Man darf es nicht essen, es ist heilig." },
      { number: 35, text: "An sieben Tagen nacheinander sollst du das ganze Einsetzungsopfer wiederholen." },
      { number: 36, text: "Täglich sollst du einen jungen Stier als Sündopfer schlachten und den Altar entsündigen. Du sollst die Sühne an ihm vollziehen und ihn durch Salbung heiligen." },
      { number: 37, text: "An sieben Tagen sollst du das wiederholen. Dann wird der Altar höchst heilig sein: Alles, was ihn berührt, ist dem Heiligtum verfallen.\"" },
      { number: 38, text: "\"Jeden Tag sollst du zwei einjährige Lämmer als Brandopfer darbringen lassen,", heading: "Die täglichen Opfer" },
      { number: 39, text: "das eine am Morgen, das zweite am späten Nachmittag." },
      { number: 40, text: "Dazu kommen als Speisopfer jeweils zwei Litergefäße* mit Feinmehl, das mit einem knappen Liter* Öl aus zerstoßenen Oliven vermengt ist, und als Trankopfer je einen knappen Liter Wein.", footnotes: ["zwei Litergefäße. Wörtlich: ein Zehntel (Efa) = 2,2 Liter.", "Litergefäße. Wörtlich: ein Viertel Hin = 0,9 Liter"] },
      { number: 41, text: "Das ist ein Feueropfer für Jahwe, ein Geruch, der ihm angenehm ist." },
      { number: 42, text: "Ihr sollt das als regelmäßiges Brandopfer vor Jahwe darbringen, und zwar am Eingang vom Zelt der Gottesbegegnung, also dort, wo ich euch begegnen werde, um mit dir zu reden." },
      { number: 43, text: "Dort werde ich den Israeliten begegnen, und das Zelt wird durch meine Herrlichkeit geheiligt sein." },
      { number: 44, text: "Ich werde das Zelt der Gottesbegegnung und den Altar heiligen. Auch Aaron und seine Söhne mache ich heilig, damit sie mir als Priester dienen können." },
      { number: 45, text: "Und ich werde mitten unter den Israeliten wohnen und ihr Gott sein." },
      { number: 46, text: "Und sie werden erkennen, dass ich, Jahwe, ihr Gott bin, der sie aus Ägypten herausgeführt hat, um in ihrer Mitte zu wohnen; ich, Jahwe, ihr Gott.\"" },
    ] },
    { number: 30, verses: [
      { number: 1, text: "\"Du sollst auch einen Räucheraltar machen lassen, auf dem Weihrauch verbrannt wird. Er muss aus Akazienholz bestehen", heading: "Der Räucheraltar" },
      { number: 2, text: "und viereckig, einen halben Meter lang, ebenso breit und einen Meter hoch sein. Seine Hörner müssen aus einem Stück mit ihm bestehen." },
      { number: 3, text: "Lass ihn mit reinem Gold überziehen, seine Platte, seine Wände und seine Hörner und lass ringsum eine goldene Leiste anbringen." },
      { number: 4, text: "Unter dieser Leiste müssen an beiden Seiten je zwei goldene Ringe angebracht sein, durch die die Tragstangen gesteckt werden können." },
      { number: 5, text: "Die Stangen müssen aus Akazienholz sein und mit Gold überzogen werden." },
      { number: 6, text: "Stell diesen Altar vor dem Vorhang auf, hinter dem sich die Bundeslade und ihre Deckplatte befinden, von der aus ich dir begegnen will." },
      { number: 7, text: "Aaron soll jeden Morgen, wenn er die Lampen zurichtet, wohlriechenden Weihrauch auf ihm verbrennen." },
      { number: 8, text: "Auch wenn er am späten Nachmittag die Lampen aufsetzt, soll er Weihrauch aufsteigen lassen. Dieses Räucheropfer soll auch in künftigen Generationen regelmäßig vor Jahwe aufsteigen." },
      { number: 9, text: "Ihr dürft keine fremden Duftstoffe auf diesem Altar verbrennen, auch kein Brand- oder Speisopfer. Auch kein Trankopfer darf über ihm ausgegossen werden." },
      { number: 10, text: "Einmal im Jahr soll Aaron mit dem Blut des Sündopfers der Versöhnung an seinen Hörnern die Sühne vollziehen. Das gilt auch für alle weiteren Generationen, denn der Altar ist höchst heilig für Jahwe.\"" },
      { number: 11, text: "Jahwe sagte zu Mose:", heading: "Die Kopfsteuer für das Heiligtum" },
      { number: 12, text: "\"Wenn du die Gesamtzahl der Israeliten ermittelst, dann soll jeder Gemusterte Jahwe ein Lösegeld für sein Leben zahlen, damit bei der Musterung keine Seuche über das Volk kommt." },
      { number: 13, text: "Jeder, der bei der Musterung erfasst wird, soll ein halbes Silberstück geben, wobei ein Silberstück nach dem Gewicht des Heiligtums zwölf Gramm wiegt. Es ist eine Abgabe für Jahwe." },
      { number: 14, text: "Jeder männliche Israelit ab zwanzig Jahren, der durch die Musterung geht, soll sie für Jahwe geben." },
      { number: 15, text: "Ein Reicher soll nicht mehr und ein Armer nicht weniger als ein halbes Silberstück geben, wenn ihr Jahwe diese Abgabe bringt, um Sühne für euer Leben zu erwirken." },
      { number: 16, text: "Du sollst dieses Sühnegeld von den Israeliten für die Arbeit am Zelt der Gottesbegegnung nehmen. So bringt es die Israeliten vor Jahwe in Erinnerung und wird euer Leben bewahren.\"" },
      { number: 17, text: "Jahwe sagte zu Mose:", heading: "Das Wasserbecken" },
      { number: 18, text: "\"Lass ein Wasserbecken aus Bronze und dazu einen bronzenen Untersatz anfertigen. Stell es zwischen das Zelt der Gottesbegegnung und den Altar und füll es mit Wasser." },
      { number: 19, text: "Aaron und seine Söhne sollen ihre Hände und Füße dort waschen." },
      { number: 20, text: "Sie sollen sich waschen, wenn sie ins Zelt der Gottesbegegnung gehen, damit sie nicht sterben. Auch wenn sie an den Altar herantreten, um ein Opfer für Jahwe dort in Rauch aufgehen zu lassen," },
      { number: 21, text: "sollen sie Hände und Füße waschen, damit sie nicht sterben. Diese Anordnung gilt für Aaron und alle seine Nachkommen.\"" },
      { number: 22, text: "Jahwe sagte zu Mose:", heading: "Salböl und Weihrauch" },
      { number: 23, text: "\"Nimm dir Balsamöle von bester Sorte: sechs Kilogramm selbst ausgeflossene Myrrhe*, je drei Kilogramm wohlriechenden Zimt, Würzrohr*", footnotes: ["Myrrhe. Ein sehr kostbares wohlriechendes Harz afrikanisch-arabischer Herkunft, das in Salbölen und Arzneien verarbeitet wurde.", "Würzrohr. Gemeint ist das Mark aus den Wurzeln einer Schilfpflanze."] },
      { number: 24, text: "und Kassia*, wie es dem Gewicht des Heiligtums entspricht, dazu dreieinhalb Liter Olivenöl.", footnotes: ["Kassia. Gemeint sind wahrscheinlich Duftstoffe und das Öl, das aus der Rinde des Zimt-Kassienbaums in Südchina gewonnen wurde."] },
      { number: 25, text: "Lass daraus ein wohlriechendes Salböl für heilige Salbungen herstellen, wie Salbenmischer das machen." },
      { number: 26, text: "Damit sollst du das Zelt der Gottesbegegnung und die Bundeslade salben," },
      { number: 27, text: "auch den Tisch mit seinen Gegenständen, den Leuchter mit allem, was dazu gehört, und den Räucheraltar," },
      { number: 28, text: "den Brandopferaltar mit allen Gegenständen, die dazu gehören, und schließlich das Wasserbecken und sein Gestell." },
      { number: 29, text: "Dadurch wird alles mir geweiht und höchst heilig sein. Jeder Unbefugte, der etwas davon berührt, ist dem Heiligtum verfallen." },
      { number: 30, text: "Auch Aaron und seine Söhne sollst du mit dem Öl salben, wenn du sie in den Priesterdienst einsetzt." },
      { number: 31, text: "Den Israeliten aber sollst du sagen: 'Das ist ein Öl, das nur für mich bestimmt ist und nur für die heilige Salbung gebraucht werden darf." },
      { number: 32, text: "Es darf nicht auf die Haut gewöhnlicher Menschen kommen. Ihr dürft auch nichts herstellen, was diesem Öl in seiner Zusammensetzung gleicht. Es ist heilig und ihr sollt es auch so achten." },
      { number: 33, text: "Wer eine solche Mischung herstellt oder etwas von dem Öl auf einen Unbefugten streicht, soll von der Gemeinschaft des Volkes beseitigt* werden.'\"", footnotes: ["beseitigt. Das bedeutete entweder Verbannung oder Tod."] },
      { number: 34, text: "Jahwe sagte zu Mose: \"Nimm dir Duftstoffe zu gleichen Teilen: Staktetropfen*, Räucherklaue*, wohlriechendes Galbanum* und reines Weihrauchharz", footnotes: ["Staktetropfen. Wahrscheinlich ein wohlriechendes Harz.", "Räucherklaue. Gehäuse einer Meeresschneckenart, das beim Verbrennen stark riecht.", "Galbanum. Saft aus einem in Syrien heimischen Arzneikraut."] },
      { number: 35, text: "und lass daraus eine Mischung für das Räucheropfer herstellen, wie es Salbenmischer machen. Füge auch etwas Salz hinzu und verwende nur reine Stoffe." },
      { number: 36, text: "Zerstoße jeweils einen Teil davon zu Pulver und leg es vor die Bundeslade im Zelt der Gottesbegegnung, also dorthin, wo ich dir begegnen werde. Es soll euch als etwas Höchstheiliges gelten." },
      { number: 37, text: "Ihr dürft nichts herstellen, was dieser Weihrauchmischung gleicht. Es soll euch als etwas Heiliges gelten, das Jahwe gehört." },
      { number: 38, text: "Wer es nachmacht, um daran zu riechen, soll von der Gemeinschaft des Volkes beseitigt werden.\"" },
    ] },
    { number: 31, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Die Berufung der Kunsthandwerker" },
      { number: 2, text: "\"Pass auf! Ich habe Bezalel Ben-Uri, den Enkel von Hur aus dem Stamm Juda, berufen" },
      { number: 3, text: "und ihn mit dem Geist Gottes erfüllt, mit Weisheit und Verstand und kunsthandwerklichem Geschick." },
      { number: 4, text: "Er kann Pläne entwerfen und danach Gegenstände aus Gold, Silber und Bronze anfertigen." },
      { number: 5, text: "Er kann Edelsteine schneiden und einfassen, er versteht sich auf Holzschnitzerei und ist in jeder künstlerischen Technik erfahren." },
      { number: 6, text: "Ich habe ihm Oholiab Ben-Ahisamach aus dem Stamm Dan zur Seite gestellt. Dazu habe ich alle kunstbegabten Handwerker befähigt, alles herzustellen, was ich angeordnet habe:" },
      { number: 7, text: "das Zelt der Gottesbegegnung, die Bundeslade und die Deckplatte darauf und alle Gegenstände, die zum Zelt gehören;" },
      { number: 8, text: "dazu den Tisch mit seinen Gegenständen, den Leuchter aus reinem Gold und alles, was dazugehört, den Räucheraltar," },
      { number: 9, text: "den Brandopferaltar und alles, was dazugehört, das Becken und sein Gestell," },
      { number: 10, text: "die Dienstkleider und die heiligen Gewänder für Aaron und die Priesterkleider für seine Söhne," },
      { number: 11, text: "das Salböl und die Weihrauchmischung für das Heiligtum. Sie sollen alles genauso machen, wie ich es dir befohlen habe.\"" },
      { number: 12, text: "Jahwe sagte zu Mose:", heading: "Das Sabbatgebot" },
      { number: 13, text: "\"Du sollst den Israeliten einschärfen, dass sie nur ja meine Sabbate halten. Denn sie sind ein Zeichen für den Bund zwischen mir und euch, auch für alle späteren Generationen. Daran soll man erkennen, dass ich Jahwe bin, der euch heiligt." },
      { number: 14, text: "Haltet also den Sabbat! Ja, als heilig soll er euch gelten! Jeder, der an diesem Tag eine Arbeit verrichtet, soll von der Gemeinschaft des Volkes beseitigt werden." },
      { number: 15, text: "Sechs Tage in der Woche soll man arbeiten, aber am siebten Tag ist Sabbat, ein Tag völliger Ruhe, der Jahwe gehört. Jeder, der am Sabbat arbeitet, muss unbedingt getötet werden." },
      { number: 16, text: "Die Israeliten sollen also den Sabbat halten. Und auch all ihre Nachkommen sollen ihn als ewigen Bund feiern." },
      { number: 17, text: "Er ist ein Zeichen des Bundes zwischen mir und den Israeliten für immer. Denn in sechs Tagen hat Jahwe Himmel und Erde gemacht. Am siebten Tag jedoch hat er geruht und Atem geschöpft.\"" },
      { number: 18, text: "Als Jahwe Mose auf dem Berg Sinai alles gesagt hatte, übergab er ihm die beiden Tafeln mit dem Bundesgesetz, auf die der Finger Gottes geschrieben hatte." },
    ] },
    { number: 32, verses: [
      { number: 1, text: "Als dem Volk das Warten auf die Rückkehr Moses zu viel wurde, sammelten sie sich bei Aaron und sagten zu ihm: \"Los! Mach uns einen Gott, der vor uns herzieht! Denn was aus diesem Mose geworden ist, der uns aus Ägypten hergeführt hat, wissen wir nicht.\"", heading: "Gottes Bund ist in Gefahr (32-35)\nDas goldene Kalb: der Bundesbruch" },
      { number: 2, text: "Aaron erwiderte: \"Nehmt euren Frauen, Söhnen und Töchtern die goldenen Ringe ab und bringt sie mir!\"" },
      { number: 3, text: "Da zerrten sich alle die goldenen Ohrringe ab und brachten sie zu Aaron." },
      { number: 4, text: "Der nahm das Gold entgegen, schmolz es ein und verwendete es, um die Skulptur* von einem Kalb anzufertigen. Da riefen alle: \"Hier ist dein Gott, Israel, der dich aus dem Land Ägypten herausgeführt hat!\"", footnotes: ["Skulptur. Vermutlich ein mit Goldblech beschlagenes Holzmodell, denn es wurde später (V. 20) verbrannt."] },
      { number: 5, text: "Als Aaron das sah, baute er einen Altar davor und rief: \"Morgen ist ein Fest für Jahwe!\"" },
      { number: 6, text: "Am folgenden Tag standen sie früh auf und opferten Brand- und Freudenopfer. Dann setzten sie sich hin, um zu essen und zu trinken. Anschließend standen sie auf, um sich zu vergnügen.*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: 1. Korinther 10,7"] },
      { number: 7, text: "Da sagte Jahwe zu Mose: \"Geh, steig hinunter, denn dein Volk, das du aus Ägypten hierher geführt hast, läuft ins Verderben!" },
      { number: 8, text: "Sie sind schnell von dem Weg abgewichen, den ich ihnen vorgeschrieben habe. Ein Stierkalb haben sie sich gebaut und sind vor ihm niedergefallen. Sie haben ihm Opfer gebracht und gesagt: 'Das ist dein Gott, Israel, der dich aus dem Land Ägypten hierher geführt hat.'\"" },
      { number: 9, text: "Weiter sagte Jahwe zu Mose: \"Ich habe gesehen, wie eigensinnig dieses Volk ist." },
      { number: 10, text: "Lass mich jetzt meinen Zorn über sie ausschütten und sie vernichten. Dafür werde ich dich zu einem großen Volk machen.\"" },
      { number: 11, text: "Doch Mose flehte Jahwe, seinen Gott, an und sagte: \"O Jahwe, warum willst du deinen Zorn über dein Volk ausschütten, das du eben erst mit großer Macht und starker Hand aus Ägypten herausgeführt hast?" },
      { number: 12, text: "Warum sollen die Ägypter sagen dürfen: 'Er hat sie nur herausgeführt, um sie dort am Berg umzubringen und vom Erdboden verschwinden zu lassen.'? Lass ab von deinem glühenden Zorn und lass das Unheil nicht über dein Volk kommen!" },
      { number: 13, text: "Denk an deine Diener Abraham, Isaak und Israel, denen du bei dir selbst geschworen hast, ihre Nachkommen so zahlreich zu machen wie die Sterne am Himmel. Du hast ihnen zugesichert, dass ihre Nachkommen dieses Land für immer in Besitz nehmen werden.\"" },
      { number: 14, text: "Da tat es Jahwe leid, seinem Volk das angedrohte Unheil anzutun." },
      { number: 15, text: "Mose kehrte um und stieg den Berg hinunter. In der Hand hielt er die beiden Tafeln mit dem Bundesgesetz. Sie waren vorn und hinten beschrieben." },
      { number: 16, text: "Diese Tafeln waren Gottes Werk, und die Schrift darauf war von Gott selbst eingraviert worden." },
      { number: 17, text: "Als Josua den Lärm hörte, den das Volk im Lager machte, sagte er zu Mose: \"Es muss Krieg im Lager sein!\"" },
      { number: 18, text: "\"Nein\", sagte Mose, \"das klingt nicht wie Siegesjubel und auch nicht wie das Klagegeschrei nach einer Niederlage. Was ich höre, klingt nach Festgesang!\"" },
      { number: 19, text: "Als Mose dem Lager näher kam, das Stierkalb erblickte und die Reigentänze sah, packte ihn der Zorn, und er zerschmetterte die Tafeln unten am Berg." },
      { number: 20, text: "Dann nahm er das Stierkalb, das sie gemacht hatten, und warf es ins Feuer. Schließlich zermalmte er alles zu Staub und streute ihn auf das Wasser, das die Israeliten trinken mussten." },
      { number: 21, text: "Zu Aaron sagte er: \"Was hat dir das Volk angetan, dass du es in so schwere Sünde gebracht hast?\"" },
      { number: 22, text: "Aaron erwiderte: \"Werde bitte nicht zornig, mein Herr. Du weißt doch, wie böse dieses Volk ist." },
      { number: 23, text: "Sie haben zu mir gesagt: 'Mach uns einen Gott, der vor uns herzieht! Denn wir wissen nicht, was aus diesem Mose geworden ist, der uns aus Ägypten hierher geführt hat.'" },
      { number: 24, text: "Da fragte ich sie: 'Wer hat Gold?' Da rissen sie es sich ab und gaben es mir. Ich habe es ins Feuer geworfen, und da ist dieses Stierkalb daraus geworden.\"" },
      { number: 25, text: "Mose begriff, dass das Volk zügellos geworden war, denn Aaron hatte die Zügel schleifen lassen – zur Schadenfreude ihrer Feinde." },
      { number: 26, text: "Mose stellte sich an den Eingang des Lagers und rief: \"Her zu mir, wer für Jahwe ist!\" Da sammelten sich alle Leviten* um ihn.", footnotes: ["Leviten sind die Nachkommen des Stammes Levi (2. Mose 1,2)."] },
      { number: 27, text: "Er sagte zu ihnen: \"So spricht Jahwe, der Gott Israels: Jeder von euch hole sein Schwert! Dann geht ihr durch das ganze Lager hin und her von einem Tor zum andern und erschlagt alle Götzendiener*, selbst wenn es der eigene Bruder, Freund oder Verwandte ist.\"", footnotes: ["Alle Götzendiener. Alle Götzendiener. Hinzugefügt nach der Aussage von 1. Korinther 10,7, die sich auf dieses Geschehen hier bezieht."] },
      { number: 28, text: "Die Leviten führten den Befehl Moses aus und töteten an jenem Tag etwa dreitausend Mann." },
      { number: 29, text: "Darauf sagte Mose zu ihnen: \"Weiht euch heute für Jahwe, damit er seinen Segen auf euch legt, denn keiner von euch hat den eigenen Sohn oder Bruder verschont.\"" },
      { number: 30, text: "Am nächsten Tag sagte Mose zum Volk: \"Ihr habt gesündigt, schwer gesündigt! Darum will ich jetzt zu Jahwe hinaufsteigen. Vielleicht darf ich eure Sünde zudecken.\"" },
      { number: 31, text: "Darauf kehrte Mose zu Jahwe zurück und sagte: \"Ach, dieses Volk hat eine schwere Sünde begangen: Sie haben sich einen Gott aus Gold gemacht." },
      { number: 32, text: "Wenn du ihnen doch ihre Sünde vergeben könntest! Wenn aber nicht, dann lösch meinen Namen aus dem Buch, das du geschrieben hast.\"" },
      { number: 33, text: "Doch Jahwe sagte: \"Ich lösche nur den aus meinem Buch, der sich an mir vergangen hat." },
      { number: 34, text: "Geh jetzt und führ das Volk an den Ort, den ich dir genannt habe! Pass auf, mein Engel wird vor dir hergehen. Wenn die Zeit gekommen ist, werde ich sie für ihre Sünde zur Rechenschaft ziehen.\"" },
      { number: 35, text: "Jahwe schlug die Israeliten, weil sie Aaron verleitet hatten, das Stierkalb zu machen." },
    ] },
    { number: 33, verses: [
      { number: 1, text: "Jahwe sagte zu Mose: \"Ihr brecht jetzt auf! Bring das Volk, das du aus Ägypten hierher geführt hast, in das Land, das ich Abraham, Isaak und Jakob unter Eid für ihre Nachkommen versprochen habe." },
      { number: 2, text: "Ich werde einen Engel vor dir herschicken und die Kanaaniter, Amoriter, Hetiter, Perisiter, Hiwiter und Jebusiter vertreiben." },
      { number: 3, text: "Ihr kommt in ein Land, das von Milch und Honig überfließt. Aber ich selbst werde nicht mit euch ziehen, denn ihr seid ein widerspenstiges Volk, und vielleicht müsste ich euch deshalb unterwegs vernichten.\"" },
      { number: 4, text: "Als die Israeliten diese harten Worte vernahmen, trauerten sie. Keiner legte seinen Schmuck an." },
      { number: 5, text: "Denn Jahwe hatte zu Mose gesagt: \"Sag den Israeliten: Ihr seid ein widerspenstiges Volk. Würde ich auch nur einen Augenblick in eurer Mitte sein, müsste ich euch vernichten. Aber wenn ihr jetzt euren Schmuck ablegt, werde ich sehen, was ich für euch tun kann.\"" },
      { number: 6, text: "Da trugen die Israeliten vom Berg Horeb an keinen Schmuck mehr." },
      { number: 7, text: "Von da an schlug Mose das Zelt jedes Mal entfernt vom Lager auf. Er nannte es Zelt der Gottesbegegnung.* Jeder, der Jahwe suchte, musste aus dem Lager hinaus zu diesem Zelt gehen.", heading: "Die Erneuerung des Bundes", footnotes: ["Zelt der Gottesbegegnung.Damit ist noch nicht das Heiligtum gemeint, denn dessen Bau wird erst in den folgenden Kapiteln berichtet; es stand mitten im Lager."] },
      { number: 8, text: "Wenn Mose zu dem Zelt ging, standen alle auf. Sie traten an den Eingang ihrer Zelte und sahen Mose nach, bis er im Zelt verschwunden war." },
      { number: 9, text: "Und wenn Mose dort hineinging, kam die Wolkensäule herab und blieb am Eingang des Zeltes stehen. Dann redete Gott mit Mose." },
      { number: 10, text: "Wenn die Israeliten die Wolkensäule am Eingang des Zeltes stehen sahen, standen sie alle auf und warfen sich am Eingang ihrer Zelte nieder." },
      { number: 11, text: "Jahwe redete direkt mit Mose, so, wie ein Mann mit seinem Freund redet. Dann kehrte Mose ins Lager zurück. Sein Diener Josua Ben-Nun, ein junger Mann, blieb ständig im Zelt.*", footnotes: ["blieb ... im Zelt. Josua hatte offenbar die Aufgabe, sich um dieses Zelt zu kümmern."] },
      { number: 12, text: "Mose sagte zu Jahwe: \"Du befiehlst mir, dieses Volk in sein Land zu führen, aber du hast mir nicht offenbart, wen du mitschicken wirst. Dabei hast du mir doch gesagt, dass du mich mit Namen kennst und mir deine Gunst geschenkt hast." },
      { number: 13, text: "Wenn ich also wirklich deine Gunst genieße, dann lass mich doch erkennen, was du vorhast. Ich möchte dich besser verstehen und auch weiter in deiner Gunst bleiben. Denk doch daran: Dieses Volk ist dein Volk!\"" },
      { number: 14, text: "Jahwe erwiderte: \"Wenn ich mitgehe, würde dich das dann beruhigen?\"" },
      { number: 15, text: "Mose entgegnete: \"Wenn du nicht mitgehst, dann bring uns lieber nicht von hier weg!" },
      { number: 16, text: "Woran soll man denn sonst erkennen, dass wir in deiner Gnade stehen, ich und dein Volk? Doch nur daran, dass du mit uns ziehst und uns dadurch vor allen anderen Völkern der Welt auszeichnest, mich und dein Volk!\"" },
      { number: 17, text: "Jahwe erwiderte: \"Auch diese Bitte werde ich dir erfüllen, denn du stehst in meiner Gunst und ich kenne dich genau!\"" },
      { number: 18, text: "Doch er bat ihn weiter: \"Lass mich doch deine Herrlichkeit sehen!\"" },
      { number: 19, text: "Er antwortete: \"Ich selbst werde all meine Güte an dir vorüberziehen lassen und den Namen Jahwe vor dir ausrufen. Ich entscheide, wem ich gnädig bin, und schenke mein Erbarmen, wem ich will.\"*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 9,15"] },
      { number: 20, text: "Dann sagte er: \"Du kannst mein Gesicht nicht sehen, denn kein Mensch, der mich sieht, bleibt am Leben.\"" },
      { number: 21, text: "Jahwe sagte weiter: \"Pass auf! Hier auf dem Felsen ist ein Platz bei mir. Da kannst du stehen." },
      { number: 22, text: "Wenn dann meine Herrlichkeit vorüberzieht, werde ich dich in einen Felsspalt stellen und meine Hand als Schutz über dich halten, bis ich vorüber bin." },
      { number: 23, text: "Dann werde ich meine Hand wegnehmen, und du kannst mich von hinten sehen. Aber mein Gesicht darf nicht gesehen werden.\"" },
    ] },
    { number: 34, verses: [
      { number: 1, text: "Dann sagte Jahwe zu Mose: \"Hau dir zwei Steintafeln zurecht wie die ersten, die du zerbrochen hast! Ich werde die Worte darauf schreiben, die schon auf den ersten Tafeln standen.", heading: "Die neuen Gesetzestafeln" },
      { number: 2, text: "Halte dich für morgen bereit! Morgen früh steigst du auf den Berg Sinai und erwartest mich auf dem Gipfel." },
      { number: 3, text: "Es darf niemand mit dir heraufkommen. Es darf überhaupt niemand auf dem Berg gesehen werden. Auch das Vieh darf nicht an seinem Fuß weiden.\"" },
      { number: 4, text: "So hieb Mose zwei Tafeln aus Stein zurecht wie die ersten. Am nächsten Morgen stand er früh auf und stieg mit den Tafeln in der Hand auf den Berg, wie Jahwe es ihm befohlen hatte." },
      { number: 5, text: "Da kam Jahwe in einer Wolke auf den Berg herab, stellte sich an die Seite von Mose und rief den Namen Jahwes aus." },
      { number: 6, text: "Dann zog er vor seinen Augen vorbei und rief: \"Jahwe, Jahwe, Gott: barmherzig und gnädig, langmütig und reich an Güte und Treue," },
      { number: 7, text: "der Gnade über tausend Generationen hin erweist, der Schuld, Vergehen und Sünde vergibt, aber keineswegs ungestraft lässt, der die Schuld der Väter an den Kindern und Enkeln bis in die dritte und vierte Generation verfolgt.\"" },
      { number: 8, text: "Sofort warf sich Mose auf die Erde und betete an." },
      { number: 9, text: "Er sagte: \"Herr, wenn du mir deine Gunst geschenkt hast, dann sei in unserer Mitte. Wenn es auch ein widerspenstiges Volk ist, so vergib uns doch unsere Schuld und Sünde und nimm uns als Eigentum an.\"" },
      { number: 10, text: "Da sagte er: \"Hiermit schließe ich einen Bund: Vor deinem ganzen Volk werde ich Wunder tun, wie sie bisher unter allen Völkern der Erde noch nie vollbracht worden sind. Das ganze Volk, in dessen Mitte du stehst, soll das Tun Jahwes sehen. Es wird furchterregend sein, was ich für dich tun werde." },
      { number: 11, text: "Merk dir genau, was ich dir heute befehle! Ich werde die Amoriter, Kanaaniter, Hetiter, Perisiter, Hiwiter und Jebusiter vor dir vertreiben." },
      { number: 12, text: "Hüte dich, mit den Bewohnern des Landes, in das du kommen wirst, einen Bund zu schließen. Sie werden dir sonst eine Falle sein, wenn sie unter dir leben." },
      { number: 13, text: "Du sollst vielmehr ihre Altäre niederreißen, ihre Steinmale zerschlagen und ihre Aschera-Pfähle umhauen." },
      { number: 14, text: "Du darfst dich vor keinem anderen Gott anbetend niederwerfen, denn Jahwe ist ein eifersüchtiger Gott und heißt auch 'der Eifersüchtige'!" },
      { number: 15, text: "Hüte dich, einen Bund mit den Bewohnern des Landes zu schließen! Denn sonst könnten sie dich einladen, wenn sie sich ihren Göttern anbieten*, wenn sie ihnen opfern und ihre Opfermahlzeiten feiern.", footnotes: ["Sich Göttern anbieten. Wörtlich: nachhuren."] },
      { number: 16, text: "Vielleicht würdest du deine Söhne mit ihren Töchtern verheiraten; und wenn ihre Töchter sich dann ihren Göttern anbieten, könnten sie deine Söhne verführen, das ebenfalls zu tun." },
      { number: 17, text: "Du sollst dir auch keine Götter aus Metall gießen!" },
      { number: 18, text: "Das Fest der ungesäuerten Brote sollst du halten. Zur festgesetzten Zeit im Ährenmonat sollst du sieben Tage lang ungesäuerte Brotfladen essen, wie ich es dir befohlen habe. Denn in diesem Monat bist du aus Ägypten gezogen." },
      { number: 19, text: "Alles, was das erste Mal aus einem Mutterschoß kommt, gehört mir! Auch die Erstgeburt von deinen Rindern, Schafen und Ziegen, wenn es männliche Tiere sind." },
      { number: 20, text: "Die Erstgeburt eines Esels sollst du mit einem Lamm auslösen. Wenn du das nicht tun willst, musst du dem Fohlen das Genick brechen. Auch deine erstgeborenen Söhne sollst du auslösen. Keiner soll mit leeren Händen vor mir erscheinen." },
      { number: 21, text: "Sechs Tage sollst du arbeiten und am siebten Tag ruhen. Das gilt auch für die Zeit des Pflügens und des Erntens." },
      { number: 22, text: "Auch das Erntefest sollst du feiern, wenn du das erste Getreide einbringst, und im Herbst das Wein- und Obstlesefest." },
      { number: 23, text: "Dreimal im Jahr sollen alle deine Männer vor dem Herrn, vor Jahwe, dem Gott Israels, erscheinen." },
      { number: 24, text: "In dieser Zeit wird niemand in dein Land einfallen, denn ich werde die Völker vor dir vertrieben und deine Grenzen erweitert haben." },
      { number: 25, text: "Das Blut meiner Schlachtopfer darf nicht zusammen mit Backwaren aus Sauerteig dargebracht werden. Das Schlachtopfer vom Passafest darf nicht bis zum nächsten Morgen aufbewahrt bleiben." },
      { number: 26, text: "Die Besten von deinen ersten Feldfrüchten sollst du in das Haus Jahwes, deines Gottes, bringen. Ein Böckchen darfst du nicht in der Milch seiner Mutter kochen.\"" },
      { number: 27, text: "Dann sagte Jahwe zu Mose: \"Schreib alles auf, was ich dir gesagt habe. Denn auf dieser Grundlage schließe ich mit dir und mit Israel einen Bund.\"" },
      { number: 28, text: "Vierzig Tage und Nächte blieb Mose dort bei Jahwe, und dieser schrieb die zehn Gebote des Bundes auf die Steintafeln. Während der ganzen Zeit aß und trank Mose nichts." },
      { number: 29, text: "Als Mose vom Berg herabstieg, hatte er die beiden Tafeln mit dem Bundesgesetz in der Hand. Er wusste aber nicht, dass durch das Reden mit Gott seine Gesichtshaut zu leuchten begonnen hatte.", heading: "Gottes Herrlichkeit auf Moses Gesicht" },
      { number: 30, text: "Aaron und alle Israeliten sahen das Leuchten auf der Gesichtshaut Moses und fürchteten sich, in seine Nähe zu kommen." },
      { number: 31, text: "Erst als Mose sie rief, kamen Aaron und die führenden Männer der Gemeinschaft zu ihm, und Mose konnte mit ihnen reden." },
      { number: 32, text: "Dann kamen auch die anderen Israeliten. Mose gab ihnen alle Anordnungen weiter, die Jahwe ihm auf dem Berg Sinai gegeben hatte." },
      { number: 33, text: "Als er ihnen alles gesagt hatte, verhüllte er sein Gesicht." },
      { number: 34, text: "Immer wenn er ins Zelt ging, um mit Jahwe zu reden, nahm er die Verhüllung ab, bis er wieder hinausging. Draußen sagte er den Israeliten, was ihm aufgetragen war." },
      { number: 35, text: "Da sahen sie das Leuchten auf der Gesichtshaut von Mose. Dann verhüllte Mose sein Gesicht, bis er wieder ins Zelt ging, um mit Gott zu reden." },
    ] },
    { number: 35, verses: [
      { number: 1, text: "Mose rief die ganze Gemeinschaft der Israeliten zusammen und sagte zu ihnen: \"Folgendes hat Jahwe euch befohlen zu tun:", heading: "Das Sabbatgebot" },
      { number: 2, text: "Sechs Tage sollt ihr arbeiten, aber der siebte Tag soll euch heilig sein. Da feiert ihr einen Sabbat völliger Ruhe zur Ehre Jahwes. Wer an diesem Tag arbeitet, muss getötet werden." },
      { number: 3, text: "Ihr dürft am Sabbat auch kein Herdfeuer anzünden, egal, wo ihr wohnt.\"" },
      { number: 4, text: "Weiter sagte Mose der ganzen Gemeinschaft der Israeliten: \"Folgendes hat Jahwe euch befohlen:", heading: "Spenden für das Heiligtum" },
      { number: 5, text: "Bringt Jahwe eine freiwillige Gabe aus eurem Besitz! Jeder, der es gern gibt, soll diese Opfergabe für Jahwe herbringen. Es kann Gold, Silber oder Bronze sein," },
      { number: 6, text: "blauer oder roter Purpur, Karmesinstoff, Leinen oder Ziegenhaar." },
      { number: 7, text: "Ihr könnt rot gefärbte Felle von Schafböcken bringen, Tachasch-Häute und Akazienholz," },
      { number: 8, text: "Öl für den Leuchter, wohlriechende Zutaten für das Salböl und die Weihrauchmischung," },
      { number: 9, text: "dazu Edelsteine und Onyx zum Schmuck für das Efod und die Brusttasche." },
      { number: 10, text: "Jeder kunstbegabte Handwerker soll kommen und alles anfertigen, was Jahwe befohlen hat:" },
      { number: 11, text: "die Wohnung, ihr Zeltdach und ihre Hülle, ihre Haken, Bretter, Riegel, Säulen und Sockel," },
      { number: 12, text: "die Bundeslade und ihre Stangen, die Deckplatte und den alles verhüllenden Vorhang;" },
      { number: 13, text: "den Tisch mit Stangen und Zubehör für die heiligen Brote;" },
      { number: 14, text: "den Leuchter mit seinen Lampen und allem Zubehör und das Öl für die Lampen;" },
      { number: 15, text: "auch den Räucheraltar mit seinen Stangen, das Salböl und die Weihrauchmischung und den Eingangsvorhang für das Zelt;" },
      { number: 16, text: "den Brandopferaltar mit seinem Gitter aus Bronze, seinen Stangen und allem Zubehör, das Wasserbecken und sein Gestell;" },
      { number: 17, text: "die Behänge für den Vorhof, die Säulen und ihre Sockel und den Vorhang für den Eingang zum Vorhof;" },
      { number: 18, text: "die Pflöcke für die Wohnung und den Vorhof mit den dazugehörigen Seilen;" },
      { number: 19, text: "die Kleidung für den Dienst im Heiligtum, die heiligen Gewänder, die Aaron und seine Söhne beim Priesterdienst tragen sollen.\"" },
      { number: 20, text: "Da ging die versammelte Gemeinschaft der Israeliten von Mose weg." },
      { number: 21, text: "Dann kamen alle wieder, die gern etwas geben wollten und die es aus innerem Antrieb taten. Sie brachten ein freiwilliges Opfer für Jahwe. Es war für die Arbeit am Zelt der Gottesbegegnung und den ganzen Dienst darin und für die heiligen Gewänder." },
      { number: 22, text: "Männer und Frauen brachten bereitwillig Spangen, Ohr- und Siegelringe, Halskettchen und goldene Schmucksachen. Jeder brachte das Gold hin- und herschwingend vor Jahwe." },
      { number: 23, text: "Und jeder, bei dem sich blauer oder roter Purpur vorfand, Karmesinstoff, Leinen oder Ziegenhaar, rot gefärbte Felle von Schafböcken oder Tachasch-Häute, brachte es herbei." },
      { number: 24, text: "Jeder, der Jahwe eine Opfergabe aus Silber oder Bronze geben wollte, brachte sie herbei; und jeder, bei dem sich Akazienholz vorfand, das für irgendetwas beim Bau gebraucht werden konnte, brachte es." },
      { number: 25, text: "Alle begabten Frauen spannen in Handarbeit und brachten das Gesponnene: blauen und roten Purpur, Karmesinstoff und Leinen." },
      { number: 26, text: "Und begabte Frauen, die sich dazu angespornt fühlten, spannen Ziegenhaar." },
      { number: 27, text: "Die führenden Männer brachten Onyx und andere Edelsteine für das Efod und die Brusttasche," },
      { number: 28, text: "außerdem Balsam, Öl für den Leuchter und Duftstoffe für das Salböl und die Weihrauchmischung." },
      { number: 29, text: "Alle Männer und Frauen Israels, die gern zu dem Werk beitragen wollten, das Jahwe durch Mose angeordnet hatte, brachten Jahwe eine freiwillige Gabe." },
      { number: 30, text: "Nun sagte Mose zu den Israeliten: \"Seht, Jahwe hat Bezalel Ben-Uri, den Enkel von Hur aus dem Stamm Juda, berufen.", heading: "Mose beauftragt die Kunsthandwerker" },
      { number: 31, text: "Er hat ihn mit dem Geist Gottes erfüllt, mit Weisheit und Verstand und kunsthandwerklichem Geschick." },
      { number: 32, text: "Er kann Pläne entwerfen und danach Gegenstände aus Gold, Silber und Bronze anfertigen." },
      { number: 33, text: "Er kann Edelsteine schneiden und einfassen, er versteht sich auf Holzschnitzerei und ist in jeder künstlerischen Technik erfahren." },
      { number: 34, text: "Dazu hat Jahwe ihm und Oholiab Ben-Ahisamach aus dem Stamm Dan die Gabe geschenkt, andere zu unterweisen." },
      { number: 35, text: "Beiden hat er die Fähigkeit gegeben, jeden Entwurf eines Kunsthandwerkers, Kunststickers oder Buntwirkers ausführen zu können, ob es um blauen und roten Purpur, Karmesinstoff oder Leinen geht, um Weberei oder Stickerei. Sie können alle möglichen Entwürfe machen und sie ausführen." },
    ] },
    { number: 36, verses: [
      { number: 1, text: "Bezalel und Oholiab und alle begabten Männer, denen Jahwe Weisheit und Einsicht gegeben hat, sollen nun alle Arbeiten zum Bau des Heiligtums ausführen, wie es Jahwe befohlen hat.\"", heading: "Gottes Heiligtum wird gebaut (36-40)\nDie Wohnung" },
      { number: 2, text: "Mose berief also Bezalel und Oholiab und jeden begabten Mann, dem Jahwe Weisheit und Einsicht gegeben hatte und den sein Herz antrieb, sich ans Werk zu machen." },
      { number: 3, text: "Sie nahmen von Mose alle freiwilligen Gaben der Israeliten entgegen, die für den Bau des Heiligtums gegeben worden waren. Auch weiterhin brachten die Leute Morgen für Morgen freiwillige Gaben." },
      { number: 4, text: "Da ließen die Kunsthandwerker, die das Heiligtum errichten sollten, ihre Arbeit liegen," },
      { number: 5, text: "gingen zu Mose und sagten: \"Die Leute bringen zu viel. Es ist mehr da, als für die Arbeit benötigt wird, die uns Jahwe aufgetragen hat.\"" },
      { number: 6, text: "Darauf ließ Mose im Lager ausrufen: \"Ihr Männer und Frauen, ihr braucht nichts mehr für den Bau des Heiligtums herzustellen!\" So hörte das Volk auf, noch mehr zu bringen." },
      { number: 7, text: "Es war bereits mehr als genug Material für alle Arbeiten vorhanden." },
      { number: 8, text: "So machten sich alle, die etwas davon verstanden, an die Arbeit. Sie stellten die Wohnung aus zehn Zeltdecken her. Die Zeltbahnen waren aus gezwirnten Leinenfäden gewebt und künstlerisch mit Cherubim aus blauer, roter und karmesinroter Wolle bestickt." },
      { number: 9, text: "Jede dieser Zeltbahnen war vierzehn Meter lang und zwei Meter breit." },
      { number: 10, text: "Je fünf Zeltdecken vernähte man an den Längsseiten miteinander." },
      { number: 11, text: "An den beiden Längsseiten der so entstandenen Stücke brachte man Schlaufen aus blauem Purpur an," },
      { number: 12, text: "je fünfzig, die sich genau gegenüber standen, wenn man die Stücke nebeneinander legte." },
      { number: 13, text: "Dann wurden fünfzig Haken aus Gold hergestellt, mit denen man beide Zeltdecken verbinden konnte, sodass es ein Ganzes wurde." },
      { number: 14, text: "Die Männer webten elf Zeltbahnen aus Ziegenhaar." },
      { number: 15, text: "Jede einzelne Bahn war fünfzehn Meter lang und zwei Meter breit." },
      { number: 16, text: "Sie verbanden einmal fünf und einmal sechs dieser Zeltbahnen miteinander." },
      { number: 17, text: "Am Ende der beiden großen Stücke brachten sie je fünfzig Schlaufen an." },
      { number: 18, text: "Dann stellten sie fünfzig Bronzehaken her und fügten sie in die Schlaufen ein, sodass es ein Ganzes wurde." },
      { number: 19, text: "Sie fertigten schließlich noch eine Decke aus rot gefärbten Fellen von Schafböcken an und oben darüber eine Decke aus Tachasch-Häuten." },
      { number: 20, text: "Die Bretter für die Wohnung machten sie aus Akazienholz. Sie standen aufrecht." },
      { number: 21, text: "Jedes Brett war fünf Meter lang, dreiviertel Meter breit" },
      { number: 22, text: "und hatte unten zwei nebeneinanderstehende Zapfen." },
      { number: 23, text: "Zwanzig Bretter bildeten die Südseite der Wohnung." },
      { number: 24, text: "Unter jedem Brett waren zwei Bodenplatten aus Silber angebracht, für jeden Zapfen eine, also insgesamt vierzig." },
      { number: 25, text: "Auch die andere Längsseite der Wohnung, die Nordseite, bestand aus zwanzig Brettern" },
      { number: 26, text: "mit ihren vierzig silbernen Bodenplatten, je zwei unter einem Brett." },
      { number: 27, text: "Für die Rückwand nach Westen machten sie sechs Bretter," },
      { number: 28, text: "dazu die zwei Bretter für die Ecken an der Rückseite." },
      { number: 29, text: "Sie verbanden die Rückwand mit den Seitenwänden." },
      { number: 30, text: "Es waren also acht Bretter mit sechzehn silbernen Bodenplatten, zwei unter jedem Brett." },
      { number: 31, text: "Dann fertigten sie Riegel aus Akazienholz an, um die Bretter der Wohnung zusammenzuhalten," },
      { number: 32, text: "je fünf für die beiden Längsseiten und fünf für die nach Westen gerichtete Rückseite." },
      { number: 33, text: "Der jeweils mittlere Riegel lief in der Mitte der Bretter von einem Ende bis zum anderen durch." },
      { number: 34, text: "Die Bretter selbst wurden mit Gold überzogen, ebenso die Riegel. Die Ösen für die Riegel wurden aus Gold hergestellt." },
      { number: 35, text: "Dann fertigten sie den Vorhang aus gezwirntem Leinen an und bestickten ihn künstlerisch mit Cherubim aus blauer, roter und karmesinroter Wolle." },
      { number: 36, text: "Dazu machten sie vier Säulen aus Akazienholz und überzogen sie mit Gold. Auch ihre Haken waren aus Gold. Sie standen auf silbernen Bodenplatten." },
      { number: 37, text: "Für den Eingang des Zeltes fertigten sie einen Vorhang aus gezwirntem Leinen, worin blaue, rote und karmesinrote Wollfäden eingewebt waren." },
      { number: 38, text: "Er wurde an fünf Säulen aus Akazienholz gehängt, deren Köpfe und Bindestäbe mit Gold überzogen waren. Die Bodenplatten waren hier aus Bronze." },
    ] },
    { number: 37, verses: [
      { number: 1, text: "Die Lade stellte Bezalel aus Akazienholz her. Sie war eineinviertel Meter lang, dreiviertel Meter breit und ebenso hoch.", heading: "Die Bundeslade" },
      { number: 2, text: "Innen und außen überzog er sie mit reinem Gold und verzierte sie oben mit einer Goldleiste." },
      { number: 3, text: "Dann goss er vier Ringe aus Gold und machte sie so an den vier Ecken fest, dass an jeder Längsseite zwei Ringe waren." },
      { number: 4, text: "Er fertigte Stangen aus Akazienholz an und überzog sie mit Gold." },
      { number: 5, text: "Diese Stangen steckte er in die Ringe an der Längsseite, damit man die Lade tragen konnte." },
      { number: 6, text: "Dann stellte er eine Deckplatte aus reinem Gold her, eineinviertel Meter lang und dreiviertel Meter breit." },
      { number: 7, text: "An beide Enden dieser Platte stellte er zwei Cherubim-Figuren, die aus getriebenem Gold gefertigt waren." },
      { number: 8, text: "Sie standen einander gegenüber und waren fest mit der Platte verbunden." },
      { number: 9, text: "Die Cherubim hielten ihre Flügel nach oben über die Deckplatte ausgebreitet. Ihre Gesichter waren einander zugewandt, und ihr Blick war auf die Deckplatte gerichtet." },
      { number: 10, text: "Den Tisch machte er aus Akazienholz, einen Meter lang, einen halben Meter breit und dreiviertel Meter hoch.", heading: "Der Tisch" },
      { number: 11, text: "Er überzog ihn mit reinem Gold und fasste ihn mit einer goldenen Schmuckleiste ein." },
      { number: 12, text: "Dazu machte er einen Rahmen von zehn Zentimetern Höhe, der ebenfalls von einer goldenen Schmuckleiste eingefasst war." },
      { number: 13, text: "Dann fertigte er vier goldene Ringe für ihn an und befestigte sie an den Kanten der vier Füße." },
      { number: 14, text: "Die Ringe waren dicht an dem Rahmen befestigt und dienten als Ösen für die Stangen, damit man den Tisch tragen konnte." },
      { number: 15, text: "Die Tragstangen machte er aus Akazienholz und überzog sie mit Gold." },
      { number: 16, text: "Dann fertigte er die Schüsseln und Schalen, die Kannen und Kellen an, die für das Trankopfer gebraucht werden, alles aus reinem Gold." },
      { number: 17, text: "Den Leuchter machte er aus reinem Gold. Er war mit seinem Fußgestell, seinem Schaft, seinen Kelchen, Knäufen und Blüten aus einem Stück getrieben.", heading: "Der Leuchter" },
      { number: 18, text: "Von seinem Schaft gingen je drei Arme nach beiden Seiten aus." },
      { number: 19, text: "Jeder von ihnen war mit drei Kelchen in Form von Mandelblüten verziert, jede mit einem Knauf darunter." },
      { number: 20, text: "Auf dem Schaft selbst befanden sich vier solcher Blütenkelche mit Knauf," },
      { number: 21, text: "drei davon unter den Ansatzstellen der Armpaare." },
      { number: 22, text: "Der ganze Leuchter mit seinen Knäufen und Armen war aus einem Stück gearbeitet und bestand aus reinem Gold." },
      { number: 23, text: "Auch seine sieben Lampen, seine Dochtscheren und Pfännchen waren aus reinem Gold." },
      { number: 24, text: "Aus einem Block reinen Goldes fertigte er ihn und seine Geräte an." },
      { number: 25, text: "Er machte auch einen Räucheraltar aus Akazienholz. Der war viereckig, einen halben Meter lang, ebenso breit und einen Meter hoch. Seine Hörner bestanden aus einem Stück mit ihm.", heading: "Der Räucheraltar" },
      { number: 26, text: "Dann überzog er ihn mit reinem Gold: seine Platte, seine Wände und seine Hörner, und brachte ringsum eine goldene Leiste an." },
      { number: 27, text: "Unter dieser Leiste waren an beiden Seiten je zwei goldene Ringe angebracht, durch die Tragstangen gesteckt werden konnten." },
      { number: 28, text: "Die Stangen wurden aus Akazienholz gemacht und mit Gold überzogen." },
      { number: 29, text: "Von kundigen Salbenmischern ließ er das heilige Salböl und den wohlriechenden Weihrauch herstellen." },
    ] },
    { number: 38, verses: [
      { number: 1, text: "Den Brandopferaltar fertigte er aus Akazienholz. Er war viereckig, zweieinhalb Meter lang, ebenso breit und eineinhalb Meter hoch.", heading: "Der Brandopferaltar" },
      { number: 2, text: "An seinen vier oberen Ecken ließ er Hörner aufragen, die aus einem Stück mit dem Altar bestanden. Dann beschlug er ihn mit Bronzeblechen." },
      { number: 3, text: "Auch die Töpfe, Schaufeln und Schalen, die Fleischgabeln und Feuerbecken waren aus Bronze." },
      { number: 4, text: "Er fertigte auch ein netzartiges Gitter aus Bronze an, das von unten her in die Einfassung des Altars geführt wurde und bis zu seiner halben Höhe reichte." },
      { number: 5, text: "Dann goss er vier Ringe und befestigte sie an seinen Ecken. Sie dienten als Ösen für die Tragstangen," },
      { number: 6, text: "die er aus Akazienholz machte und mit Bronze überzog." },
      { number: 7, text: "Die Stangen wurden in die Ringe an den Seiten des Altars gesteckt, damit er so getragen werden konnte. Er war aus Brettern zusammengefügt und innen hohl." },
      { number: 8, text: "Dann stellte er aus den Spiegeln* der Frauen, die sich am Eingang vom Zelt* der Gottesbegegnung zusammenscharten*, ein Wasserbecken aus Bronze und dazu einen bronzenen Untersatz her.", heading: "Das Wasserbecken", footnotes: ["Spiegel bestanden im Altertum aus poliertem Metall, hier aus Bronze.", "Eingang vom Zelt meint hier wie auch an einigen anderen Stellen nicht den Eingang zum Heiligtum, sondern den Platz vor dem Eingang zum Vorhof, wo sich auch das ganze Volk versammeln konnte (3. Mose 8,3; 4. Mose 10,3; 25,6).", "Frauen … zusammenscharten. Das Verb bedeutet eigentlich: kämpfen gegen, in den Krieg ziehen. Was diese Frauen, die auch in 1. Samuel 2,22 erwähnt werden, wirklich taten, ist unbekannt."] },
      { number: 9, text: "Als Abgrenzung des Vorhofs an der Südseite ließ er auf fünfzig Metern Länge Planen aus gezwirnter Leinwand aufhängen,", heading: "Der Vorhof" },
      { number: 10, text: "die von zwanzig Säulen gehalten wurden. Die Säulen hatten Sockel aus Bronze. Die Haken und Verbindungsstangen waren jedoch aus Silber." },
      { number: 11, text: "Genauso war es bei der fünfzig Meter langen Nordseite." },
      { number: 12, text: "Auf der Westseite war der Vorhof 25 Meter breit. Seine Planen wurden von zehn Säulen gehalten. Auch sie hatten Sockel aus Bronze und Haken und Verbindungsstangen aus Silber." },
      { number: 13, text: "Auch die dem Sonnenaufgang zugekehrte Ostseite war 25 Meter breit." },
      { number: 14, text: "Links vom Tor waren Planen auf siebeneinhalb Meter Länge an drei Säulen aufgehängt" },
      { number: 15, text: "und ebenso rechts davon." },
      { number: 16, text: "Die Planen waren aus gezwirnter Leinwand gefertigt." },
      { number: 17, text: "Alle Säulen des Vorhofs hatten Verbindungsstangen und Haken aus Silber und Sockel aus Bronze. Ihre Köpfe waren mit Silber überzogen." },
      { number: 18, text: "Das Tor des Vorhofs war eine Plane von zehn Meter Breite und zweieinhalb Meter Höhe, die aus gezwirntem Leinen bestand, worin blaue, rote und karmesinrote Wollfäden eingewebt waren." },
      { number: 19, text: "Sie war an vier Säulen aufgehängt, deren Sockel aus Bronze bestanden. Die Köpfe und Verbindungsstangen waren jedoch mit Silber überzogen, und die Haken bestanden aus Silber." },
      { number: 20, text: "Alle Zeltpflöcke für die Wohnung und den Vorhof waren aus Bronze." },
      { number: 21, text: "Es folgt eine Liste des Materials, das für die Wohnung des Bundesbuches* verwendet wurde. Man hatte sie auf Anweisung Moses unter der Leitung von Itamar, dem Sohn des Priesters Aaron, aufgestellt.", heading: "Das verwendete Material", footnotes: ["Wohnung des Bundesbuches. Anderer Name für Zelt der Gottesbegegnung."] },
      { number: 22, text: "Bezalel Ben-Uri, der Enkel von Hur aus dem Stamm Juda, hatte alle Arbeiten ausgeführt, die Jahwe Mose befohlen hatte." },
      { number: 23, text: "Unterstützt wurde er von Oholiab Ben-Ahisamach aus dem Stamm Dan, einem Kunsthandwerker, der sich besonders auf das kunstfertige Weben und Sticken mit blauer, roter und karmesinroter Wolle und gezwirntem Leinen verstand." },
      { number: 24, text: "Die Goldmenge, die zum Bau des Heiligtums gespendet und verarbeitet worden war, betrug nach dem Gewicht des Heiligtums 1009 Kilogramm*.", footnotes: ["1009 Kilogramm. Wörtlich: 29 Talente und 730 Schekel. Ein Talent hatte 3000 Schekel. Ein Schekel wog etwa 11,5 Gramm."] },
      { number: 25, text: "Das Silber von den Männern, die gemustert worden waren, wog insgesamt 3470 Kilogramm," },
      { number: 26, text: "es war das halbe Silberstück für die 603 550 Männer der Gemeinschaft, die zwanzig Jahre und älter waren.*", footnotes: ["Siehe 2. Mose 30,13!"] },
      { number: 27, text: "3450 Kilogramm waren zum Gießen der 100 silbernen Bodenplatten verwendet worden, die die Wände des Heiligtums und die Säulen für die Vorhänge trugen." },
      { number: 28, text: "Aus den übrig gebliebenen 20 Kilogramm wurden die Haken für die Säulen hergestellt und außerdem die Köpfe der Säulen und die Tragstangen versilbert." },
      { number: 29, text: "Die gespendete Kupfermenge hatte ein Gewicht von 2443 Kilogramm." },
      { number: 30, text: "Daraus wurden die Sockel für den Eingang vom Zelt der Gottesbegegnung gemacht, der Metallüberzug für den Altar, sein Bronzegitter und alle seine Geräte," },
      { number: 31, text: "die Sockel für die Säulen rund um den Vorhof und für seinen Eingang, sowie die Pflöcke für das Zelt und die Abgrenzung des Vorhofs." },
    ] },
    { number: 39, verses: [
      { number: 1, text: "Nach der Anweisung, die Mose von Jahwe erhalten hatte, wurden die heiligen Gewänder hergestellt, wie sie Aaron für den Dienst im Heiligtum benötigte. Man nahm dazu blauen und roten Purpur und Karmesinstoff*.", heading: "Die Kleidung der Priester", footnotes: ["Karmesinstoff. Siehe Fußnote zu 2. Chronik 2,13!"] },
      { number: 2, text: "Das Efod machten sie aus Gold, blauer, roter und karmesinroter Wolle und gezwirntem Leinen.", heading: "Das Efod" },
      { number: 3, text: "Sie hämmerten dünne Goldbleche und zerschnitten sie zu schmalen Streifen, um sie künstlerisch in das Material einzuarbeiten." },
      { number: 4, text: "Sie machten auch die beiden mit ihm verbundenen Schulterstücke" },
      { number: 5, text: "und den Gürtel, mit dem es befestigt wird. Er bestand aus demselben Material und war mit ihm verbunden, so, wie es Jahwe Mose befohlen hatte." },
      { number: 6, text: "Dann fassten sie die zwei Onyxsteine in Gold, gravierten in die Steine die Namen der Söhne Israels" },
      { number: 7, text: "und brachten sie auf den Schulterstücken des Efods an – die Steine zur Erinnerung an die Israeliten; so wie Jahwe es Mose befohlen hatte." },
      { number: 8, text: "Die Brusttasche machte man wie das Efod aus gezwirntem Leinen. Sie wurde mit Goldfäden, blauer, roter und karmesinroter Wolle künstlerisch bestickt.", heading: "Das Brustschild" },
      { number: 9, text: "Sie war quadratisch, 25 mal 25 Zentimeter groß, und doppelt gelegt." },
      { number: 10, text: "Dann wurde sie mit Edelsteinen in vier Reihen besetzt. In der ersten Reihe ein Karneol, ein Topas und ein Smaragd;" },
      { number: 11, text: "in der zweiten Reihe ein Rubin, ein Saphir und ein Jaspis;" },
      { number: 12, text: "in der dritten Reihe ein Hyazinth, ein Achat und ein Amethyst;" },
      { number: 13, text: "und in der vierten Reihe ein Türkis, ein Onyx und ein Nephrit. Alle waren mit Gold eingefasst." },
      { number: 14, text: "In die Steine waren die Namen der zwölf Söhne Israels eingraviert, in jedem Stein ein Name für einen Stamm." },
      { number: 15, text: "Dann wurden zwei gedrehte Kettenschnüre aus reinem Gold für das Brustschild hergestellt." },
      { number: 16, text: "An den beiden oberen Ecken des Brustschilds wurden zwei goldene Ringe angebracht" },
      { number: 17, text: "und die beiden goldenen Schnüre dort befestigt." },
      { number: 18, text: "Die Enden dieser beiden Schnüre wurden an der Vorderseite der Schulterstücke befestigt." },
      { number: 19, text: "Auch an den beiden unteren Enden der Brusttasche wurden zwei goldene Ringe angebracht," },
      { number: 20, text: "ebenso an den beiden Schulterstücken des Efods. Sie wurden dicht an ihrer Naht, aber oberhalb des Gürtels vom Efod befestigt." },
      { number: 21, text: "Man verknüpfte das Brustschild mit einer blauen Schnur von seinen Ringen aus mit den Ringen des Efods, sodass es über dem Gurt des Efods saß und sich nicht verschieben konnte; so wie Jahwe es Mose befohlen hatte." },
      { number: 22, text: "Das Obergewand, das unter dem Efod getragen wurde, bestand aus purpurblauem Stoff.", heading: "Andere Kleidungsstücke" },
      { number: 23, text: "Die Öffnung für den Kopf in der Mitte war wie bei der Halseinfassung eines Panzerhemdes mit einer gewebten Borte eingefasst, damit sie nicht einriss." },
      { number: 24, text: "Am unteren Saum waren Granatäpfel aus blauer, roter und karmesinroter Wolle befestigt." },
      { number: 25, text: "Dazwischen hatte man goldene Glöckchen angebracht," },
      { number: 26, text: "sodass um den ganzen Saum herum immer ein Glöckchen auf einen Granatapfel folgte. In diesem Gewand sollte der Dienst im Heiligtum verrichtet werden, wie Jahwe es Mose befohlen hatte." },
      { number: 27, text: "Weiter machten sie aus Leinen für Aaron und seine Söhne Hemden," },
      { number: 28, text: "Kopfbünde, turbanartige Kopfbedeckungen und Kniehosen." },
      { number: 29, text: "Auch der bunt gewirkte Gürtel bestand aus gezwirntem Leinen; so wie Jahwe es Mose befohlen hatte." },
      { number: 30, text: "Schließlich machten sie das Stirnblatt, das heilige Diadem, aus reinem Gold und gravierten darauf ein: \"Heilig für Jahwe\"." },
      { number: 31, text: "Das wurde mit einer blauen Schnur vorn am Kopfbund befestigt, wie Jahwe es Mose befohlen hatte." },
      { number: 32, text: "So wurde die ganze Arbeit für die Wohnung, das Zelt der Gottesbegegnung, vollendet. Die Israeliten machten es genauso, wie Jahwe es Mose befohlen hatte.", heading: "Mose besichtigt das Heiligtum" },
      { number: 33, text: "Dann brachten sie alles zu Mose: das Zelt und alles, was dazu gehörte; seine Haken, Bretter, Riegel, Säulen und Bodenplatten," },
      { number: 34, text: "die Decke aus rot gefärbten Fellen von Schafböcken, die Decke aus Tachasch-Häuten, den Vorhang, der alles verhüllte," },
      { number: 35, text: "die Lade für das Bundesgesetz, ihre Tragstangen und die Deckplatte," },
      { number: 36, text: "den Tisch für die geweihten Brote mit allem, was dazu gehört;" },
      { number: 37, text: "den Leuchter mit seinen Lampen, dem Öl und allem Zubehör," },
      { number: 38, text: "den goldenen Altar, das Salböl, den Weihrauch und den Vorhang für den Eingang," },
      { number: 39, text: "den Bronzealtar, sein Bronzegitter, seine Tragstangen und alles Zubehör, das Becken und sein Gestell," },
      { number: 40, text: "die Planen für den Vorhof, dazu die Säulen und Bodenplatten, die Plane für den Eingang zum Vorhof, dazu die Seile, Pflöcke und was sonst noch dazugehört;" },
      { number: 41, text: "die gewirkten Gewänder für den Priesterdienst im Heiligtum, die heiligen Gewänder für Aaron und die für seine Söhne." },
      { number: 42, text: "Die Israeliten hatten alles genauso gemacht, wie Jahwe es Mose befohlen hatte." },
      { number: 43, text: "Mose sah sich alles an, was sie gemacht hatten. Es war alles genauso geworden, wie Jahwe es befohlen hatte. Da segnete Mose sie." },
    ] },
    { number: 40, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Der Aufbau des Heiligtums" },
      { number: 2, text: "\"Am 1. April* sollst du die Wohnung aufrichten, das Zelt der Gottesbegegnung.", footnotes: ["Genau ein Jahr nach Einsetzung des Passa (2. Mose 12,2)."] },
      { number: 3, text: "Bring die Lade mit dem Bundesbuch hinein und verdecke sie mit dem Vorhang!" },
      { number: 4, text: "Dann stell den Tisch auf und richte alles her, was dazu gehört! Bring auch den Leuchter hinein und setze seine Lichtschalen darauf." },
      { number: 5, text: "Stell dann den goldenen Räucheraltar der Lade mit dem Bundesgesetz gegenüber und hänge den Vorhang am Eingang zur Wohnung auf!" },
      { number: 6, text: "Den Brandopferaltar stell vor dem Eingang zum Zelt der Gottesbegegnung auf!" },
      { number: 7, text: "Dann stell das Becken zwischen das Zelt und den Altar und füll es mit Wasser!" },
      { number: 8, text: "Errichte die Abgrenzung rings um den Vorhof und häng die Plane an seinem Eingang auf!" },
      { number: 9, text: "Nimm dann das Salböl und salbe damit die Wohnung und alles, was darin ist! Dadurch wird sie mit allem, was darin ist, heilig." },
      { number: 10, text: "Salbe auch den Brandopferaltar und alles, was dazu gehört, damit der Altar höchst heilig wird!" },
      { number: 11, text: "Salbe auch das Becken und sein Gestell und heilige es!" },
      { number: 12, text: "Dann lass Aaron und seine Söhne an den Eingang vom Zelt der Gottesbegegnung treten und wasch sie mit Wasser!" },
      { number: 13, text: "Leg Aaron die heiligen Gewänder an und salbe ihn. Dadurch heiligst du ihn zum Priesterdienst für mich." },
      { number: 14, text: "Lass auch seine Söhne herantreten und bekleide sie mit den Priesterhemden!" },
      { number: 15, text: "Salbe sie dann, wie du ihren Vater gesalbt hast, damit sie mir als Priester dienen. Damit überträgst du ihnen und ihren Nachkommen den Priesterdienst für immer.\"" },
      { number: 16, text: "Mose machte alles genauso, wie Jahwe es ihm aufgetragen hatte." },
      { number: 17, text: "Am 1. April* im zweiten Jahr nach dem Auszug aus Ägypten wurde die Wohnung aufgerichtet.", footnotes: ["Nach biblischer Chronologie (siehe Vorwort des Übersetzers) entspricht das dem Jahr 1445 v.Chr."] },
      { number: 18, text: "Mose stellte die Bretter auf die Bodenplatten, setzte ihre Riegel ein und stellte auch die Säulen auf." },
      { number: 19, text: "Dann breitete er das Zeltdach aus und legte noch die Schutzdecke darüber, wie Jahwe es ihm befohlen hatte." },
      { number: 20, text: "Anschließend legte er die Tafeln mit dem Bundesbuch in die Lade. Er steckte die Tragstangen in die Ringe und legte die Deckplatte auf." },
      { number: 21, text: "Dann brachte er die Lade in die Wohnung, hängte den verhüllenden Vorhang auf und verdeckte so den Blick zur Bundeslade." },
      { number: 22, text: "Dann trug er den Tisch in das Zelt der Gottesbegegnung und stellte ihn an die Nordseite vor den Vorhang." },
      { number: 23, text: "Schließlich legte er die Brote übereinander geschichtet darauf, wie Jahwe es ihm befohlen hatte." },
      { number: 24, text: "Den Leuchter stellte er an der Südseite im Zelt der Gottesbegegnung auf, dem Tisch gegenüber." },
      { number: 25, text: "Er legte vor Jahwe die Lichtschalen darauf, ganz wie er es ihm befohlen hatte." },
      { number: 26, text: "Dann stellte er den goldenen Altar im Zelt der Gottesbegegnung vor den inneren Vorhang" },
      { number: 27, text: "und verbrannte Weihrauch darauf, wie Jahwe es ihm befohlen hatte." },
      { number: 28, text: "Schließlich brachte er den Vorhang am Eingang der Wohnung an." },
      { number: 29, text: "Den Brandopferaltar stellte er vor den Eingang der Wohnung. Dann opferte er Brand- und Speisopfer darauf, wie Jahwe es ihm befohlen hatte." },
      { number: 30, text: "Schließlich stellte er das Becken zwischen das Zelt der Gottesbegegnung und den Altar und füllte es mit Wasser." },
      { number: 31, text: "Mose selbst, Aaron und seine Söhne wuschen Hände und Füße darin." },
      { number: 32, text: "Immer wenn sie ins Zelt der Gottesbegegnung gingen oder an den Altar traten, wuschen sie sich, wie Jahwe es Mose befohlen hatte." },
      { number: 33, text: "Zuletzt errichtete Mose die Abgrenzung des Vorhofs um die Wohnung und den Altar herum und brachte die Plane am Eingang zum Vorhof an. So vollendete Mose das ganze Werk." },
      { number: 34, text: "Da verhüllte die Wolke das Zelt der Gottesbegegnung und die Herrlichkeit Jahwes erfüllte die ganze Wohnung.", heading: "Die Herrlichkeit Jahwes" },
      { number: 35, text: "Weil die Wolke sich auf dem Zelt niedergelassen hatte und die Herrlichkeit Jahwes alles erfüllte, konnte Mose nicht hineingehen." },
      { number: 36, text: "Während der ganzen Wanderschaft richteten sich die Israeliten nach der Wolke. Immer wenn sie sich erhob, brachen sie auf;" },
      { number: 37, text: "und wenn sie ruhte, blieben sie an ihrem Lagerplatz. Wenn sie sich wieder erhob, zogen sie weiter." },
      { number: 38, text: "Bei Tag schwebte die Wolke Jahwes über der Wohnung. Bei Nacht war ein Feuer in ihr, das alle Israeliten während ihrer ganzen Wanderung sehen konnten." },
    ] },
  ],
};